/* DAWAH X — ahmad, অধ্যায় 129 · খণ্ড 129 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][129]=[[25601,25601,"","আমরা অনেক খড়ের সাথে কথা বলেছি আমরা ভাগ্যের জন্য এসেছি। মানে, বধির ছেলে তার বাগদত্তা লর্ডকে দোষারোপ করতে যাচ্ছে তার শান্তির জন্য। যদি আমার চোখে তার চোখ তাকে খুঁজে পায়, তাহলে সে তার চোখেও খুঁজে পাবে। দেখো কে লুকিয়ে ছিল আর তার রাস্তা পরিষ্কার করেছে.","‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَعْفَرٌ ‏ ‏وَعَلِيُّ بْنُ ثَابِتٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ بُرْقَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ يَعْنِي ابْنَ الْأَصَمِّ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَجَدَ جَافَى بَيْنَ يَدَيْهِ حَتَّى يَرَى مَنْ خَلْفَهُ ‏ ‏وَضَحَ ‏ ‏إِبْطَيْهِ ‏","","",""],[25602,25602,"","আমরা আমাদের বলার প্রয়োজনের কথা বলেছিলাম যে, ঈশ্বর বলেছেন, আপনার ছেলে তোমার চেয়ে ভালো হয়েছে। নাবিক লর্ডের কাছে লর্ডের ইচ্ছা পূরণ করেছে। ফিরে আসার পর রসগুলো নিয়ে আসো।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَنْظَلَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاتَتْهُ رَكْعَتَانِ قَبْلَ الْعَصْرِ فَصَلَّاهُمَا بَعْدُ ‏","","",""],[25603,25603,"","আমরা গিলানকে বলেছিলাম যে আমরা আরো কিছু ঘটেছে। আমি হয়ত তার মহান মায়ের বই অথবা তার ঊর্ধ্বতন নাম নিয়ে আপনার টাকা দিয়ে দিতে পারি। ঈশ্বরের অনুগ্রহে তিনি তার কথা দিয়েছেন। তারা বাঁশের মত বলে যে তারা ঈশ্বরের বংশধর, ঈশ্বরেরই সন্তান, সে পেয়ে গেছে। পরিষ্কার করে জেগে উঠ.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رِشْدِينُ بْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏كَثِيرَ بْنَ فَرْقَدٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ مَالِكِ بْنِ حُذَافَةَ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أُمِّهِ الْعَالِيَةِ بِنْتِ سُمَيْعٍ ‏ ‏أَوْ ‏ ‏سُبَيْعٍ ‏ ‏الشَّكُّ مِنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏مَيْمُونَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِرِجَالٍ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏يَجُرُّونَ شَاةً لَهُمْ مِثْلَ الْحِمَارِ فَقَالَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ أَخَذْتُمْ ‏ ‏إِهَابَهَا ‏ ‏قَالُوا إِنَّهَا مَيْتَةٌ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُطَهِّرُهَا الْمَاءُ ‏ ‏وَالْقَرَظُ ‏","","",""],[25604,25604,"","আমার মা আমার জীবনের সবচেয়ে ভালটা দিয়ে আমাকে বলেছিলেন যে, আমি তাকে সবচেয়ে ভালটা বলব । হয়ত সে আমাকে জিজ্ঞেস করবে যে সে নিজের জীবন নিয়ে আছে, আর তার একটাও একটা জিনিস আছে। তার সাহস নিয়ে কৌশল করে, তার প্রার্থনা আমার বাড়িতে তার কাছে আসবে, যেটা আমার ছেলে এবং নেতা কোথায়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَنْبُوذٌ ‏ ‏أَنَّ ‏ ‏أُمَّهُ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّهَا بَيْنَا هِيَ جَالِسَةٌ عِنْدَ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ دَخَلَ عَلَيْهَا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَقَالَتْ مَا لَكَ ‏ ‏شَعِثًا ‏ ‏قَالَ ‏ ‏أُمُّ عَمَّارٍ ‏ ‏مُرَجِّلَتِي ‏ ‏حَائِضٌ فَقَالَتْ أَيْ بُنَيَّ وَأَيْنَ الْحَيْضَةُ مِنْ الْيَدِ لَقَدْ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْخُلُ عَلَى إِحْدَانَا وَهِيَ مُتَّكِئَةٌ حَائِضٌ قَدْ عَلِمَ أَنَّهَا حَائِضٌ ‏ ‏فَيَتَّكِئُ ‏ ‏عَلَيْهَا ‏ ‏فَيَتْلُو الْقُرْآنَ وَهُوَ ‏ ‏مُتَّكِئٌ ‏ ‏عَلَيْهَا ‏ ‏أَوْ يَدْخُلُ عَلَيْهَا قَاعِدَةً وَهِيَ حَائِضٌ ‏ ‏فَيَتَّكِئُ ‏ ‏فِي حِجْرِهَا ‏ ‏فَيَتْلُو الْقُرْآنَ فِي حِجْرِهَا ‏ ‏وَتَقُومُ وَهِيَ حَائِضٌ فَتَبْسُطُ لَهُ ‏ ‏الْخُمْرَةَ ‏ ‏فِي مُصَلَّاهُ ‏ ‏وقَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏خُمْرَتَهُ ‏ ‏فَيُصَلِّي عَلَيْهَا فِي بَيْتِي أَيْ بُنَيَّ وَأَيْنَ الْحَيْضَةُ مِنْ الْيَدِ ‏","","",""],[25605,25605,"","আমরা সবচেয়ে ভালটার ব্যাপারে কথা বলেছিলাম । আমরা বলেছিলাম যে, সেই বাচ্চা সম্বন্ধে আমরা কথা বলেছিলাম । ঈশ্বর ঈশ্বর তাকে বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏نَافِعًا ‏ ‏مَوْلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏يَقُولُ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ عَبْدِ اللَّهِ بْنِ مَعْبَدٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏حَدَّثَ أَنَّ ‏ ‏مَيْمُونَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏صَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏هَذَا أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ إِلَّا ‏ ‏مَسْجِدَ الْكَعْبَةِ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏نَافِعًا ‏ ‏يَقُولُ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ عَبْدِ اللَّهِ بْنِ مَعْبَدِ بْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏مَيْمُونَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[25606,25606,"","আমরা একটা নির্দিষ্ট ছেলের কথা বলেছিলাম যে আমাদের কাছে ভালো বিশ্বাস নিয়ে কথা বলার আনন্দ আছে, হয়তো সে লর্ডের বার্তা শুনতে পেয়েছে। যেখানে প্রার্থনা করা হয় তারা গৌরব খুঁজে না পেয়েই ভাল।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ مَعْبَدِ بْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏مَيْمُونَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏صَلَاةٌ فِيهِ أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ مِنْ الْمَسَاجِدِ إِلَّا ‏ ‏مَسْجِدَ الْكَعْبَةِ ‏","","",""],[25607,25607,"","তারা মনে করেছিল যে, আমি যদি যেতে চাই, তা হলে এটা বৃদ্ধি পাবে । লর্ড লর্ড লর্ডের লর্ড নয়, এমন এক শিক্ষক, যিনি প্রার্থনা করেন যে জাতি কখনো জিতে যাবে না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عُبَيْدَةَ عَبْدُ الْوَاحِدِ الْحَدَّادُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ فَرُّوخٍ أَبُو بَكَّارٍ ‏ ‏أَنَّ ‏ ‏أَبَا الْمَلِيحِ ‏ ‏خَرَجَ عَلَى جَنَازَةٍ فَلَمَّا اسْتَوَى ظَنُّوا أَنَّهُ يُكَبِّرُ فَالْتَفَتَ فَقَالَ اسْتَوُوا لِتَحْسُنَ شَفَاعَتُكُمْ فَإِنِّي لَوْ اخْتَرْتُ رَجُلًا لَاخْتَرْتُ هَذَا إِلَّا أَنَّهُ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ سَلِيطٍ ‏ ‏عَنْ ‏ ‏إِحْدَى ‏ ‏أُمَّهَاتِ الْمُؤْمِنِينَ وَهِيَ ‏ ‏مَيْمُونَةُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ مُسْلِمٍ ‏ ‏يُصَلِّي عَلَيْهِ أُمَّةٌ مِنْ النَّاسِ إِلَّا ‏ ‏شُفِّعُوا ‏ ‏فِيهِ ‏ ‏قَالَ ‏ ‏فَسَأَلْتُ ‏ ‏أَبَا الْمَلِيحِ ‏ ‏عَنْ الْأُمَّةِ ‏ ‏فَقَالَ ‏ ‏أَرْبَعُونَ ‏","","",""],[25608,25608,"","আমরা আমার বাবার কাছে প্রার্থনা করেছিলাম যেন তিনি বজ্রপাতের ঝড়ের লোকেদের মতো হন । তিনি এই বলে আপত্তি জানিয়েছিলেন যে, তিনি এই ব্যাপারে প্রস্তুত ছিলেন । সে এমন কিছু পছন্দ করে যা সে করতে চায়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَنْظَلَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ بْنِ نَوْفَلٍ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا ‏ ‏مُعَاوِيَةُ بْنُ أَبِي سُفْيَانَ ‏ ‏صَلَاةَ الْعَصْرِ فَأَرْسَلَ إِلَى ‏ ‏مَيْمُونَةَ ‏ ‏ثُمَّ أَتْبَعَهُ رَجُلًا آخَرَ فَقَالَتْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُجَهِّزُ ‏ ‏بَعْثًا ‏ ‏وَلَمْ يَكُنْ عِنْدَهُ ‏ ‏ظَهْرٌ ‏ ‏فَجَاءَهُ ‏ ‏ظَهْرٌ ‏ ‏مِنْ الصَّدَقَةِ فَجَعَلَ يَقْسِمُهُ بَيْنَهُمْ فَحَبَسُوهُ حَتَّى أَرْهَقَ الْعَصْرَ وَكَانَ ‏ ‏يُصَلِّي قَبْلَ الْعَصْرِ رَكْعَتَيْنِ أَوْ مَا شَاءَ اللَّهُ فَصَلَّى ‏ ‏الْعَصْرَ ثُمَّ رَجَعَ فَصَلَّى مَا كَانَ ‏ ‏يُصَلِّي قَبْلَهَا وَكَانَ إِذَا صَلَّى صَلَاةً أَوْ فَعَلَ شَيْئًا يُحِبُّ أَنْ يُدَاوِمَ عَلَيْهِ ‏","","",""],[25609,25609,"","আমরা আদম সম্পর্কে কথা বলেছি যে আমরা একজন শিকারীকে খুঁজে পেয়েছি যে কিনা মারা গেছে। আমি তার জন্য প্রার্থনা করেছি এবং আমি বলবো যে আমাদের ঈশ্বর কে জানে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ زِيَادٍ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ بِنْتِ الْحَارِثِ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ اسْتَدَانَ دَيْنًا يَعْلَمُ اللَّهُ عَزَّ وَجَلَّ مِنْهُ أَنَّهُ يُرِيدُ أَدَاءَهُ أَدَّاهُ اللَّهُ عَنْهُ ‏","","",""],[25610,25610,"","আমরা সাক্ষীর ছেলের প্রতি ভালবাসা নিয়ে কথা বলেছি, আমার ভাইয়ের ছেলে দৃঢ়প্রতিজ্ঞ যে নবী তার শান্তি এবং তার বিবাহকে রক্ষা করেছে। জ্ঞানহীন হয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ الشَّهِيدِ ‏ ‏عَنْ ‏ ‏مَيْمُونِ بْنِ مِهْرَانَ ‏ ‏عَنْ ‏ ‏يَزِيدَ الْأَصَمِّ ‏ ‏ابْنَ أَخِي ‏ ‏مَيْمُونَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَزَوَّجَهَا وَهُمَا حَلَالَانِ ‏ ‏بِسَرِفٍ ‏ ‏بَعْدَمَا رَجَعَ ‏","","",""],[25611,25611,"","আমরা একে অপরের সাথে কথা বলেছি, আমরা কতবার এ বিষয়ে কথা বলেছি আমি আমার ছেলেকে ঈশ্বরের কাছে রাখি, তাকে চলে যেতে হবে। মানে, সে ফিরে এসেছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏خَالَتِهِ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏وَضَعْتُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غِسْلًا فَاغْتَسَلَ مِنْ الْجَنَابَةِ ثُمَّ أَتَيْتُهُ بِثَوْبٍ حِينَ اغْتَسَلَ فَقَالَ بِيَدِهِ هَكَذَا ‏ ‏يَعْنِي رَدَّهُ ‏","","",""],[25612,25612,"","আমি আমার ছেলেকে ঈশ্বরের কাছে পৌঁছে দিয়েছিলাম, যেন তিনি স্বর্গ থেকে বেরিয়ে এসেছেন এবং স্বর্গ থেকে তাকে জিজ্ঞেস করা হবে. তারপর আমি তার হাত কে তা বলার জন্য তার হাত বাড়িয়ে দিব. তিনি তিন বার এটা খুঁজে পান আর এরপর তিন দিন তিনি তিন বার তার দিকে তাকিয়ে তাকে দেখেন ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏خَالَتِهِ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏وَضَعْتُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غِسْلًا فَاغْتَسَلَ مِنْ الْجَنَابَةِ وَأَكْفَأَ الْإِنَاءَ بِشِمَالِهِ عَلَى يَمِينِهِ فَغَسَلَ كَفَّيْهِ ثَلَاثًا ثُمَّ أَدْخَلَ يَدَهُ فِي الْإِنَاءِ ‏ ‏فَأَفَاضَ ‏ ‏عَلَى فَرْجِهِ ثُمَّ دَلَكَ يَدَهُ بِالْحَائِطِ ‏ ‏أَوْ الْأَرْضِ ‏ ‏ثُمَّ مَضْمَضَ وَاسْتَنْشَقَ ثَلَاثًا وَغَسَلَ وَجْهَهُ ثَلَاثًا وَذِرَاعَيْهِ ثَلَاثًا ثَلَاثًا ثُمَّ ‏ ‏أَفَاضَ ‏ ‏عَلَى رَأْسِهِ ثَلَاثًا ثُمَّ ‏ ‏أَفَاضَ ‏ ‏عَلَى سَائِرِ جَسَدِهِ الْمَاءَ ثُمَّ ‏ ‏تَنَحَّى ‏ ‏فَغَسَلَ رِجْلَيْهِ ‏","","",""],[25613,25613,"","আমরা কথা বলেছি আমরা কি করেছি, ঈশ্বর আত্মসমর্পণ করেছেন যদি তিনি আমার চোখের সামনে আমার দৃষ্টি খুঁজে না পান, যতক্ষণ না তিনি বুঝতে পারেন কে পরিত্যক্ত অবস্থায় আছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ بُرْقَانَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْأَصَمِّ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَجَدَ ‏ ‏جَافَى ‏ ‏حَتَّى يَرَى مَنْ خَلْفَهُ بَيَاضَ إِبْطَيْهِ ‏","","",""],[25614,25614,"","আমরা একটা মৃত্যুর কথা বলেছি... ...আমার বাবা তার সম্পর্কে একই কথা বলেছেন, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তার সাত জনে বড় লোককে দিয়ে দেন। আর আশা করি সে পৃথিবীর এক প্রান্তে খেয়ে যাবে.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْأَعْمَشَ ‏ ‏قَالَ ‏ ‏أَظُنُّ ‏ ‏أَبَا خَالِدٍ الْوَالِبِيَّ ‏ ‏ذَكَرَهُ عَنْ ‏ ‏مَيْمُونَةَ بِنْتِ الْحَارِثِ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْكَافِرُ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ وَالْمُؤْمِنُ يَأْكُلُ فِي مِعًى وَاحِدٍ ‏","","",""],[25615,25615,"","আমি আমার সবচেয়ে ভালটা নিয়ে কথা বলেছি... ...আমার নিজের জন্য দুই বছর কঠোর হয়ে থাকার কথা... ...তার জন্য লর্ড প্রার্থনা করেছে তার জন্য আর আত্মসমর্পণ করা হয়েছে - ঐ অতিথির তো একদম সোজা।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُبَاشِرُهَا وَهِيَ حَائِضٌ فَوْقَ ‏ ‏الْإِزَارِ ‏","","",""],[25616,25616,"","আমরা আমার ভাই-বোনের জন্য আপনার সবচেয়ে ভালো টাকা নিয়ে কথা বলেছি। নবী তার জন্য প্রার্থনা করেছেন এবং আশ্বস্ত হয়েছেন যে, ভাববাদী তার পতাকায় পৌঁছেছেন এবং সঠিক দাবি করেছেন। গোপন কথা, তাকে নিয়ে যাও আর তাকে রূপান্তর করো.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ فَأْرَةٍ وَقَعَتْ فِي سَمْنٍ قَالَ خُذُوهَا وَمَا حَوْلَهَا فَأَلْقُوهُ ‏","","",""],[25617,25617,"","আমরা আবেগ এবং আনন্দের সাথে কথা বলেছি যাতে আমাকে সতর্ক করে বলতে পারি যে, আমি প্রার্থনা থেকে বেরিয়ে এসেছি, ভয় পেয়ে আমাকে উড়িয়ে দিতে। ছেলেটির প্রতি যা করেছিল, তার উপর তাকে বিশ্বাস করতে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَيَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْحَكَمُ ‏ ‏قَالَ سَأَلْتُ ‏ ‏مِقْسَمًا ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏أُوتِرُ ‏ ‏بِثَلَاثٍ ثُمَّ أَخْرُجُ إِلَى الصَّلَاةِ مَخَافَةَ أَنْ تَفُوتَنِي قَالَ لَا يَصْلُحُ إِلَّا بِخَمْسٍ أَوْ سَبْعٍ فَأَخْبَرْتُ ‏ ‏مُجَاهِدًا ‏ ‏وَيَحْيَى بْنَ الجَزَّارِ ‏ ‏بِقَوْلِهِ فَقَالَا لِي سَلْهُ عَمَّنْ فَسَأَلْتُهُ فَقَالَ عَنْ الثِّقَةِ عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏وَعَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[25618,25618,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমাদের কাছে এনেছে... ...যে আমার প্রভুর ইচ্ছা পূরণ করতে, তার দাসের প্রতি সন্দেহ আছে। সে ঈশ্বরের কাছে প্রার্থনা করেছে এবং তাকে আত্মসমর্পণ করা হয়েছে যে, তাকে সীলের জন্য ডাকা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏خَالَتِهِ ‏ ‏مَيْمُونَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُصَلِّي عَلَى ‏ ‏الْخُمْرَةِ ‏","","",""],[25619,25619,"","আমরা তর্ক আর বাবার কথা বলেছি আমরা প্রেম আর ভালবাসা নিয়ে কথা বলেছি। লর্ড লর্ড লর্ড লর্ডের মৃত্যু হল, ঈশ্বর আদেশ দিয়েছেন আর তাই হয়েছে ঈশ্বরের দেবতা, তার মেয়েদের থেকে, যদি তিনি দেখতে যেতেন যে, অর্ধেক ফাঁদ বা হাঁটুকে ডেকে ডাকতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَأَبُو كَامِلٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏مَوْلَى ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏بُدَيَّةَ ‏ ‏مَوْلَاةِ ‏ ‏مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُبَاشِرُ ‏ ‏الْمَرْأَةَ مِنْ نِسَائِهِ وَهِيَ حَائِضٌ إِذَا كَانَ عَلَيْهَا إِزَارٌ يَبْلُغُ أَنْصَافَ الْفَخِذَيْنِ أَوْ الرُّكْبَتَيْنِ مُحْتَجِزَةً بِهِ ‏","","",""],[25620,25620,"","আমরা সেই যুবকের কথা বলেছিলাম, ঈশ্বরের অমরত্ব নিয়ে আমরা তাকে বলেছিলাম। ভগবান ঈশ্বরকে প্রার্থনা করতো, যেন তিনি তাকে চিনত এবং তিনি পঞ্চমবারের জন্য প্রার্থনা করতেন।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الشَّيْبَانِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ بِنْتِ الْحَارِثِ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى ‏ ‏الْخُمْرَةِ ‏","","",""],[25621,25621,"","আমরা সবচেয়ে ভালোর বিষয়ে কথা বলেছিলাম । আত্মসমর্পণ করো.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَيَزِيدُ ‏ ‏قَالَا أَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ ‏ ‏عَطَاءٌ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَخْبَرَتْنِي ‏ ‏مَيْمُونَةُ زَوْجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ شَاةً مَاتَتْ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا ‏ ‏دَبَغْتُمْ ‏ ‏إِهَابَهَا ‏ ‏فَاسْتَمْتَعْتُمْ بِهِ ‏","","",""],[25622,25622,"","আমরা পৃথিবীর খ্যাতির সাথে আমাদের দেখা সবচেয়ে ভালো সময়ের কথা বলেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তার জন্য সবচেয়ে সেরা হয়ে যাবেন। আমি অর্ধেক সময় নিয়েছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏بُدَيَّةَ ‏ ‏مَوْلَاةِ ‏ ‏مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُبَاشِرُ ‏ ‏الْمَرْأَةَ مِنْ نِسَائِهِ حَائِضًا تَكُونُ عَلَيْهَا الْخِرْقَةُ إِلَى الرُّكْبَتَيْنِ أَوْ إِلَى أَنْصَافِ الْفَخِذَيْنِ ‏","","",""],[25623,25623,"","আমরা ইশ্বরের সাথে কথা বলেছি তিনি যা বলেছেন তা হল প্রভু ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি তার মেয়েদের কাছে প্রচার করতে যাচ্ছেন এবং তিনি তার ঘরে গিয়েছেন এবং তারা জীবিত।","‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الشَّيْبَانِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادِ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُبَاشِرُ نِسَاءَهُ فَوْقَ ‏ ‏الْإِزَارِ ‏ ‏وَهُنَّ حُيَّضٌ ‏","","",""],[25624,25624,"","আমরা ঐ যুবককে মারার ব্যাপারে কথা বলেছিলাম যে সে হয়ত এমন হতে পারে, শিকারী বলেছে... ...যে ভাববাদীর পতাকার সাথে মিশিয়েছে আর সে বলেছে যে সে লর্ডের বার্তাবাহক. তার মেয়েদের কাছ থেকে কোন মেয়েকে পালিয়ে বের করতে হবে আর তার তালাক আছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ الشَّيْبَانِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ شَدَّادِ بْنِ الْهَادِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَيْمُونَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَنْ ‏ ‏يُبَاشِرَ ‏ ‏امْرَأَةً مِنْ نِسَائِهِ وَهِيَ حَائِضٌ أَمَرَهَا ‏ ‏فَاتَّزَرَتْ ‏","","",""],[25625,25625,"","বাবার মৃত্যুর পর বাবার খোঁজ নিয়ে কথা বলেছিলাম, সে তার হাতে গিয়েছে, আর একবার সে তাকে ধোঁকা দিয়েছে বা বলেছে যে সে আমার বাবার সাথে প্রতারণা করেছে এরপর তার শরীর নেমে আসে, তিনি বলেন যে তিনি আসবেন আর আপনার কথা ঠিক আপনার মতো । কখনো অস্বীকার করে নি এবং বলে নি যে, এটা যেন খুঁজে পাওয়া যায়।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنِ ‏ ‏سُلَيْمَانَ الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ بِنْتِ الْحَارِثِ ‏ ‏قَالَتْ ‏ ‏وَضَعْتُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غِسْلًا وَسَتَرْتُهُ ‏ ‏فَصَبَّ عَلَى يَدِهِ فَغَسَلَهَا مَرَّةً ‏ ‏أَوْ مَرَّتَيْنِ قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏فَلَا أَدْرِي أَذَكَرَ الثَّالِثَةَ أَمْ لَا ‏ ‏قَالَ ثُمَّ أَفْرَغَ بِيَمِينِهِ عَلَى شِمَالِهِ فَغَسَلَ فَرْجَهُ ثُمَّ دَلَكَ يَدَهُ بِالْأَرْضِ ‏ ‏أَوْ بِالْحَائِطِ ‏ ‏ثُمَّ مَضْمَضَ وَاسْتَنْشَقَ وَغَسَلَ وَجْهَهُ قَالَ وَغَسَلَ رَأْسَهُ ثُمَّ صَبَّ عَلَى جَسَدِهِ ثُمَّ ‏ ‏تَنَحَّى ‏ ‏فَغَسَلَ قَدَمَيْهِ قَالَتْ فَنَاوَلْتُهُ خِرْقَةً قَالَ فَقَالَ هَكَذَا وَأَشَارَ بِيَدِهِ أَنْ لَا أُرِيدُهَا ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏فَذَكَرْتُ ‏ ‏ذَلِكَ ‏ ‏لِإِبْرَاهِيمَ ‏ ‏فَقَالَ ‏ ‏هُوَ كَذَلِكَ وَلَمْ يُنْكِرْهُ ‏ ‏و قَالَ ‏ ‏إِبْرَاهِيمُ ‏ ‏لَا بَأْسَ بِالْمِنْدِيلِ إِنَّمَا هِيَ عَادَةٌ ‏","","",""],[25626,25626,"","আমরা একজন বাবাকে খুন করার কথা বলেছিলাম, হয়তো সে দরজা থেকে খুন হয়েছে, সে বলেছে সে আমাকে ঈশ্বরের ইচ্ছা নিয়ে যেতে বলেছে। বিছানা আর হৃদয়ের হৃদয় আর হৃদয়ের হৃদয়। সূর্য.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَيْدُ بْنُ جُبَيْرٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏فَذَكَرَ حَدِيثًا ‏ ‏قَالَ ‏ ‏وَسَأَلَهُ رَجُلٌ عَمَّا يُقْتَلُ مِنْ ‏ ‏الدَّوَابِّ ‏ ‏فَقَالَ أَخْبَرَتْنِي ‏ ‏إِحْدَى نِسْوَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏أَمَرَ بِقَتْلِ الْفَأْرَةِ وَالْعَقْرَبِ وَالْكَلْبِ ‏ ‏الْعَقُورِ ‏ ‏وَالْحُدَيَّا وَالْغُرَابِ ‏","","",""],[25627,25627,"","আমরা একে অপরের সাথে কথা বলেছি যে ছেলে চুপচাপ আছে। আমি দেখেছি যে, ঘৃণাকারীরা হয়তো তাদের ওপর নজর রাখতে পারে ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي إِدْرِيسَ ‏ ‏عَنِ ‏ ‏ابْنِ صَفْوَانَ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَنْتَهِي النَّاسُ عَنْ غَزْوِ هَذَا ‏ ‏الْبَيْتِ ‏ ‏حَتَّى يَغْزُوَهُ جَيْشٌ حَتَّى إِذَا كَانُوا ‏ ‏بِبَيْدَاءَ ‏ ‏مِنْ الْأَرْضِ خُسِفَ بِأَوَّلِهِمْ وَآخِرِهِمْ وَلَمْ يَنْجُ أَوْسَطُهُمْ قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَأَيْتَ الْمُكْرَهَ مِنْهُمْ قَالَ يَبْعَثُهُمْ اللَّهُ عَلَى مَا فِي أَنْفُسِهِمْ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏سَلَمَةُ ‏ ‏فَحَدَّثَنِي ‏ ‏عُبَيْدُ بْنُ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏نَحْوَ هَذَا الْحَدِيثِ ‏","","",""],[25628,25628,"","আমরা একটি স্মৃতিস্তম্ভের পুত্র, যে আমার ছেলে দেবতা হওয়ার জন্য একটি মহান পুত্র হবার আশীর্বাদ নিয়ে কথা বলেছি। আমি তাদের শেষ পর্যন্ত বেঁচে থাকতে দেব না, আমি তাদের ভয় ছিল. কিন্তু, তারা যখন যিহোবার কাছে প্রার্থনা করে, তখন তারা তাঁর কাছে প্রার্থনা করে ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ يَعْنِي ابْنَ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي إِدْرِيسَ ‏ ‏عَنِ ‏ ‏ابْنِ صَفْوَانَ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ حُيَيٍّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَنْتَهِي النَّاسُ عَنْ غَزْوِ هَذَا ‏ ‏الْبَيْتِ ‏ ‏حَتَّى إِذَا كَانُوا ‏ ‏بِبَيْدَاءَ ‏ ‏مِنْ الْأَرْضِ خُسِفَ أَوَّلُهُمْ وَآخِرُهُمْ وَلَمْ يَنْجُ أَوْسَطُهُمْ قَالُوا يَا رَسُولَ اللَّهِ يَكُونُ فِيهِمْ الْمُكْرَهُ قَالَ يَبْعَثُهُمْ اللَّهُ عَلَى مَا فِي أَنْفُسِهِمْ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي إِدْرِيسَ الْمُرْهِبِيُّ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ صَفْوَانَ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَنْتَهِي النَّاسُ وَذَكَرَ الْحَدِيثَ وَسَاقَهُ ‏","","",""],[25629,25629,"","বাবার সাথে এমন একজন উৎপীড়ক হওয়া সম্পর্কে আমরা কথা বলেছি যে কিনা বলেছে সে একজন উৎপীড়ক। তোমার জীবনের এক গ্রীষ্মকালে, আমি অপরাধ করার জন্য আবেদন করেছিলাম। ঈশ্বরের কাছে প্রার্থনা করা নিষিদ্ধ ছিল, ঈশ্বরের দ্বারা তিনি তা করেছেন এবং ঈশ্বরের রাজা হওয়ার জন্য এসেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏يَعْلَى بْنَ حَكِيمٍ ‏ ‏عَنْ ‏ ‏صُهَيْرَةَ بِنْتِ جَيْفَرٍ ‏ ‏قَالَتْ ‏ ‏دَخَلْتُ ‏ ‏عَلَى ‏ ‏صَفِيَّةَ بِنْتِ حُيَيٍّ ‏ ‏فَسَأَلْتُ عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏فَقَالَتْ ‏ ‏حَرَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَبِيذَ ‏ ‏الْجَرِّ ‏","","",""],[25630,25630,"","আমরা র‍্যালির কথা বলেছিলাম, আমি কেমন অনুভব করেছিলাম, সেই সম্বন্ধে আমরা একে অন্যকে বলেছিলাম । ঈশ্বর তাকে শিক্ষা দিতে পারেন আর আমি প্রভুকে হত্যা করতে দ্রুতই চাই এবং ঈশ্বর তাকে উদ্ধার করেছেন এবং আপনাকে ঈশ্বরের কাছে সমর্পণ করেছেন । প্রভু, বলবে যে, শয়তান রক্ত ডিলারের কাছ থেকে পালিয়ে যাচ্ছে... ...আর আমি ভয় পাচ্ছি সে শপথ নিবে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَعَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ حُيَيٍّ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُعْتَكِفًا ‏ ‏فَأَتَيْتُهُ أَزُورُهُ لَيْلًا فَحَدَّثْتُهُ ثُمَّ قُمْتُ ‏ ‏فَانْقَلَبْتُ ‏ ‏فَقَامَ مَعِي ‏ ‏يَقْلِبُنِي ‏ ‏وَكَانَ مَسْكَنُهَا فِي دَارِ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏فَمَرَّ رَجُلَانِ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَلَمَّا رَأَيَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْرَعَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏رِسْلِكُمَا ‏ ‏إِنَّهَا ‏ ‏صَفِيَّةُ بِنْتُ حُيَيٍّ ‏ ‏فَقَالَا سُبْحَانَ اللَّهِ يَا رَسُولَ اللَّهِ فَقَالَ ‏ ‏إِنَّ الشَّيْطَانَ يَجْرِي مِنْ الْإِنْسَانِ مَجْرَى الدَّمِ وَإِنِّي خَشِيتُ أَنْ ‏ ‏يَقْذِفَ ‏ ‏فِي قُلُوبِكُمَا شَرًّا ‏ ‏أَوْ قَالَ شَيْئًا ‏","","",""],[25631,25631,"","আমরা একটা সাহসী বিচার সম্বন্ধে বলেছিলাম, যেটা আমার বাবার কাছে হয়েছিল বলে তিনি শুনেছিলেন যে তিনি তার গোপন কথা বলেছেন । তিনি পিপা ওয়াইন দিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏يَعْلَى بْنَ حَكَمٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏صُهَيْرَةَ بِنْتِ جَيْفَرٍ ‏ ‏قَالَتْ ‏ ‏حَجَجْنَا ثُمَّ أَتَيْنَا ‏ ‏الْمَدِينَةَ ‏ ‏فَدَخَلْنَا عَلَى ‏ ‏صَفِيَّةَ بِنْتِ حُيَيٍّ ‏ ‏فَوَافَقْنَا عِنْدَهَا نِسْوَةً فَقَالَتْ ‏ ‏حَرَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَبِيذَ ‏ ‏الْجَرِّ ‏","","",""],[25632,25632,"","আমরা আমাকে খুন করার কথা বলছিলাম, একটা প্রান্তরে সে আমাকে খুন করার চেষ্টা করছিল। সে বলেছিল, আমরা জেলে ছিলাম এবং আমরা শহরে জয়ের চেষ্টা করেছি। আমি কিছু একটা শুনেছি। আমি জানি, আমি কি বলছি, এটা একটা জিনিস শুনতে পাই। কিন্তু আমি জানি, এটা কি, এটা একটা বিশাল আঘাত। আমি জানি, এটা কি, এটা কি, এটা একটা বিশাল ব্যাপার। কিন্তু আমি জানি না, আমি কি বলছি, আমি কি বলেছি? আমি জানি, আমি কি করেছি, আমি জানি, আমি কি করেছি? এটা একটা জিনিস শুনতে চাই। আমি কি করেছি, আমি কি করেছি? এটা একটা ছোট ব্যাপার জানি, আমি জানি, আমি কি করেছি। আমি কি করেছি। আমি জানি, আমি জানি, আমি কি করেছি। আমি কি করেছি, আমি জানি না? আমি শুনতে পাবো যদি আমি শুনতে পাই তাহলে প্রতিবেশীদের আগুন নিয়ন্ত্রণের বাইরে চলে যেতে বলবো।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَعْلَى بْنُ حَكِيمٍ ‏ ‏عَنْ ‏ ‏صُهَيْرَةَ بِنْتِ جَيْفَرٍ ‏ ‏سَمِعَهُ مِنْهَا ‏ ‏قَالَتْ ‏ ‏حَجَجْنَا ثُمَّ انْصَرَفْنَا إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَدَخَلْنَا عَلَى ‏ ‏صَفِيَّةَ بِنْتِ حُيَيٍّ ‏ ‏فَوَافَقْنَا عِنْدَهَا نِسْوَةً مِنْ أَهْلِ ‏ ‏الْكُوفَةِ ‏ ‏فَقُلْنَ لَهَا إِنْ شِئْتُنَّ سَأَلْتُنَّ وَسَمِعْنَا وَإِنْ شِئْتُنَّ سَأَلْنَا وَسَمِعْتُنَّ فَقُلْنَا سَلْنَ فَسَأَلْنَ عَنْ أَشْيَاءَ مِنْ أَمْرِ الْمَرْأَةِ وَزَوْجِهَا وَمِنْ أَمْرِ ‏ ‏الْمَحِيضِ ‏ ‏ثُمَّ سَأَلْنَ عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏فَقَالَتْ أَكْثَرْتُمْ عَلَيْنَا يَا أَهْلَ ‏ ‏الْعِرَاقِ ‏ ‏فِي ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏وَمَا عَلَى إِحْدَاكُنَّ أَنْ تَطْبُخَ تَمْرَهَا ثُمَّ تَدْلُكَهُ ثُمَّ تُصَفِّيَهُ فَتَجْعَلَهُ فِي سِقَائِهَا ‏ ‏وَتُوكِئَ عَلَيْهِ فَإِذَا طَابَ شَرِبَتْ وَسَقَتْ زَوْجَهَا ‏","","",""],[25633,25633,"","আমাদের দুজনের মধ্যে কেউ কেউ কেউ ঈশ্বরের কাছে প্রার্থনা করেছে । একটা লোককে নিচে নামিয়ে, তারা দ্রুতই ভবিষ্যদ্বাণীটা হত্যা করতে থাকে আর সে তোমাকে যেতে বলে, তারা তোমাকে অর্ধেক সারিতে নিয়ে যাবে, তুমি তার জীবনের চেয়ে ভালো। তোমাকে স্বপ্ন দেখে তাকে অশ্রুচাঁপাতে বলা হয়েছে। এটা বলা যায় যে আমি জানতাম না যে আমি ঈশ্বরের অনুগ্রহে আক্রান্ত হয়েছি, আমার কাছে এমন কিছু আছে যেটা আমাকে জীবিত থাকতে বলা হয়েছিল যে সে জানতো আমি বিক্রি করিনি। কিছু জিনিস আমি কখনো দোষ দিচ্ছি না। আল্লাহ্‌ আর আমি ঈশ্বরের জন্য দোষারোপ করেছি। তারপর সে আর চলে যাবে না। ঈশ্বরও তা করতে পারতেন না। সে ছিল একটা দানব, যে কিনা পিছনে তাকিয়ে ছিল, সে বলল আমি তোমাকে বোকা বানাতে পারি না। সে আর কখনোই ঈশ্বরের ছায়ায় থাকতে পারত না। ঈশ্বর তাকে প্রার্থনা করেছেন এবং নিজেকে ঈশ্বরের অনুগ্রহে দেখার জন্য প্রার্থনা করেছেন। আমি জানি, আমি কী করছি, ভাববাদী তার হৃদয়ে হেঁটেছি। আমি জানি, আমি কি করছি। আমি জানি, নবী, আমি যদি আমার জীবনের উদ্দেশ্য নিয়ে কথা বলি, তাহলে আমি তাকে বলি, আমি যদি আমি আমার জীবনের জন্য প্রার্থনা করি, তাহলে আমি যদি আমার জীবনের জন্য প্রার্থনা করি, তাহলে আমি জানি, আমি কি করতে হবে। (হাসি) আর তাকে প্রভুর কাছে হস্তান্তর করা হয় এবং তারপর আমাকে পরাজিত করা হয়। আমরা একটা বাপ্তিস্মের অর্থ ছিল তার গ্রেসের কথা বলা ছেলে। ঈশ্বর আছে এবং তিনি কিছু গোপন বিষয় নিয়ে কথা বলেছেন যা তিনি করেছেন। তার আত্মার কথা বল.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏شُمَيْسَةُ ‏ ‏أَوْ ‏ ‏سُمَيَّةُ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏هُوَ فِي كِتَابِي ‏ ‏سُمَيَّةُ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ حُيَيٍّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَجَّ بِنِسَائِهِ فَلَمَّا كَانَ فِي بَعْضِ الطَّرِيقِ نَزَلَ رَجُلٌ فَسَاقَ بِهِنَّ فَأَسْرَعَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَذَاكَ سَوْقُكَ ‏ ‏بِالْقَوَارِيرِ ‏ ‏يَعْنِي النِّسَاءَ ‏ ‏فَبَيْنَا هُمْ يَسِيرُونَ بَرَكَ ‏ ‏بِصَفِيَّةَ بِنْتِ حُيَيٍّ ‏ ‏جَمَلُهَا وَكَانَتْ مِنْ أَحْسَنِهِنَّ ظَهْرًا فَبَكَتْ وَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ أُخْبِرَ بِذَلِكَ فَجَعَلَ يَمْسَحُ دُمُوعَهَا ‏ ‏بِيَدِهِ وَجَعَلَتْ تَزْدَادُ بُكَاءً وَهُوَ ‏ ‏يَنْهَاهَا فَلَمَّا أَكْثَرَتْ زَبَرَهَا وَانْتَهَرَهَا ‏ ‏وَأَمَرَ النَّاسَ بِالنُّزُولِ فَنَزَلُوا وَلَمْ يَكُنْ يُرِيدُ أَنْ يَنْزِلَ قَالَتْ فَنَزَلُوا وَكَانَ يَوْمِي فَلَمَّا نَزَلُوا ضُرِبَ ‏ ‏خِبَاءُ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَدَخَلَ فِيهِ قَالَتْ فَلَمْ أَدْرِ عَلَامَ أُهْجَمُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَخَشِيتُ أَنْ يَكُونَ فِي نَفْسِهِ شَيْءٌ مِنِّي فَانْطَلَقْتُ إِلَى ‏ ‏عَائِشَةَ ‏ ‏فَقُلْتُ لَهَا تَعْلَمِينَ أَنِّي لَمْ أَكُنْ أَبِيعُ يَوْمِي مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِشَيْءٍ أَبَدًا وَإِنِّي قَدْ وَهَبْتُ يَوْمِي لَكِ عَلَى أَنْ تُرْضِي رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنِّي قَالَتْ نَعَمْ قَالَ فَأَخَذَتْ ‏ ‏عَائِشَةُ ‏ ‏خِمَارًا ‏ ‏لَهَا قَدْ ‏ ‏ثَرَدَتْهُ ‏ ‏بِزَعْفَرَانٍ ‏ ‏فَرَشَّتْهُ بِالْمَاءِ لِيُذَكِّيَ رِيحَهُ ثُمَّ لَبِسَتْ ثِيَابَهَا ثُمَّ انْطَلَقَتْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَفَعَتْ طَرَفَ ‏ ‏الْخِبَاءِ ‏ ‏فَقَالَ لَهَا مَا لَكِ يَا ‏ ‏عَائِشَةُ ‏ ‏إِنَّ هَذَا لَيْسَ بِيَوْمِكِ قَالَتْ ذَلِكَ فَضْلُ اللَّهِ ‏ ‏يُؤْتِيهِ مَنْ يَشَاءُ فَقَالَ مَعَ أَهْلِهِ فَلَمَّا كَانَ عِنْدَ ‏ ‏الرَّوَاحِ ‏ ‏قَالَ ‏ ‏لِزَيْنَبَ بِنْتِ جَحْشٍ ‏ ‏يَا ‏ ‏زَيْنَبُ ‏ ‏أَفْقِرِي ‏ ‏أُخْتَكِ ‏ ‏صَفِيَّةَ ‏ ‏جَمَلًا وَكَانَتْ مِنْ أَكْثَرِهِنَّ ‏ ‏ظَهْرًا ‏ ‏فَقَالَتْ أَنَا أُفْقِرُ يَهُودِيَّتَكَ فَغَضِبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ سَمِعَ ذَلِكَ مِنْهَا فَهَجَرَهَا فَلَمْ يُكَلِّمْهَا حَتَّى قَدِمَ ‏ ‏مَكَّةَ ‏ ‏وَأَيَّامَ ‏ ‏مِنًى ‏ ‏فِي سَفَرِهِ حَتَّى رَجَعَ إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏وَالْمُحَرَّمَ وَصَفَرَ فَلَمْ يَأْتِهَا وَلَمْ يَقْسِمْ لَهَا وَيَئِسَتْ مِنْهُ فَلَمَّا كَانَ شَهْرُ رَبِيعٍ الْأَوَّلِ دَخَلَ عَلَيْهَا فَرَأَتْ ظِلَّهُ فَقَالَتْ إِنَّ هَذَا لَظِلُّ رَجُلٍ وَمَا يَدْخُلُ عَلَيَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَنْ هَذَا فَدَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا رَأَتْهُ قَالَتْ يَا رَسُولَ اللَّهِ مَا أَدْرِي مَا أَصْنَعُ حِينَ دَخَلْتَ عَلَيَّ قَالَتْ وَكَانَتْ لَهَا جَارِيَةٌ وَكَانَتْ تَخْبَؤُهَا مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ فُلَانَةُ لَكَ فَمَشَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى سَرِيرِ ‏ ‏زَيْنَبَ ‏ ‏وَكَانَ قَدْ رُفِعَ فَوَضَعَهُ بِيَدِهِ ثُمَّ ‏ ‏أَصَابَ ‏ ‏أَهْلَهُ وَرَضِيَ عَنْهُمْ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏سُمَيَّةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي سَفَرٍ ‏ ‏فَاعْتَلَّ ‏ ‏بَعِيرٌ ‏ ‏لِصَفِيَّةَ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[25634,25634,"","আমরা দুই বছর ধরে আনন্দের সাথে বলছি, কিভাবে ঈশ্বর তার মায়ের জন্য প্রার্থনা করেছেন, তার জন্য তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন এবং তিনি জেনের গৌরবে আসেন।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏أَنَّهَا ‏ ‏سَمِعَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي الْمَغْرِبِ ‏ ‏بِالْمُرْسَلَاتِ عُرْفًا ‏","","",""],[25635,25635,"","আমি খুবই বিরক্ত হয়ে পড়ি ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ أَفْطَرَ ‏ ‏بِعَرَفَةَ ‏ ‏أُتِيَ بِرُمَّانٍ فَأَكَلَهُ وَقَالَ حَدَّثَتْنِي ‏ ‏أُمُّ الْفَضْلِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْطَرَ ‏ ‏بِعَرَفَةَ ‏ ‏أَتَتْهُ بِلَبَنٍ فَشَرِبَهُ ‏","","",""],[25636,25636,"","আমরা আমার বাবার সাথে কথা বলেছিলাম যে আমার সাথে কথা বলতে চায়, ঈশ্বর আমাকে সমুদ্রের জন্য যে স্বপ্নের কথা বলেছিলেন, সে তার মায়ের স্বপ্ন পূরণ করতে চেয়েছিল যে কিনা এক অসফল পাপ করেছিল। আমি ওকে বিয়ে করতে চাইনা।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ وَحَدَّثَنِي ‏ ‏حُسَيْنُ بْنُ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أُمِّ الْفَضْلِ بِنْتِ الْحَارِثِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏أُمَّ حَبِيبَةَ بِنْتَ عَبَّاسٍ ‏ ‏وَهِيَ فَوْقَ الْفَطِيمِ قَالَتْ فَقَالَ ‏ ‏لَئِنْ بَلَغَتْ بُنَيَّةُ ‏ ‏الْعَبَّاسِ ‏ ‏هَذِهِ وَأَنَا حَيٌّ لَأَتَزَوَّجَنَّهَا ‏","","",""],[25637,25637,"","আমরা মূসা কে বলেছিলাম, কিন্তু বাবার স্বপ্নের উপর জয় করার কথা বলেছিলাম। সে বলল আমরা ঈশ্বরের কাছে প্রার্থনা করব এবং তার বাড়িতে তার কাছে প্রার্থনা করব, আর তিনি একটি প্রার্থনা করলেন। ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ ‏ ‏أُمِّ الْفَضْلِ بِنْتِ الْحَارِثِ ‏ ‏قَالَتْ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِهِ ‏ ‏مُتَوَشِّحًا ‏ ‏فِي ‏ ‏ثَوْبِ ‏ ‏الْمَغْرِبِ ‏ ‏فَقَرَأَ ‏ ‏الْمُرْسَلَاتِ ‏ ‏مَا صَلَّى صَلَاةً بَعْدَهَا حَتَّى ‏ ‏قُبِضَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[25638,25638,"","আমরা বাবার মৃত্যুর কথা বলেছি আমার মায়ের ব্যাপারে আমি শুনেছি তারা আমার মায়ের কাছে প্রার্থনা করার শব্দ বলেছে এবং আমি জানতে পারব যে আমার মা কি করবে সেও পান করেছে ।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُمَيْرًا ‏ ‏مَوْلَى ‏ ‏أُمِّ الْفَضْلِ أُمِّ بَنِي الْعَبَّاسِ ‏ ‏عَنْ ‏ ‏أُمِّ الْفَضْلِ ‏ ‏قَالَتْ ‏ ‏شَكُّوا فِي صَوْمِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏عَرَفَةَ ‏ ‏فَقَالَتْ ‏ ‏أُمُّ الْفَضْلِ ‏ ‏أَنَا أَعْلَمُ لَكُمْ ذَلِكَ فَبَعَثَتْ بِلَبَنٍ فَشَرِبَ ‏","","",""],[25639,25639,"","আমি যখন তাকে জিজ্ঞেস করি যে, আমি কী করতে পারি, তখন আমি তাকে বলেছিলাম যে, তিনি আমাকে ছেড়ে দেবেন । দুটো শব্দকে উপেক্ষা না করে বা দুটো শব্দকে ভুলভাবে না বলতে পারার প্রয়োজনকে অস্বীকার করা ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي الْخَلِيلِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ الْهَاشِمِيِّ ‏ ‏عَنْ ‏ ‏أُمِّ الْفَضْلِ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِي فَجَاءَ أَعْرَابِيٌّ فَقَالَ يَا رَسُولَ اللَّهِ كَانَتْ لِي امْرَأَةٌ فَتَزَوَّجْتُ عَلَيْهَا امْرَأَةً أُخْرَى فَزَعَمَتْ امْرَأَتِي الْأُولَى أَنَّهَا أَرْضَعَتْ امْرَأَتِي ‏ ‏الْحُدْثَى ‏ ‏إِمْلَاجَةً ‏ ‏أَوْ ‏ ‏إِمْلَاجَتَيْنِ ‏ ‏وَقَالَ مَرَّةً رَضْعَةً ‏ ‏أَوْ رَضْعَتَيْنِ ‏ ‏فَقَالَ ‏ ‏لَا تُحَرِّمُ ‏ ‏الْإِمْلَاجَةُ ‏ ‏وَلَا ‏ ‏الْإِمْلَاجَتَانِ ‏ ‏أَوْ قَالَ الرَّضْعَةُ أَوْ الرَّضْعَتَانِ ‏","","",""],[25640,25640,"","আমরা বাবা আমার গাল নিয়ে কথা বলেছি... ...আমরা তাকে থামতে বলেছি আর আমরা কথা বলেছি, আমার মা আসলে আমার মায়ের কথা বলছি, যে পৃথিবীতে আগে কখনো ছিলেন। মরতে চাইলে সতর্ক থাকতে হবে, আর যদি তুমি কষ্ট পাও, তোমার ভালর চেষ্টা করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏لَيْثٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏هِنْدَ بِنْتِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أُمِّ الْفَضْلِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَى ‏ ‏الْعَبَّاسِ ‏ ‏وَهُوَ ‏ ‏يَشْتَكِي ‏ ‏فَتَمَنَّى الْمَوْتَ فَقَالَ يَا ‏ ‏عَبَّاسُ ‏ ‏يَا عَمَّ رَسُولِ اللَّهِ ‏ ‏لَا تَتَمَنَّ الْمَوْتَ إِنْ كُنْتَ مُحْسِنًا تَزْدَادُ إِحْسَانًا إِلَى إِحْسَانِكَ خَيْرٌ لَكَ وَإِنْ كُنْتَ مُسِيئًا فَإِنْ تُؤَخَّرْ ‏ ‏تَسْتَعْتِبْ ‏ ‏خَيْرٌ لَكَ فَلَا تَتَمَنَّ الْمَوْتَ ‏ ‏قَالَ ‏ ‏يُونُسُ ‏ ‏وَإِنْ كُنْتَ مُسِيئًا فَإِنْ تُؤَخَّرْ ‏ ‏تَسْتَعْتِبْ ‏ ‏مِنْ إِسَاءَتِكَ خَيْرٌ لَكَ ‏","","",""],[25641,25641,"","আমি আমার বাবার সাথে কথা বলেছি, সে বলল আমি আমার ঘরে ঈশ্বরের দোহাই দিয়ে কাজ করার জন্য আমার সবচেয়ে ভাল উপায় দেখেছি, আর তাকে বলেছি যে ঈশ্বর তাকে বলেছেন। ওকে শিখালে সে মনে মনে মনে আসবে তুমি তার জীবন হারিয়ে ফেলেছ, আমি তাকে ছেড়ে দিয়েছি, এমনকি তাকেও সরিয়ে দিতে, আর তারপর আমি তার গলা মারিয়ে তাকে বসি। আমার কাঁধে তুলে রাখ অথবা বলি সে চলে গেছে, ঈশ্বর তোমার সফর আর পোশাকটা পাঠিয়ে দিয়েছেন... ...আমি তাকে ধোঁকা দিয়েছি যখন সে ভেসে গিয়েছিল.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏قَابُوسَ بْنِ أَبِي الْمُخَارِقِ ‏ ‏عَنْ ‏ ‏أُمِّ الْفَضْلِ ‏ ‏قَالَتْ ‏ ‏رَأَيْتُ كَأَنَّ فِي بَيْتِي عُضْوًا مِنْ أَعْضَاءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏فَجَزِعْتُ ‏ ‏مِنْ ذَلِكَ فَأَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ فَقَالَ خَيْرًا تَلِدُ ‏ ‏فَاطِمَةُ ‏ ‏غُلَامًا فَتَكْفُلِينَهُ بِلَبَنِ ابْنِكِ ‏ ‏قُثَمٍ ‏ ‏قَالَتْ فَوَلَدَتْ ‏ ‏حَسَنًا ‏ ‏فَأُعْطِيتُهُ فَأَرْضَعْتُهُ حَتَّى تَحَرَّكَ ‏ ‏أَوْ فَطَمْتُهُ ‏ ‏ثُمَّ جِئْتُ بِهِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَجْلَسْتُهُ فِي حِجْرِهِ فَبَالَ فَضَرَبْتُ بَيْنَ كَتِفَيْهِ فَقَالَ ارْفُقِي بِابْنِي رَحِمَكِ اللَّهُ ‏ ‏أَوْ أَصْلَحَكِ اللَّهُ ‏ ‏أَوْجَعْتِ ابْنِي قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ اخْلَعْ ‏ ‏إِزَارَكَ ‏ ‏وَالْبَسْ ثَوْبًا غَيْرَهُ حَتَّى أَغْسِلَهُ قَالَ ‏ ‏إِنَّمَا يُغْسَلُ بَوْلُ الْجَارِيَةِ ‏ ‏وَيُنْضَحُ ‏ ‏بَوْلُ الْغُلَامِ ‏","","",""],[25642,25642,"","বাবা তার কথা শুনে তার কথা শুনে আমি তার কথা শুনেছি। আমি আমার বাবার কাছ থেকে শুনেছি। একবার যখন আমরা ঈশ্বর সম্বন্ধে বলেছি, কিন্তু আল্লাহ্ জানেন তিনি কি বলেন। আমার বাবা সমুদ্রের মায়ের প্রতি ঈশ্বরের ভালোবাসা। আমার মা, তার জন্য প্রার্থনা করুক, আর তিনি আপনার বাবার সম্মানার্থে তাকে আত্মসমর্পণ করবেন, আমরা আপনাকে উদ্ধার করবো, স্যার। আমার কিছু শত্রুকে মেরে ফেলতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْمَرٍ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏أَبِي مَعْمَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ يَعْنِي ابْنَ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أُمِّ الْفَضْلِ بِنْتِ الْحَارِثِ ‏ ‏وَهِيَ أُمُّ وَلَدِ ‏ ‏الْعَبَّاسِ ‏ ‏أُخْتُ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَرَضِهِ فَجَعَلْتُ أَبْكِي فَرَفَعَ رَأْسَهُ فَقَالَ مَا يُبْكِيكِ قُلْتُ خِفْنَا عَلَيْكَ وَمَا نَدْرِي مَا نَلْقَى مِنْ النَّاسِ بَعْدَكَ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏أَنْتُمْ الْمُسْتَضْعَفُونَ بَعْدِي ‏","","",""],[25643,25643,"","আমরা যে ঘোড়াগুলো দিতে বলেছিলাম সেগুলো আমি ভালো অথবা ভাল করে লোকেদের বলেছিলাম যে, ঈশ্বর যখন এটা তৈরি করেছিলেন, তখন তিনি বলেছিলেন যে, ঈশ্বর তাকে তাড়া করে নিয়ে যাবেন । আমরা বলেছিলাম যে হামাদ যখন বলেন যে, আমার বাবা আমার বাবাকে একটা উপহার দিচ্ছেন, তখন তিনি আমাকে বলেন যে, তিনি যেন অন্ধকার সম্বন্ধে জানেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَطَاءٌ الْخُرَاسَانِيُّ ‏ ‏عَنْ ‏ ‏لُبَابَةَ أُمِّ الْفَضْلِ ‏ ‏أَنَّهَا كَانَتْ تُرْضِعُ ‏ ‏الْحَسَنَ ‏ ‏أَوْ ‏ ‏الْحُسَيْنَ ‏ ‏قَالَتْ فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاضْطَجَعَ ‏ ‏فِي مَكَانٍ مَرْشُوشٍ فَوَضَعَهُ عَلَى بَطْنِهِ فَبَالَ عَلَى بَطْنِهِ فَرَأَيْتُ الْبَوْلَ يَسِيلُ عَلَى بَطْنِهِ فَقُمْتُ إِلَى ‏ ‏قِرْبَةٍ ‏ ‏لِأَصُبَّهَا عَلَيْهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏أُمَّ الْفَضْلِ ‏ ‏إِنَّ بَوْلَ الْغُلَامِ يُصَبُّ عَلَيْهِ الْمَاءُ وَبَوْلُ الْجَارِيَةِ يُغْسَلُ ‏ ‏وَقَالَ ‏ ‏بَهْزٌ ‏ ‏غُسْلًا ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ ‏ ‏حُمَيْدٌ ‏ ‏كَانَ ‏ ‏عَطَاءٌ ‏ ‏يَرْوِيهِ عَنْ ‏ ‏أَبِي عَطَاءٍ ‏ ‏عَنْ ‏ ‏لُبَابَةَ ‏","","",""],[25644,25644,"","সেই ভাববাদী তার কাছে প্রার্থনা করেছিলেন এবং বলেছিলেন যে, আমি ঘুমিয়ে পড়েছিলাম । আপনার মধ্যে কেউ কেউ বলেছিল যে, আপনি এমন কিছু করতে শুরু করেছেন, যা ঈশ্বর তার হৃদয় কবর দিয়েছে । আমি বলেছিলাম যে, যখন প্রতিবেশীদের পরিষ্কার করা হয়, তখন আমি তোমার সঙ্গে দেখা করতে যাই ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏صَالِحٍ أَبِي الْخَلِيلِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أُمِّ الْفَضْلِ ‏ ‏قَالَتْ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ إِنِّي رَأَيْتُ فِي مَنَامِي ‏ ‏أَنَّ ‏ ‏فِي بَيْتِي ‏ ‏أَوْ حُجْرَتِي ‏ ‏عُضْوًا مِنْ أَعْضَائِكَ قَالَ تَلِدُ ‏ ‏فَاطِمَةُ ‏ ‏إِنْ شَاءَ اللَّهُ غُلَامًا فَتَكْفُلِينَهُ فَوَلَدَتْ ‏ ‏فَاطِمَةُ ‏ ‏حَسَنًا ‏ ‏فَدَفَعَتْهُ إِلَيْهَا فَأَرْضَعَتْهُ بِلَبَنِ ‏ ‏قُثَمَ ‏ ‏وَأَتَيْتُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا أَزُورُهُ فَأَخَذَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَضَعَهُ عَلَى صَدْرِهِ فَبَالَ عَلَى صَدْرِهِ فَأَصَابَ الْبَوْلُ ‏ ‏إِزَارَهُ ‏ ‏فَزَخَخْتُ ‏ ‏بِيَدِي عَلَى كَتِفَيْهِ فَقَالَ أَوْجَعْتِ ابْنِي أَصْلَحَكِ اللَّهُ ‏ ‏أَوْ قَالَ رَحِمَكِ اللَّهُ ‏ ‏فَقُلْتُ أَعْطِنِي ‏ ‏إِزَارَكَ ‏ ‏أَغْسِلْهُ فَقَالَ ‏ ‏إِنَّمَا يُغْسَلُ بَوْلُ الْجَارِيَةِ وَيُصَبُّ عَلَى بَوْلِ الْغُلَامِ ‏","","",""],[25645,25645,"","আমি আমার বাবার সাথে কথা বলেছি, আমি তার কাছে প্রার্থনা করেছি এবং সে বলে দিয়েছে বিজয় নাকি মালপত্রের বাক্সের কথা অস্বীকার না করার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْخَلِيلِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أُمِّ الْفَضْلِ ‏ ‏أَنَّ الرَّسُولَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُحَرِّمُ ‏ ‏الْإِمْلَاجَةُ ‏ ‏أَوْ ‏ ‏الْإِمْلَاجَتَانِ ‏","","",""],[25646,25646,"","আমরা সবচেয়ে ভালটা সম্বন্ধে বলেছিলাম । তার শান্তি, বার্তাবাহকরা","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏أُمِّ الْفَضْلِ ‏ ‏قَالَتْ ‏ ‏إِنَّ آخِرَ مَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَرَأَ فِي الْمَغْرِبِ سُورَةَ ‏ ‏الْمُرْسَلَاتِ ‏","","",""],[25647,25647,"","আমি তাকে বলেছি ভবিষ্যদ্বাণীর বাক্যের ব্যাপারে তারা অভিযোগ করেছে, ঈশ্বরের নাম আছে এবং তিনি তার ইচ্ছা পূরণ করতে যাচ্ছে আমার মা বলেছিলেন যে, ভাববাদী তার কাছে প্রার্থনা করেছিলেন এবং তার কাছে প্রার্থনা করেছিলেন । আমরা আমার বাবার বয়ফ্রেন্ডের ব্যাপারে কথা বলেছি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏حَدَّثَنِي ‏ ‏سَالِمٌ أَبُو النَّضْرِ ‏ ‏عَنْ ‏ ‏عُمَيْرٍ ‏ ‏مَوْلَى ‏ ‏أُمِّ الْفَضْلِ ‏ ‏أَنَّ ‏ ‏أُمَّ الْفَضْلِ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّهُمْ شَكُّوا فِي صَوْمِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏عَرَفَةَ ‏ ‏فَأَرْسَلَتْ إِلَيْهِ بِلَبَنٍ فَشَرِبَ وَهُوَ يَخْطُبُ النَّاسَ ‏ ‏بِعَرَفَةَ ‏ ‏عَلَى بَعِيرِهِ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏قَابُوسَ بْنِ مُخَارِقٍ ‏ ‏عَنْ ‏ ‏أُمِّ الْفَضْلِ ‏ ‏قَالَتْ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَتْ مِثْلَ حَدِيثِ ‏ ‏عَفَّانَ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏صَالِحٍ أَبِي الْخَلِيلِ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[25648,25648,"","আমরা আমাদের স্বপ্নের সবচেয়ে ভালো দিক নিয়ে কথা বলেছি, যার মধ্যে দুর্বল বাবাও ছিলেন। আমি ভবিষ্যদ্বাণীর মাধ্যমে যাচ্ছি, তাকে জানতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَالِمٍ أَبُو النَّضْرِ ‏ ‏عَنْ ‏ ‏عُمَيْرٍ ‏ ‏مَوْلَى ‏ ‏أُمِّ الْفَضْلِ ‏ ‏عَنْ ‏ ‏أُمِّ الْفَضْلِ ‏ ‏أَنَّهُمْ ‏ ‏تَمَارَوْا ‏ ‏فِي صَوْمِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏عَرَفَةَ ‏ ‏فَبَعَثَتْ إِلَيْهِ ‏ ‏بِقَدَحٍ ‏ ‏فِيهِ لَبَنٌ فَشَرِبَهُ ‏","","",""],[25649,25649,"","সে বলেছিল যে আমরা কেবল একটা ছেলের কথা বলেছি যে ঈশ্বরের পুত্র এমন এক ছেলের সন্তান যে তার মা যে দুঃখ পাচ্ছে, রাজকুমার আমার প্রভুর কথা পাঠ করে। লর্ড হয়তো আপনার গোপন কথা মনে করিয়ে দিতে পারে, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং সে এটা ধুলোয় ফেলে দেবে।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ الْمَعْنَى ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ ‏ ‏أُمَّ الْفَضْلِ بِنْتَ الْحَارِثِ ‏ ‏سَمِعَتْهُ وَهُوَ يُقْرَأُ ‏ ‏وَالْمُرْسَلَاتِ عُرْفًا ‏ ‏فَقَالَتْ يَا بُنَيَّ وَاللَّهِ لَقَدْ ذَكَّرْتَنِي بِقِرَاءَتِكَ هَذِهِ السُّورَةَ ‏ ‏إِنَّهَا لَآخِرُ مَا سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ بِهَا فِي الْمَغْرِبِ ‏","","",""],[25650,25650,"","আমার সঙ্গে কথা বলার জন্য মা আমাকে অনুরোধ করেছিলেন যেন ঈশ্বর সদয়ভাবে তার কাছে সাহায্য ও পরিত্রাণ করে থাকেন ।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزُ بْنُ أَسَدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ أَفْطَرَ ‏ ‏بِعَرَفَةَ ‏ ‏قَالَ وَحَدَّثَتْنِي ‏ ‏أُمُّ الْفَضْلِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْطَرَ ‏ ‏بِعَرَفَةَ ‏ ‏أَتَتْهُ بِلَبَنٍ فَشَرِبَهُ ‏","","",""],[25651,25651,"","আমার বাবার অবিশ্বাসের কথা বলছি, আমার মা পালক জয়ের জন্য... ...আমি ঐ ভবিষ্যদ্বাণীর মানুষটিকে অনুরোধ করব... ...আর আমি তাকে ক্ষমা করব... নবী তার কাছে প্রার্থনা করেছেন আর তাকে মনে করতে বলেছেন।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي الْخَلِيلِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أُمِّ الْفَضْلِ بِنْتِ الْحَارِثِ ‏ ‏سَأَلَ رَجُلٌ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتُحَرِّمُ الْمَصَّةُ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ فَذَكَرَهُ ‏","","",""],[25652,25652,"","আমরা সবচেয়ে ভালো বিষয়টা নিয়ে কথা বলেছিলাম । সে আমাকে প্রভুর কাছে এক স্মৃতি হিসেবে বোঝাতে চেয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏ابْنِ طَاوُسٍ ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ بْنِ عَبْدِ اللَّهِ بْنِ حَنْطَبٍ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏قَالَتْ ‏ ‏نَزَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْفَتْحِ بِأَعْلَى ‏ ‏مَكَّةَ ‏ ‏فَأَتَيْتُهُ فَجَاءَ ‏ ‏أَبُو ذَرٍّ ‏ ‏بِجَفْنَةٍ ‏ ‏فِيهَا مَاءٌ قَالَتْ إِنِّي لَأَرَى فِيهَا أَثَرَ الْعَجِينِ قَالَتْ فَسَتَرَهُ ‏ ‏يَعْنِي ‏ ‏أَبَا ذَرٍّ ‏ ‏فَاغْتَسَلَ ثُمَّ صَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَمَانِ رَكَعَاتٍ وَذَلِكَ فِي الضُّحَى ‏","","",""],[25653,25653,"","আমরা আমাদের সবচেয়ে ভালো ছেলের কথা বলেছি, আমি ভাববাদীকে প্রার্থনা করেছি যেন তিনি তার মৃত্যুতে জয় করেন। একজন ভিকটিম এসে বললো, আমি আমার মায়ের লুকানোর অনুমতি দিয়ে দেবো। উজ্জ্বল, উজ্জ্বল, উজ্জ্বল, উজ্জ্বল, উজ্জ্বল, উজ্জ্বল এক ছেলে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ ‏ ‏قَالَتْ ‏ ‏دَخَلْتُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْفَتْحِ وَهُوَ فِي ‏ ‏قُبَّةٍ ‏ ‏لَهُ فَوَجَدْتُهُ قَدْ ‏ ‏اغْتَسَلَ بِمَاءٍ كَانَ فِي ‏ ‏صَحْفَةٍ ‏ ‏إِنِّي لَأَرَى فِيهَا أَثَرَ الْعَجِينِ فَوَجَدْتُهُ ‏ ‏يُصَلِّي ضُحًى قُلْتُ ‏ ‏إِخَالُ ‏ ‏خَبَرَ ‏ ‏أُمِّ هَانِئٍ ‏ ‏هَذَا ‏ ‏ثَبَتَ ‏ ‏قَالَ نَعَمْ ‏ ‏قَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏الضُّحَى ‏","","",""],[25654,25654,"","আমরা জনতার কথা বলেছিলাম নাবিকের মুখ নিয়ে। কোড।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏وَكَانَ نَازِلًا عَلَيْهَا أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْفَتْحِ سُتِرَ عَلَيْهِ ‏ ‏فَاغْتَسَلَ فِي الضُّحَى فَصَلَّى ثَمَانِ رَكَعَاتٍ ‏ ‏لَا يُدْرَى أَقِيَامُهَا أَطْوَلُ أَمْ سُجُودُهَا ‏","","",""],[25655,25655,"","আমার মায়ের সাক্ষীর জন্য বাবার দুই ছেলের কথা বলছি... ...সে বলেছে আমার বাবা তার জন্য ভাল করেছে.","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏قَالَتْ ‏ ‏قَدِمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَكَّةَ ‏ ‏مَرَّةً وَلَهُ أَرْبَعُ ‏ ‏غَدَائِرَ ‏","","",""],[25656,25656,"","আমি হামাদাকে বললাম আমার বাবা যখন ছেলে ছিলেন তখন আমার বাবা কিভাবে মারা যান। সে পুত্র ছিল এমন এক ছেলে যে ছেলে ছিল যে পুত্র ছিল সে পুত্র। আমার বাবা একটা পবিত্র জায়গা হতে যাচ্ছে, আমার মায়ের সাথে যুদ্ধ করছিল। তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন এবং বলেছিলেন যে, তিনি আপনার কাছে প্রার্থনা করছিলেন । এ রকমই","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ أُسَامَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏حَاتِمُ بْنُ أَبِي صَغِيرَةَ ‏ ‏وَرَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَاتِمُ بْنُ أَبِي صَغِيرَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سِمَاكُ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏مَوْلَى ‏ ‏أُمِّ هَانِئٍ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏حَدَّثَتْنِي ‏ ‏أُمُّ هَانِئٍ ‏ ‏فَقَالَتْ ‏ ‏لِي ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ قَوْلِهِ تَعَالَى ‏ { ‏وَتَأْتُونَ فِي ‏ ‏نَادِيكُمْ ‏ ‏الْمُنْكَرَ ‏} ‏قَالَ ‏ ‏كَانُوا ‏ ‏يَخْذِفُونَ ‏ ‏أَهْلَ الطَّرِيقِ وَيَسْخَرُونَ مِنْهُمْ فَذَاكَ الْمُنْكَرُ الَّذِي كَانُوا يَأْتُونَ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏فَذَلِكَ قَوْلُهُ تَعَالَى ‏ { ‏وَتَأْتُونَ فِي ‏ ‏نَادِيكُمْ ‏ ‏الْمُنْكَرَ ‏}","","",""],[25657,25657,"","আমার বাবা আমার ভালবাসার কথা একবার বলতেন। আমার মা বললো, কেন সে একটা যন্ত্রের মৃত্যু বরণ করলো, যে মেশিনটা আমি তার থেকে টেনে টেনে নিয়ে গেলাম। সে একটা নির্বোধ আনন্দ করেছিল। সে আমাকে দেখে বৃত্তে যখন সে আমাকে বললো \"উঠ\" আমাকে দুইজন রক্ষক ভাড়া করে দিয়েছে... ...যে আমাদেরকে ভাড়ায় নিয়ে গেছে আর এতিমকে উদ্ধার করেছে। তারপর দুটো হাঁটু গেড়ে বসলে, ওর সাথে বিষ মিশিয়ে ফেলা আর তোমার নিঃশব্দে একদম স্পষ্ট।","‏ ‏حَدَّثَنَا ‏ ‏زيدُ بْنُ الْحُبَابِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مُرَّةَ ‏ ‏مَوْلَى ‏ ‏عَقِيلِ بْنِ أَبِي طَالِبٍ ‏ ‏عَنْ ‏ ‏فَاخِتَةَ أُمِّ هَانِئٍ ‏ ‏قَالَتْ ‏ ‏لَمَّا كَانَ يَوْمُ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏أَجَرْتُ ‏ ‏حَمْوَيْنِ لِي مِنْ الْمُشْرِكِينَ إِذْ طَلَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيْهِ ‏ ‏رَهْجَةُ ‏ ‏الْغُبَارِ فِي ‏ ‏مِلْحَفَةٍ ‏ ‏مُتَوَشِّحًا ‏ ‏بِهَا فَلَمَّا رَآنِي قَالَ مَرْحَبًا ‏ ‏بِفَاخِتَةَ أُمِّ هَانِئٍ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏أَجَرْتُ ‏ ‏حَمْوَيْنِ لِي مِنْ الْمُشْرِكِينَ فَقَالَ قَدْ ‏ ‏أَجَرْنَا ‏ ‏مَنْ ‏ ‏أَجَرْتِ ‏ ‏وَأَمَّنَّا مَنْ أَمَّنْتِ ثُمَّ أَمَرَ ‏ ‏فَاطِمَةَ ‏ ‏فَسَكَبَتْ لَهُ مَاءً ‏ ‏فَتَغَسَّلَ بِهِ فَصَلَّى ثَمَانِ رَكَعَاتٍ فِي الثَّوْبِ ‏ ‏مُتَلَبِّبًا ‏ ‏بِهِ وَذَلِكَ يَوْمَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏ضُحًى ‏","","",""],[25658,25658,"","আমরা আমার মাকে ঈশ্বরের কাছে পাঠানো হয়েছে, সে তাকে মাতাল মাতাল মাতাল মাতাল মাতাল মাতাল মাতাল সঙ্গে যেতে দিবে, তারপর সে মাতাল হয়ে তাকে খুন করবে এবং তাকে উদ্ধার করবে। টাক ঋতুতে আমি তার আত্মা আদেশ করেছি, আমি এমন কিছু বলার জন্য যে সে বলেছে... ...আমরা তাকে বলে দিয়েছি যে সে নাকি আমার বাবা চোর আর আমার মায়ের ব্যাপারে কথা বলেছি. আমার মায়ের ছেলে, যে হারিয়ে যাবে সে খুশি হবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ الطَّيَالِسِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَعْدَةَ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهَا ‏ ‏فَدَعَا بِشَرَابٍ فَشَرِبَ ثُمَّ نَاوَلَهَا فَشَرِبَتْ فَقَالَتْ يَا رَسُولَ اللَّهِ أَمَا إِنِّي كُنْتُ صَائِمَةً فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّائِمُ الْمُتَطَوِّعُ أَمِيرُ نَفْسِهِ إِنْ شَاءَ صَامَ وَإِنْ شَاءَ أَفْطَرَ ‏ ‏قَالَ ‏ ‏قُلْتُ لَهُ سَمِعْتَهُ أَنْتَ مِنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏قَالَ لَا ‏ ‏حَدَّثَنِيهِ ‏ ‏أَبُو صَالِحٍ ‏ ‏وَأَهْلُنَا ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏كُنْتُ أَسْمَعُ ‏ ‏سِمَاكًا ‏ ‏يَقُولُ حَدَّثَنَا ‏ ‏ابْنَ أُمِّ هَانِئٍ ‏ ‏فَأَتَيْتُ أَنَا خَيْرَهُمَا وَأَفْضَلَهُمَا فَسَأَلْتُهُ وَكَانَ يُقَالُ لَهُ ‏ ‏جَعْدَةُ ‏","","",""],[25659,25659,"","আমরা সেই বধিরদের কথা বলেছি, যাদের নিয়ে আমরা কথা বলেছি, কিন্তু আমার মনে হয় আমি এমন ভালো ছেলে, যে কিনা আগে কখনো আসেনি। পরিবেশ, আমাকে এটা করতে হবে আর তাকে খেলতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ثَابِتُ بْنُ يَزِيدَ أَبُو زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏هِلَالٌ يَعْنِي ابْنَ خَبَّابٍ ‏ ‏قَالَ ‏ ‏نَزَلْتُ أَنَا ‏ ‏وَمُجَاهِدٌ ‏ ‏عَلَى ‏ ‏يَحْيَى بْنِ جَعْدَةَ بْنِ أُمِّ هَانِئٍ ‏ ‏فَحَدَّثَنَا عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏قَالَتْ ‏ ‏أَنَا أَسْمَعُ قِرَاءَةَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏جَوْفِ ‏ ‏اللَّيْلِ وَأَنَا عَلَى ‏ ‏عَرِيشِي ‏ ‏هَذَا وَهُوَ عِنْدَ ‏ ‏الْكَعْبَةِ ‏","","",""],[25660,25660,"","আমার মায়ের কাছে মা বলেছিলেন, ঈশ্বর তাকে ধরে নিয়ে গেছেন । ...তারপর এক দূরের জায়গা থেকে উদ্ধার করবে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏وَابْنُ أَبِي بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏قَالَتْ ‏ ‏اغْتَسَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَيْمُونَةُ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ ‏ ‏قَصْعَةٍ ‏ ‏فِيهَا أَثَرُ الْعَجِينِ ‏","","",""],[25661,25661,"","আমরা তাদের থেকে ভালো কিছু পাওয়ার চেষ্টা করেছি তারা আমাদের বলেছে তাদের নিজেদের উপর পাশ দিয়ে যাওয়ার মানে কি। আমার মা এক নিশ্চিত কথা বলেছেন যে আপনার মা একবার বাবাকে দেখেছেন। ঈশ্বর যদি তাঁর জন্য প্রার্থনা করতেন এবং আমি আমার প্রভু, প্রভু, আমি হয়তো তাকে হত্যা করার জন্য আমার জীবন ভাড়া করে ফেলেছি । ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং জল সরবরাহ করেছেন এবং তিনি ভিক্ষা করে জল সরবরাহ করেছেন এবং তারপর তিনি এগিয়ে যান, যেন আলো বের হয় । আমি হাঁটু গেড়ে বসে আছি।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ عَمْرٍو ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ حُنَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِي مُرَّةَ ‏ ‏مَوْلَى ‏ ‏أُمِّ هَانِئٍ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏وَقَدْ رَأَيْتُ ‏ ‏أَبَا مُرَّةَ ‏ ‏وَكَانَ شَيْخًا قَدْ أَدْرَكَ ‏ ‏أُمَّ هَانِئٍ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏قَالَتْ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَ الْفَتْحِ فَقُلْتُ يَا رَسُولَ اللَّهِ قَدْ ‏ ‏أَجَرْتُ ‏ ‏حَمْوَيْنِ لِي فَزَعَمَ ابْنُ أُمِّي أَنَّهُ قَاتَلَهُ ‏ ‏تَعْنِي ‏ ‏عَلِيًّا ‏ ‏قَالَتْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏أَجَرْنَا ‏ ‏مَنْ ‏ ‏أَجَرْتِ ‏ ‏يَا ‏ ‏أُمَّ هَانِئٍ ‏ ‏وَصُبَّ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَاءٌ فَاغْتَسَلَ ثُمَّ ‏ ‏الْتَحَفَ ‏ ‏بِثَوْبٍ عَلَيْهِ وَخَالَفَ بَيْنَ طَرَفَيْهِ عَلَى ‏ ‏عَاتِقِهِ ‏ ‏فَصَلَّى الضُّحَى ثَمَانِي رَكَعَاتٍ ‏","","",""],[25662,25662,"","আমরা একজন মায়ের কথা বলেছিলাম, যিনি বলেছিলেন যে, তিনি তার গোপন বিষয়গুলো গোপন রাখার জন্য ফিরে আসার আগ পর্যন্ত ঘুম থেকে উঠেন । তার মায়ের সাথে কথা বলেছে, সে বলেছে সে হয়ত একজন সম্পদ, তুমি তাকে বলছ তুমি তাকে বলছ যে তুমি তোমাকে আঘাত করবে না।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏قَالَتْ ‏ ‏لَمَّا كَانَ يَوْمُ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏جَاءَتْ ‏ ‏فَاطِمَةُ ‏ ‏حَتَّى قَعَدَتْ عَنْ يَسَارِهِ وَجَاءَتْ ‏ ‏أُمُّ هَانِئٍ ‏ ‏وَقَعَدَتْ عَنْ يَمِينِهِ وَجَاءَتْ ‏ ‏الْوَلِيدَةُ ‏ ‏بِشَرَابٍ فَتَنَاوَلَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَشَرِبَ ثُمَّ نَاوَلَهُ ‏ ‏أُمَّ هَانِئٍ ‏ ‏عَنْ يَمِينِهِ فَقَالَتْ لَقَدْ كُنْتُ صَائِمَةً فَقَالَ لَهَا ‏ ‏أَشَيْءٌ تَقْضِينَهُ عَلَيْكِ قَالَتْ لَا قَالَ لَا يَضُرُّكِ إِذًا ‏","","",""],[25663,25663,"","আমি বাবার অমরত্ব নিয়ে কথা বলেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তাকে তার ভালবাসার জন্য আত্মসমর্পণ করা হবে আর পানির জলে বমি হবে অন্ধকার, সে দেখেছে, কেউ এটাকে বলে.","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏قَالَتْ ‏ ‏لَمَّا دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏حَجَبُوهُ ‏ ‏وَأُتِيَ بِمَاءٍ ‏ ‏فَاغْتَسَلَ ثُمَّ صَلَّى الضُّحَى ‏ ‏ثَمَانِيَ رَكَعَاتٍ مَا رَآهُ أَحَدٌ بَعْدَهَا صَلَّاهَا ‏","","",""],[25664,25664,"","আমার মা আমার সাথে কথা বলেছে, তার জন্য ঈশ্বর প্রার্থনা করেছেন এবং আমি তার জন্য প্রার্থনা করছি। সে নদীর কাছে যাওয়ার পর আত্মসমর্পণ করবে আর তাকে মাফ করে দিবে।","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏عَبْدَ اللَّهِ بْنَ الْحَارِثِ بْنِ نَوْفَلٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أُمَّ هَانِئٍ بِنْتَ أَبِي طَالِبٍ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى بَعْدَمَا ارْتَفَعَ النَّهَارُ يَوْمَ الْفَتْحِ ‏ ‏فَأَمَرَ بِثَوْبٍ فَسُتِرَ عَلَيْهِ فَاغْتَسَلَ ثُمَّ قَامَ فَرَكَعَ ‏ ‏ثَمَانِيَ رَكَعَاتٍ ‏ ‏لَا أَدْرِي أَقِيَامُهُ فِيهَا أَطْوَلُ أَوْ رُكُوعُهُ أَوْ سُجُودُهُ كُلُّ ذَلِكَ مِنْهُ مُتَقَارِبٌ ‏ ‏قَالَتْ فَلَمْ أَرَهُ سَبَّحَهَا قَبْلُ وَلَا بَعْدُ ‏","","",""],[25665,25665,"","আমরা একটা আবেগ নিয়ে কথা বলেছিলাম, যা আমরা চেষ্টা করে শেষ করেছিলাম এবং এটাকে ভেঙে ফেলার চেষ্টা করেছিলাম । তার মৃত্যুর সময় তাকে জিজ্ঞেস করা হয়, আর তারপর ফিরে এসে আমাকে তাড়া করে দেখতে আসে যে সে একটা আলখাল্লার টুকরো আর মসজিদের কথা বলছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏قَالَ ‏ ‏مَا أَخْبَرَنِي أَحَدٌ أَنَّهُ رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الضُّحَى غَيْرَ ‏ ‏أُمِّ هَانِئٍ ‏ ‏فَإِنَّهَا حَدَّثَتْ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ بَيْتَهَا يَوْمَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏فَاغْتَسَلَ وَصَلَّى ‏ ‏ثَمَانِيَ رَكَعَاتٍ مَا رَأَتْهُ صَلَّى صَلَاةً قَطُّ أَخَفَّ مِنْهَا غَيْرَ أَنَّهُ كَانَ يُتِمُّ الرُّكُوعَ وَالسُّجُودَ ‏","","",""],[25666,25666,"","আমরা খালি হাতে কথা বলেছি যেটা আমাকে সবচেয়ে ভালো কিছু খুঁজে পেতে হবে। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং আমার মায়ের কাছে লাইট দিয়ে আসবেন। সে বলবে সে আমার হাতে আছে। সে খোলা শেলটি জনতার মাঝে পৌঁছে যাবে এবং তারপর প্রার্থনা করবে। আমার মত মাথাও খারাপ.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ الْحَارِثِ ‏ ‏عَنْ صَلَاةِ الضُّحَى فَقَالَ أَدْرَكْتُ ‏ ‏أَصْحَابَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُمْ ‏ ‏مُتَوَافِرُونَ ‏ ‏فَمَا حَدَّثَنِي أَحَدٌ مِنْهُمْ أَنَّهُ رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الضُّحَى غَيْرَ ‏ ‏أُمِّ هَانِئٍ ‏ ‏فَإِنَّهَا قَالَتْ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْفَتْحِ يَوْمَ جُمُعَةٍ ‏ ‏فَاغْتَسَلَ ثُمَّ صَلَّى ‏ ‏ثَمَانِيَ رَكَعَاتٍ ‏","","",""],[25667,25667,"","আমরা তাদের অমরতা সম্পর্কে কথা বলেছি, তিনি বলেছিলেন যে আমার ছেলে মারা যাওয়ার জন্য আমার একটা আশীর্বাদ আছে, আমার বাবার অনুগ্রহ তার নিজের ঈশ্বর। ভালো হয়ে যাচ্ছি, সে ভালো হয়ে যাচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ الْجَحْشِيِّ ‏ ‏عَنْ ‏ ‏مُوسَى ‏ ‏أَوْ ‏ ‏فُلَانِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي رَبِيعَةَ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏قَالَ لَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اتَّخِذِي غَنَمًا يَا ‏ ‏أُمَّ هَانِئٍ ‏ ‏فَإِنَّهَا تَرُوحُ بِخَيْرٍ ‏ ‏وَتَغْدُو ‏ ‏بِخَيْرٍ ‏","","",""],[25668,25668,"","আমার মা একবার ঈশ্বরের কাছে যাওয়ার জন্য আমার বাবাকে দেখা গিয়েছে । তার কাছে প্রার্থনা করে একদিন আমার কাছে এসে আমার কাছে এসে পৌঁছাবে ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ الْمَخْزُومِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الضَّحَّاكُ بْنُ عُثْمَانَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ حُنَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِي مُرَّةَ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏أَنَّهَا رَأَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي ثَوْبٍ وَاحِدٍ مُخَالِفًا بَيْنَ طَرَفَيْهِ ثَمَانِ رَكَعَاتٍ ‏ ‏بِمَكَّةَ ‏ ‏يَوْمَ الْفَتْحِ ‏","","",""],[25669,25669,"","আমরা কথা বলেছি আমার বাবার ব্যাপারে একবার আমি কেমন বোধ করি কিন্তু কখনো ভাবিনি ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তার মায়ের উপর আলো বর্ষণ করবেন যে ছেলেটির হাতে ছিল। বেটি, সে একটা জায়গা প্রার্থনা করে আর তারপর প্রার্থনা করে আর এরপর সে হাঁটু গেড়ে বসে লোকেদের খুঁজে বের করে ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏قَالَ ‏ ‏لَمْ يُخْبِرْنَا أَحَدٌ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الضُّحَى إِلَّا ‏ ‏أُمَّ هَانِئٍ ‏ ‏فَإِنَّهَا قَالَتْ ‏ ‏دَخَلَ عَلَيَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْتِي ‏ ‏فَاغْتَسَلَ يَوْمَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏ثُمَّ صَلَّى ‏ ‏ثَمَانِيَ رَكَعَاتٍ يُخِفُّ فِيهِنَّ الرُّكُوعَ وَالسُّجُودَ ‏","","",""],[25670,25670,"","আমি শুনেছি যে, আমি আমার বাবার সাথে এটা নিয়ে যেতে চেষ্টা করেছি। আমি শুনেছি, আমি রাতভর প্রার্থনা করে ঈশ্বরের কাছে প্রার্থনা করেছি। আর আমি আমার বিয়েতে আছি।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏أَبِي الْعَلَاءِ الْعَبْدِيِّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ جَعْدَةَ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَسْمَعُ قِرَاءَةَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِاللَّيْلِ وَأَنَا عَلَى ‏ ‏عَرِيشِي ‏","","",""],[25671,25671,"","বাবার জন্য আমার বাবার খুশিতে সাহায্য করার জন্য আমরা বেশ কয়েকবার কথা বলেছি। আমার মায়ের ছোট বোন আমার কাছের যে আমাকে খোলার সময় বলেছিল, আমি তাদের ছেড়ে চলে যেতে দিয়েছি। আমি তাদের সব সময় করব, আর তারপর আমার মায়ের ছেলেকে তার সাথে রাত কাটাতে হবে, ঈশ্বর আদেশ দিয়েছেন তাকে আর আত্মসমর্পণ করতে, আমি তাকে খুঁজে পেয়েছি, আর তার গৌরব খুঁজে পেয়েছি যা পাওয়া গেছে তা পেয়ে গেছে আমাকে খুঁজে বের করো, সে এটা ছেড়ে দিবে, আমি তাকে খুন করতে বলবো, নাহলে আমাকে ভাড়া করা হবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مُرَّةَ ‏ ‏مَوْلَى ‏ ‏فَاخِتَةَ أُمِّ هَانِئٍ ‏ ‏عَنْ ‏ ‏فَاخِتَةَ أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ ‏ ‏قَالَتْ ‏ ‏لَمَّا كَانَ يَوْمُ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏أَجَرْتُ ‏ ‏رَجُلَيْنِ مِنْ ‏ ‏أَحْمَائِي ‏ ‏فَأَدْخَلْتُهُمَا بَيْتًا وَأَغْلَقْتُ عَلَيْهِمَا بَابًا فَجَاءَ ابْنُ أُمِّي ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏فَتَفَلَّتَ عَلَيْهِمَا بِالسَّيْفِ قَالَتْ فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ أَجِدْهُ وَوَجَدْتُ ‏ ‏فَاطِمَةَ ‏ ‏فَكَانَتْ أَشَدَّ عَلَيَّ مِنْ زَوْجِهَا قَالَتْ فَجَاءَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيْهِ أَثَرُ الْغُبَارِ فَأَخْبَرْتُهُ فَقَالَ يَا ‏ ‏أُمَّ هَانِئٍ ‏ ‏قَدْ ‏ ‏أَجَرْنَا ‏ ‏مَنْ ‏ ‏أَجَرْتِ ‏ ‏وَأَمَّنَّا مَنْ أَمَّنْتِ ‏","","",""],[25672,25672,"","বাবার মৃত্যুর জন্য একবার বাবার ভালোর কথা বলেছিলাম, সে এটা করতে গিয়েছিল আর সে স্বপ্নের অধিকারী হবে। আমি একজন মা, প্রভু, ঈশ্বরের কাছে, আমার ছেলে হতে হবে, সে যদি চলে যায়, সে ঠিক থাকবে, সে তার ডুবন্ত থেকে তাকে উদ্ধার করেছে, সে আমার জন্য এক সারিতে চড়ে গেছে। আমার বাবা তার ভাইকে ধোঁকা দেয়ার জন্য মারা যাচ্ছে, আমার মায়ের কথা শোন, আমার বাবা আমাকে ঈশ্বরের দয়ায় যেতে বলেছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏أَبِي مُرَّةَ ‏ ‏مَوْلَى ‏ ‏عَقِيلِ بْنِ أَبِي طَالِبٍ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏أَنَّهَا ذَهَبَتْ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْفَتْحِ قَالَتْ فَوَجَدْتُهُ يَغْتَسِلُ ‏ ‏وَفَاطِمَةُ ‏ ‏تَسْتُرُهُ بِثَوْبٍ فَسَلَّمْتُ وَذَلِكَ ضُحًى فَقَالَ مَنْ هَذَا فَقُلْتُ أَنَا ‏ ‏أُمُّ هَانِئٍ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ زَعَمَ ابْنُ أُمِّي أَنَّهُ قَاتِلٌ رَجُلًا ‏ ‏أَجَرْتُهُ ‏ ‏فُلَانَ بْنَ هُبَيْرَةَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏أَجَرْنَا ‏ ‏مَنْ ‏ ‏أَجَرْتِ ‏ ‏يَا ‏ ‏أُمَّ هَانِئٍ ‏ ‏فَلَمَّا فَرَغَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ غُسْلِهِ قَامَ فَصَلَّى ‏ ‏ثَمَانِيَ رَكَعَاتٍ مُلْتَحِفًا فِي ثَوْبٍ ‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ ‏ ‏هَذَا الْحَدِيثَ ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏مَوْلَى ‏ ‏عُمَيْرِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏أَبَا مُرَّةَ ‏ ‏مَوْلَى ‏ ‏أُمِّ هَانِئٍ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏أُمَّ هَانِئٍ بِنْتَ أَبِي طَالِبٍ ‏ ‏ذَهَبَتْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْفَتْحِ فَذَكَرَ الْحَدِيثَ ‏","","",""],[25673,25673,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যে আমরা আমার মাকে নিয়ে দাঙ্গার সৃষ্টি করেছি আর সে এটা পেয়েছে, সে একটা শান্ত শান্তি পাবে আর তারপর সে আমাকে মারতে চাইবে। ছেড়ে দাও সে বুঝতে পারবে না যদি তুমি আমার আত্মা তৈরি কর আর তুমি কিছু একটা ভুল করেছ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَعْدَةَ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏وَهِيَ جَدَّتُهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهَا يَوْمَ الْفَتْحِ فَأُتِيَ بِشَرَابٍ فَشَرِبَ ثُمَّ نَاوَلَنِي فَقُلْتُ إِنِّي صَائِمَةٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْمُتَطَوِّعَ أَمِيرٌ عَلَى نَفْسِهِ فَإِنْ شِئْتِ فَصُومِي وَإِنْ شِئْتِ فَأَفْطِرِي ‏","","",""],[25674,25674,"","হামাদের ব্যাপারে আমরা কথা বলেছি কিন্তু আমরা একটি ছেলে নিয়ে কথা বলেছি যে ছেলে জন্ম নিয়েছে তার জন্য। আমার মা ঈশ্বরের কাছে প্রার্থনা করেছেন যে তাকে ঈশ্বরের কাছে প্রার্থনা করতে হবে। একটা তরুণকে বল, আমি তোমাকে বলতে চাই এটা একটা শিকারীর কাজ যেটা মাঝে মাঝে খুব উজ্জ্বল ছিল.","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكُ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏هَارُونَ ابْنِ بِنْتِ أُمِّ هَانِئٍ ‏ ‏أَوْ ‏ ‏ابْنِ أُمِّ هَانِئٍ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَرِبَ شَرَابًا فَنَاوَلَهَا لِتَشْرَبَ فَقَالَتْ إِنِّي صَائِمَةٌ وَلَكِنْ كَرِهْتُ أَنْ أَرُدَّ ‏ ‏سُؤْرَكَ ‏ ‏فَقَالَ ‏ ‏يَعْنِي ‏ ‏إِنْ كَانَ قَضَاءً مِنْ رَمَضَانَ فَاقْضِي يَوْمًا مَكَانَهُ وَإِنْ كَانَ تَطَوُّعًا فَإِنْ شِئْتِ فَاقْضِي وَإِنْ شِئْتِ فَلَا تَقْضِي ‏","","",""],[25675,25675,"","সে আমার বাবার বইতে গিয়েছে, তার লেখা দিয়ে আমরা অনেক ভালো করেছি। আমার বাবা ছিলেন একজন বন্ধ্যা মা। আমি বলেছি, মাই লর্ড। আমি হয়ত আমার বড় হয়েছি নরকের আগুনে পরিণত হয়েছি। আমি এটা নিয়ে কথা বলেছি। আমি এখন আমার বাবা খুব ভালো করে জানেন, আমি কি, আমি কি করেছি? আমি জানি, আমি জানি, আমি কি, আমি জানি, আমি জানি, আমি এটা আমার বাবা, আমি কি করেছি? আমি যদি আমার বাবা আমাকে ছেড়ে দেয়, আমি কি করে, আমি এটা একটা নরকের টুকরো টুকরো করে ফেলি। আর আমি যদি আমার বাবা না, আমি শুধু একটা আগুনের মধ্যে পড়ে যাই, আমি কি করবো? আমি কি করবো? আমি জানি? আমি জানি না? আমি কি জানি? আমি জানি না? আমি জানি, আমি জানি না, আমি যদি আমার বাবা আমাকে এটা একটা ছোট মেয়ে না? আমি কি করেছে? আমি জানি না? আমি তো, আমি জানি না? আমি জানি, আমি জানি, আমি কি হয়েছে? আমি জানি না। আমি জানি না? আমি জানি, আমি জানি না, আমি কিভাবে বলেছি যে এটা আমার কাজের সাথে করা হয়েছে, তিনি শত বছর ভালোর জন্য ঠিক করছেন, আপনি ঈশ্বরের হলের একটি গৌরব কথা দিচ্ছি, আল্লাহ আমার উপর দয়া করে, আমি পানিতে পানি এবং অন্ধকারের আলো দিয়ে তার সাথে আসছি।","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُوسَى بْنُ خَلَفٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ ‏ ‏قَالَ قَالَتْ ‏ ‏مَرَّ بِي ذَاتَ يَوْمٍ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنِّي قَدْ كَبِرْتُ وَضَعُفْتُ ‏ ‏أَوْ كَمَا قَالَتْ ‏ ‏فَمُرْنِي بِعَمَلٍ أَعْمَلُهُ وَأَنَا جَالِسَةٌ قَالَ ‏ ‏سَبِّحِي اللَّهَ مِائَةَ تَسْبِيحَةٍ فَإِنَّهَا تَعْدِلُ لَكِ مِائَةَ رَقَبَةٍ تُعْتِقِينَهَا مِنْ وَلَدِ ‏ ‏إِسْمَاعِيلَ ‏ ‏وَاحْمَدِي اللَّهَ مِائَةَ تَحْمِيدَةٍ تَعْدِلُ لَكِ مِائَةَ فَرَسٍ ‏ ‏مُسْرَجَةٍ ‏ ‏مُلْجَمَةٍ تَحْمِلِينَ عَلَيْهَا فِي سَبِيلِ اللَّهِ وَكَبِّرِي اللَّهَ مِائَةَ تَكْبِيرَةٍ فَإِنَّهَا تَعْدِلُ لَكِ مِائَةَ ‏ ‏بَدَنَةٍ ‏ ‏مُقَلَّدَةٍ ‏ ‏مُتَقَبَّلَةٍ وَهَلِّلِي ‏ ‏اللَّهَ مِائَةَ تَهْلِيلَةٍ ‏ ‏قَالَ ‏ ‏ابْنُ خَلَفٍ ‏ ‏أَحْسِبُهُ قَالَ تَمْلَأُ مَا بَيْنَ السَّمَاءِ وَالْأَرْضِ ‏ ‏وَلَا يُرْفَعُ يَوْمَئِذٍ لِأَحَدٍ عَمَلٌ إِلَّا أَنْ يَأْتِيَ بِمِثْلِ مَا أَتَيْتِ بِهِ ‏","","",""],[25676,25676,"","বাবার ছেলের কথা বলেছি, আমাকে বিষগ্রস্ত রানী, আমি কখনোই পাইলটকে আমার নিজের এলাকায় যেতে দেব না।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ لِي إِلَّا مَا أَدْخَلَ ‏ ‏الزُّبَيْرُ ‏ ‏بَيْتِي قَالَ ‏ ‏أَنْفِقِي وَلَا ‏ ‏تُوكِي ‏ ‏فَيُوكَى ‏ ‏عَلَيْكِ ‏","","",""],[25677,25677,"","আমরা দুই বছর ধরে তার বাবার প্রতি তার জেদের কথা বলেছিলাম তার মায়ের সাথে বলেছে আমার মা ছিল শিয়াল. আমি প্রার্থনা করব তার জন্য প্রার্থনা করব আর তার জন্য আমরা প্রার্থনা করব তিনি ভয় পেয়েছিলেন যে, তার বাবা নিজেকে একজন যাজক বলে ডাকতেন এবং বলেন যে, তিনি একজন শহীদ ।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏قَالَتْ ‏ ‏أَتَتْنِي ‏ ‏أُمِّي ‏ ‏رَاغِبَةً فِي عَهْدِ ‏ ‏قُرَيْشٍ ‏ ‏وَهِيَ مُشْرِكَةٌ فَسَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَصِلُهَا قَالَ نَعَمْ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏مِثْلَهُ وَقَالَ وَهِيَ مُشْرِكَةٌ فِي عَهْدِ ‏ ‏قُرَيْشٍ ‏ ‏وَمُدَّتِهِمْ إِذْ عَاهَدُوا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[25678,25678,"","আমরা সবাই কথা বলেছি, আমরা একটা ছেলে কথা শুনেছি, যখন সে বলেছিল যে সে আমার মা আর মা ঈশ্বরের জন্য আছে যা দেখা যায়, ঈশ্বর তার কাছে প্রার্থনা করেছেন আর তার কাছে প্রার্থনা করেছেন। আমার মা তার ঈশ্বরের কাছে নিজেকে উৎসর্গ করেছে, আমরা তোমার মায়ের প্রার্থনা করব।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُرْوَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏قَدِمَتْ ‏ ‏أُمِّي ‏ ‏وَهِيَ مُشْرِكَةٌ فِي عَهْدِ ‏ ‏قُرَيْشٍ ‏ ‏إِذْ عَاهَدُوا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتَفْتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ ‏ ‏أُمِّي ‏ ‏قَدِمَتْ وَهِيَ ‏ ‏رَاغِبَةٌ ‏ ‏أَفَأَصِلُهَا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَمْ صِلِي أُمَّكِ ‏","","",""],[25679,25679,"","আমরা ঈশ্বরের প্রেম নিয়ে কথা বলেছি আমরা প্রেমে বাস করার কথা বলেছিলাম. আমার বাবা ছিলেন ঈশ্বরের একজন নায়ক, তার স্বপ্ন উদ্ধার করতে হবে একদিন... ...আর আমার বাবা তাকে একদিন তার সাথে করে যেতে হবে. আমার বাবার জীবন, তার জন্য অপেক্ষা করা, তার সাথে লড়াই করতে পারবে না। তুমি তাকে ভুল পথে পরিচালিত করেছ এবং তার কাছে প্রার্থনা করেছে যেন সে আত্মসমর্পণ করে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبَّادِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏أَسْمَاءَ بِنْتَ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حُجَّاجًا حَتَّى إِذَا كُنَّا ‏ ‏بِالْعَرْجِ ‏ ‏نَزَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَلَسَتْ ‏ ‏عَائِشَةُ ‏ ‏إِلَى جَنْبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَلَسْتُ إِلَى جَنْبِ أَبِي وَكَانَتْ زِمَالَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَزِمَالَةُ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَاحِدَةً مَعَ غُلَامِ ‏ ‏أَبِي بَكْرٍ ‏ ‏فَجَلَسَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَنْتَظِرُهُ أَنْ يَطْلُعَ عَلَيْهِ فَطَلَعَ وَلَيْسَ مَعَهُ بَعِيرُهُ فَقَالَ أَيْنَ بَعِيرُكَ قَالَ قَدْ أَضْلَلْتُهُ الْبَارِحَةَ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏بَعِيرٌ وَاحِدٌ تُضِلُّهُ ‏ ‏فَطَفِقَ ‏ ‏يَضْرِبُهُ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَبَسَّمُ وَيَقُولُ ‏ ‏انْظُرُوا إِلَى هَذَا الْمُحْرِمِ وَمَا يَصْنَعُ ‏","","",""],[25680,25680,"","আমরা একটি নির্দিষ্ট উপজাতি কথা বলেছি যে আমরা আরো করেছি মানে আমার বাবার ছেলে একজন শিকারী, যে বলেছে সে হতে পারে সেই লোক যে ব ্ যক ্ তি উপুড় হয়ে মুখে ভর দিয়ে চলে , সে-ই কি ঐ যে , যার জন ্ যে খুবই বৃদ ্ ধি করেছে ? রাজা হতে পেরে আমি আনন্দিত যে তারা বলতে চাচ্ছে যে একজন যাজকের ছেলে একটা কুত্তার বাচ্চা খুন করেছে। আমরা একটা ছেলের সাথে যুদ্ধ করেছি যে তার প্রভুর সাথে পালিয়ে গিয়েছিল। তার জন্য প্রার্থনা করুন এবং আমরা নরকের মধ্য দিয়ে যাচ্ছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ يَعْنِي ابْنَ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ الزُّبَيْرِ ‏ ‏أَفْرِدُوا بِالْحَجِّ وَدَعُوا قَوْلَ هَذَا ‏ ‏يَعْنِي ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَقَالَ ‏ ‏ابْنُ الْعَبَّاسِ ‏ ‏أَلَا تَسْأَلُ ‏ ‏أُمَّكَ ‏ ‏عَنْ هَذَا فَأَرْسَلَ إِلَيْهَا فَقَالَتْ صَدَقَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حُجَّاجًا ‏ ‏فَأَمَرَنَا فَجَعَلْنَاهَا عُمْرَةً ‏ ‏فَحَلَّ لَنَا الْحَلَالُ حَتَّى سَطَعَتْ ‏ ‏الْمَجَامِرُ ‏ ‏بَيْنَ النِّسَاءِ وَالرِّجَالِ ‏","","",""],[25681,25681,"","ঈশ্বর এমন একজন নারীকে উদ্ধার করেছেন, যিনি তার প্রাণ হারিয়েছে । সে বলছে ভগবানের কাছে প্রার্থনা করেছে, সে এটা করেছে আর সে ঈশ্বরের দোহাই ছেড়ে ঈশ্বরের কাছে প্রার্থনা করবে এবং তার স্পর্শ করবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏امْرَأَةٌ فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ لِي ابْنَةً عَرِيسًا وَإِنَّهُ أَصَابَتْهَا حَصْبَةٌ ‏ ‏فَتَمَرَّقَ ‏ ‏شَعْرُهَا ‏ ‏أَفَأَصِلُهُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْوَاصِلَةَ ‏ ‏وَالْمُسْتَوْصِلَةَ ‏","","",""],[25682,25682,"","আমার সাথে যা ঘটেছে তার কথা আমরা বললাম, আমরা ঈশ্বরের কাছে প্রার্থনা করেছি, আর তিনি আমাদের সবার উপর গুলি করে মেরে ফেলার প্রতিজ্ঞা করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏نَحَرْنَا فِي عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَسًا فَأَكَلْنَا مِنْهُ ‏","","",""],[25683,25683,"","আমি সেই নবী যে কিনা আমার সাথে ঘটেছে, আমি সেই অভিশাপের কথা বলছি। আমি সেই ভাববাদী যে তার জন্য প্রার্থনা করে একজন নারীকে পাঠিয়েছি যে বলল ঈশ্বরই ঈশ্বর, যিনি এত বধির। ঈশ্বর তাকে দিয়েছেন যে, ঈশ্বর আমাদের কথা বলছেন। তাঁর দয়া এবং তারপর তাঁকে পানি দিয়ে গ্রহণ করে তার কাছে প্রার্থনা করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏امْرَأَةٌ فَقَالَتْ يَا رَسُولَ اللَّهِ الْمَرْأَةُ يُصِيبُهَا مِنْ دَمِ حَيْضِهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِتَحُتَّهُ ‏ ‏ثُمَّ ‏ ‏لِتَقْرِضْهُ ‏ ‏بِمَاءٍ ثُمَّ لِتُصَلِّي فِيهِ ‏","","",""],[25684,25684,"","আমরা আমাদের করা দুঃখ নিয়ে কথা বলেছি, কিন্তু আমরা জানি এটা মায়ের বিষে আঘাত করা খুব খারাপ। সে মায়ের কাছে ঈশ্বরের প্রার্থনায় এসেছে, আর সে একজন নারীকে সাহায্য করবে, ঈশ্বর আমাকে জিজ্ঞেস করলেন আমি ব্যথা পাচ্ছি। ঈশ্বর তাঁর কাছে প্রার্থনা করতে বলেছেন না... ...আর বিষ আবার না করা হয় নি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏جَاءَتْ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏امْرَأَةٌ فَقَالَتْ يَا رَسُولَ اللَّهِ إِنِّي عَلَى ضَرَّةٍ فَهَلْ عَلَيَّ جُنَاحٌ أَنْ أَتَشَبَّعَ مِنْ زَوْجِي بِمَا لَمْ يُعْطِنِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُتَشَبِّعُ بِمَا لَمْ يُعْطَ كَلَابِسِ ثَوْبَيْ ‏ ‏زُورٍ ‏","","",""],[25685,25685,"","আমি ঈশ্বরের কাছে প্রার্থনা করতে চাই যেন তিনি তা গ্রহণ করেন এবং আমি ব্যর্থ হই বা ব্যর্থ হই, অথবা ব্যর্থ হই ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْفَحِي ‏ ‏أَوْ ارْضَحِي أَوْ أَنْفِقِي وَلَا ‏ ‏تُوعِي ‏ ‏فَيُوعِيَ ‏ ‏اللَّهُ عَلَيْكِ وَلَا ‏ ‏تُحْصِي ‏ ‏فَيُحْصِيَ ‏ ‏اللَّهُ عَلَيْكِ ‏","","",""],[25686,25686,"","আমাদের সাথে যা ঘটেছে তার ব্যাপারে কথা বলার জন্য বাবার সবচেয়ে ভাল মানুষ খুঁজে পাওয়া নিয়ে আমরা কথা বলতাম, আমরা ভয়ে হলে থেমে যেতাম।","‏ ‏حَدَّثَنَا ‏ ‏عَثَّامُ بْنُ عَلِيٍّ أَبُو عَلِيٍّ الْعَامِرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏إِنْ ‏ ‏كُنَّا لَنُؤْمَرُ ‏ ‏بِالْعَتَاقَةِ ‏ ‏فِي صَلَاةِ الْخُسُوفِ ‏","","",""],[25687,25687,"","আমরা ঈশ্বরের প্রার্থনা নিয়ে কথা বলার চেষ্টা করেছি, ঈশ্বর এটা করেছেন এবং সূর্যের হলের আরোগ্যের ব্যবস্থা করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏وَلَقَدْ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْعَتَاقَةِ ‏ ‏فِي صَلَاةِ كُسُوفِ الشَّمْسِ ‏","","",""],[25688,25688,"","আমি ঈশ্বরের কাছে প্রার্থনা করি যেন তিনি তাঁর প্রার্থনা এবং অন্যান্য কাজ করেন । আমি এত কঠিন ভাবে প্রতারণা করেছি, আর আমি রাত কাটাবো যাতে এটা সম্ভব হয়। কেউ কিছু দেখে না, আগুন তোমাকে বলতে পারে ঐ জংলীর গন্ধের কাছে যেতে, আমি তোমাকে বলছি তুমি কি জানো, হয় নিরাপদ থাকা হোক, না হলে সে জানে। বল সে আমাদের কাছে এক সুস্থির ঈশ্বর, আমাদের তিন বার করতে হবে, তার উপর বিশ্বাস রাখতে হবে, হয় ভন্ড বা বিদায়ী কেউ কখনো জানতে পারবে না তুমি কি বলেছ। আমি যা বলেছি","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏خَسَفَتْ ‏ ‏الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَخَلْتُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَقُلْتُ مَا شَأْنُ النَّاسِ يُصَلُّونَ فَأَشَارَتْ بِرَأْسِهَا إِلَى السَّمَاءِ فَقُلْتُ ‏ ‏آيَةٌ ‏ ‏قَالَتْ نَعَمْ فَأَطَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْقِيَامَ جِدًّا حَتَّى ‏ ‏تَجَلَّانِي ‏ ‏الْغَشْيُ ‏ ‏فَأَخَذْتُ ‏ ‏قِرْبَةً ‏ ‏إِلَى جَنْبِي فَأَخَذْتُ أَصُبُّ عَلَى رَأْسِي الْمَاءَ فَانْصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ ‏ ‏تَجَلَّتْ ‏ ‏الشَّمْسُ فَخَطَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ أَمَّا بَعْدُ ‏ ‏مَا مِنْ شَيْءٍ لَمْ أَكُنْ رَأَيْتُهُ إِلَّا قَدْ رَأَيْتُهُ فِي مَقَامِي هَذَا حَتَّى الْجَنَّةُ وَالنَّارُ إِنَّهُ قَدْ أُوحِيَ إِلَيَّ أَنَّكُمْ ‏ ‏تُفْتَنُونَ ‏ ‏فِي الْقُبُورِ قَرِيبًا أَوْ مِثْلَ ‏ ‏فِتْنَةِ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏ ‏لَا أَدْرِي أَيَّ ذَلِكَ ‏ ‏قَالَتْ ‏ ‏أَسْمَاءُ ‏ ‏يُؤْتَى أَحَدُكُمْ فَيُقَالُ مَا عِلْمُكَ بِهَذَا الرَّجُلِ فَأَمَّا الْمُؤْمِنُ ‏ ‏أَوْ ‏ ‏الْمُوقِنُ ‏ ‏لَا أَدْرِي أَيَّ ذَلِكَ ‏ ‏قَالَتْ ‏ ‏أَسْمَاءُ ‏ ‏فَيَقُولُ هُوَ ‏ ‏مُحَمَّدٌ ‏ ‏هُوَ رَسُولُ اللَّهِ جَاءَنَا بِالْبَيِّنَاتِ وَالْهُدَى فَأَجَبْنَا وَاتَّبَعْنَا ثَلَاثَ مِرَارٍ فَيُقَالُ لَهُ قَدْ كُنَّا نَعْلَمُ أَنْ كُنْتَ لَتُؤْمِنُ بِهِ فَنَمْ صَالِحًا وَأَمَّا الْمُنَافِقُ ‏ ‏أَوْ ‏ ‏الْمُرْتَابُ ‏ ‏لَا يَدْرِي أَيَّ ذَلِكَ ‏ ‏قَالَتْ ‏ ‏أَسْمَاءُ ‏ ‏فَيَقُولُ مَا أَدْرِي ‏ ‏سَمِعْتُ النَّاسَ يَقُولُونَ شَيْئًا فَقُلْتُ ‏","","",""],[25689,25689,"","আমরা তার নামের প্রতি আবেগ নিয়ে কথা বলেছি যে সে তার নাম হবে পানি আর তার পকেট বলা হয়েছে তাকে আর তার শান্তি নিশ্চিত করতে আদেশ করা হয়েছে তারা হারিয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏إِنَّهَا كَانَتْ إِذَا أُتِيَتْ بِالْمَرْأَةِ لِتَدْعُوَ لَهَا صَبَّتْ الْمَاءَ بَيْنَهَا وَبَيْنَ ‏ ‏جَيْبِهَا ‏ ‏وَقَالَتْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَنَا أَنْ نُبْرِدَهَا بِالْمَاءِ وَقَالَ إِنَّهَا مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ ‏","","",""],[25690,25690,"","আমরা যা বলেছিলাম, সেই বিষয়ে নীরব থাকার ভয় সম্বন্ধে আমরা কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏أَفْطَرْنَا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي يَوْمِ ‏ ‏غَيْمٍ ‏ ‏فِي رَمَضَانَ ثُمَّ طَلَعَتْ الشَّمْسُ قُلْتُ ‏ ‏لِهِشَامٍ ‏ ‏أُمِرُوا بِالْقَضَاءِ قَالَ وَبُدٌّ مِنْ ذَاكَ ‏","","",""],[25691,25691,"","আমরা তার বাবার কথা বলেছিলাম এবং আমি বিষ খেতে ভয় পেয়েছিলাম। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং পিটের বাবাকে উদ্ধার করেছেন। আমার বাবাকে একজন জিনিয়াস হিসেবে বলেছিলেন আর আমি হয়তো এমন কিছু খুঁজে পেতে পারি, যা হয়তো ভুল বলে আমি ভুল করেছি ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَفَاطِمَةُ بِنْتُ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏صَنَعْتُ ‏ ‏سُفْرَةَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِ ‏ ‏أَبِي بَكْرٍ ‏ ‏حِينَ أَرَادَ أَنْ يُهَاجِرَ قَالَتْ فَلَمْ نَجِدْ ‏ ‏لِسُفْرَتِهِ ‏ ‏وَلَا ‏ ‏لِسِقَائِهِ ‏ ‏مَا نَرْبِطُهُمَا بِهِ قَالَتْ فَقُلْتُ ‏ ‏لِأَبِي بَكْرٍ ‏ ‏وَاللَّهِ مَا أَجِدُ شَيْئًا أَرْبِطُهُ بِهِ إِلَّا ‏ ‏نِطَاقِي ‏ ‏قَالَ فَقَالَ ‏ ‏شُقِّيهِ ‏ ‏بِاثْنَيْنِ فَارْبِطِي بِوَاحِدٍ ‏ ‏السِّقَاءَ ‏ ‏وَالْآخَرِ ‏ ‏السُّفْرَةَ ‏ ‏فَلِذَلِكَ سُمِّيَتْ ذَاتَ النِّطَاقَيْنِ ‏","","",""],[25692,25692,"","আমরা একজন মহিলাকে ফোন করেছি যে বলেছে সে কখনো করেনি। ফুল।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏فَاطِمَةُ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏أَنَّ امْرَأَةً قَالَتْ يَا رَسُولَ اللَّهِ إِنَّ لِي ضَرَّةً فَهَلْ عَلَيَّ ‏ ‏جُنَاحٌ ‏ ‏إِنْ تَشَبَّعْتُ مِنْ زَوْجِي بِغَيْرِ الَّذِي يُعْطِينِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُتَشَبِّعُ بِمَا لَمْ يُعْطَ كَلَابِسِ ثَوْبَيْ ‏ ‏زُورٍ ‏","","",""],[25693,25693,"","আমরা আমাদের সকলের কাছে ঈশ্বরের কাছে প্রার্থনা করেছিলাম এবং আত্মসমর্পণ করেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏فَاطِمَةُ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏أَكَلْنَا لَحْمَ فَرَسٍ لَنَا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[25694,25694,"","আমি শপথ নিয়ে কথা বলেছি। আমার বাবাকে তার শান্তির জন্য... ...তার কাছে ঈশ্বরের কাছে প্রার্থনা করার জন্য... তার মাথাকে প্রভু ও পালনকর ্ তার কাছে নিয়ে যাও","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏فَاطِمَةُ بِنْتُ الْمُنْذِرِ ‏ ‏وَوَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّ امْرَأَةً مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَتْ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِي بُنَيَّةً عَرِيسًا وَإِنَّهُ ‏ ‏تَمَرَّقَ ‏ ‏شَعْرُهَا فَهَلْ عَلَيَّ ‏ ‏جُنَاحٌ ‏ ‏إِنْ وَصَلْتُ رَأْسَهَا قَالَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْوَاصِلَةَ ‏ ‏وَالْمُسْتَوْصِلَةَ ‏","","",""],[25695,25695,"","আমি আমার বাবার সাথে কথা বলার বদলে বাবার সাথে কথা বলেছি। আমি দুঃখিত যে একজন মহিলা সব থেকে ভালো ভাববাদী বলেছেন যে একজন পরাজিত হবে। তারপর পানি দিয়ে এটা পরিষ্কার করে প্রার্থনা করো।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏فَاطِمَةُ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏أَنَّ امْرَأَةً أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ إِحْدَانَا يُصِيبُ ثَوْبَهَا مِنْ دَمِ الْحَيْضَةِ قَالَتْ ‏ ‏تَحُتُّهُ ‏ ‏ثُمَّ ‏ ‏لِتَقْرُصْهُ ‏ ‏بِالْمَاءِ ثُمَّ ‏ ‏لِتَنْضَحْهُ ‏ ‏ثُمَّ تُصَلِّي فِيهِ ‏","","",""],[25696,25696,"","আমরা আমার ভালোবাসার নাম সতর্কতার সাথে বলছি, ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তাকে রক্ষা করার জন্য বা তাকে রক্ষা করার জন্য আমাদের কাছে আত্মসমর্পণ করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏نَحَرْنَا فَرَسًا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَكَلْنَا لَحْمَهُ ‏ ‏أَوْ مِنْ لَحْمِهِ ‏","","",""],[25697,25697,"","আমরা একটি ছেলের কথা বলেছি যে ফাতেমাকে ঈশ্বরের কাছে প্রার্থনা করতে ভয় পেয়েছিল। আমি জেগে আছি, না হলে আমি ক্লান্ত হয়ে পড়েছি, আর তুমি তোমার জন্য ঈশ্বরের কাছে যেতে পারবে না এবং নিজের চোখে আমার নিজের মনে কিছু করবে না।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا ‏ ‏أَنْفِقِي ‏ ‏أَوْ ‏ ‏ارْضَخِي ‏ ‏وَلَا ‏ ‏تُحْصِي ‏ ‏فَيُحْصِيَ ‏ ‏اللَّهُ عَلَيْكِ وَلَا ‏ ‏تُوعِي ‏ ‏فَيُوعِيَ ‏ ‏اللَّهُ عَلَيْكِ ‏","","",""],[25698,25698,"","আমরা একটি কঠিন খারাপ সঙ্গে কথা করেছি যে আমরা এক চোরের নাম দিয়ে যা করেছি... ...সে তার কাছে প্রার্থনা করেছে আর সে কখনো তা করতে পারেনি. অথবা বড় হয়ে তুমি এখানে আটকে থাকবে আর তুমি আমার ব্যাপারে মাথা ঘামাবে না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏وَكَانَتْ ‏ ‏مُحْصِيَةً ‏ ‏وَعَنْ ‏ ‏عَبَّادِ بْنِ حَمْزَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا ‏ ‏أَنْفِقِي أَوْ ‏ ‏انْضَخِي ‏ ‏أَوْ ‏ ‏انْفَحِي ‏ ‏هَكَذَا وَهَكَذَا وَلَا ‏ ‏تُوعِي ‏ ‏فَيُوعَى ‏ ‏عَلَيْكِ وَلَا ‏ ‏تُحْصِي ‏ ‏فَيُحْصِيَ ‏ ‏اللَّهُ عَلَيْكِ ‏","","",""],[25699,25699,"","আমরা এমন এক শিকারীকে চেষ্টা করেছি, যিনি ঈশ্বরের পরে আমাদের সঙ্গে কথা বলেছিলেন । তিনি যে উপত্যকায় মারা গিয়েছিলেন, সেখানে দুটি গৌরবের শহর প্রদান করেছিলেন।","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ نَوْفَلٍ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏كُنَّا ‏ ‏نُؤَدِّي زَكَاةَ الْفِطْرِ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُدَّيْنِ ‏ ‏مِنْ قَمْحٍ ‏ ‏بِالْمُدِّ ‏ ‏الَّذِي تَقْتَاتُونَ بِهِ ‏","","",""],[25700,25700,"","আমরা বাবা বাবাকে তোমার ব্যাপারে খুন করার কথা বলেছিলাম. এটা খেলতে হবে আর আমি পানিকে রক্ষা করবো আর আমি তোমাকে ছেড়ে দেব, আর আমি তোমাকে শিকার করবো, আর আমি সেই ব্যক্তি, যে শিকারে পরিণত হব, আর আমি তাকে স্থানান্তর করছি মাখনের কামড়ের থেকে যে কিনা এটা কেটে ফেলেছে। আমার প্রভু আর আমি তিন বছর ধরে আমার সাথে আছি... আমার কাছে ভাই, তার উত্তরাধিকারী আমাকে যেতে বাধ্য করার জন্য দুঃখিত, সে এটা পরিবর্তন করে দিয়েছে, সে জানতো লর্ড তার বড় মানুষ আর সে আত্মসমর্পণ করবে। আমি জানতাম যে, তোমার ঈর্ষা এবং ঈশ্বর তোমাকে এটা বুঝতে সাহায্য করেছেন যে, তুমি কে । ঘৃণা করতাম।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏تَزَوَّجَنِي ‏ ‏الزُّبَيْرُ ‏ ‏وَمَا لَهُ فِي الْأَرْضِ مِنْ مَالٍ وَلَا مَمْلُوكٍ وَلَا شَيْءٍ غَيْرَ فَرَسِهِ قَالَتْ فَكُنْتُ أَعْلِفُ فَرَسَهُ ‏ ‏وَأَكْفِيهِ ‏ ‏مَئُونَتَهُ ‏ ‏وَأَسُوسُهُ ‏ ‏وَأَدُقُّ النَّوَى ‏ ‏لِنَاضِحِهِ ‏ ‏أَعْلِبُ ‏ ‏وَأَسْتَقِي الْمَاءَ ‏ ‏وَأَخْرُزُ ‏ ‏غَرْبَهُ ‏ ‏وَأَعْجِنُ وَلَمْ أَكُنْ أُحْسِنُ أَخْبِزُ فَكَانَ يَخْبِزُ لِي جَارَاتٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَكُنَّ نِسْوَةَ صِدْقٍ وَكُنْتُ أَنْقُلُ النَّوَى مِنْ أَرْضِ ‏ ‏الزُّبَيْرِ ‏ ‏الَّتِي أَقْطَعَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى رَأْسِي وَهِيَ مِنِّي عَلَى ثُلُثَيْ ‏ ‏فَرْسَخٍ ‏ ‏قَالَتْ فَجِئْتُ يَوْمًا وَالنَّوَى عَلَى رَأْسِي فَلَقِيتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعَهُ نَفَرٌ مِنْ أَصْحَابِهِ ‏ ‏فَدَعَانِي ثُمَّ قَالَ ‏ ‏إِخْ ‏ ‏إِخْ ‏ ‏لِيَحْمِلَنِي خَلْفَهُ قَالَتْ فَاسْتَحَيْتُ أَنْ أَسِيرَ مَعَ الرِّجَالِ وَذَكَرْتُ ‏ ‏الزُّبَيْرَ ‏ ‏وَغَيْرَتَهُ قَالَتْ وَكَانَ أَغْيَرَ النَّاسِ فَعَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنِّي قَدْ اسْتَحَيْتُ فَمَضَى وَجِئْتُ ‏ ‏الزُّبَيْرَ ‏ ‏فَقُلْتُ لَقِيَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَى رَأْسِي النَّوَى وَمَعَهُ نَفَرٌ مِنْ أَصْحَابِهِ ‏ ‏فَأَنَاخَ ‏ ‏لِأَرْكَبَ مَعَهُ فَاسْتَحَيْتُ وَعَرَفْتُ غَيْرَتَكَ فَقَالَ وَاللَّهِ لَحَمْلُكِ ‏ ‏النَّوَى ‏ ‏أَشَدُّ عَلَيَّ مِنْ رُكُوبِكِ مَعَهُ قَالَتْ حَتَّى أَرْسَلَ إِلَيَّ ‏ ‏أَبُو بَكْرٍ ‏ ‏بَعْدَ ذَلِكَ بِخَادِمٍ فَكَفَتْنِي ‏ ‏سِيَاسَةَ ‏ ‏الْفَرَسِ فَكَأَنَّمَا أَعْتَقَنِي ‏","","",""],[25701,25701,"","আমি তাকে তার বাবার কাছে দোষ দেয়ার ব্যাপারে বাবার সাথে কথা বলেছি। আমি বাইরে গিয়ে তাকে নিয়ে যাই। তারপর সে শান্তি পাবে, তারপর সময় পাবে, তারপর তাকে আশীর্বাদ করতে দেবে, আর তার প্রথম সন্তান হবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏أَنَّهَا حَمَلَتْ ‏ ‏بِعَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏بِمَكَّةَ ‏ ‏قَالَتْ فَخَرَجْتُ وَأَنَا مُتِمٌّ فَأَتَيْتُ ‏ ‏الْمَدِينَةَ ‏ ‏فَنَزَلْتُ ‏ ‏بِقُبَاءَ ‏ ‏فَوَلَدْتُهُ ‏ ‏بِقُبَاءَ ‏ ‏ثُمَّ أَتَيْتُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَضَعْتُهُ فِي حِجْرِهِ ثُمَّ ‏ ‏دَعَا بِتَمْرَةٍ فَمَضَغَهَا ثُمَّ تَفَلَ فِي ‏ ‏فِيهِ فَكَانَ أَوَّلَ مَا دَخَلَ فِي جَوْفِهِ رِيقُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ثُمَّ ‏ ‏حَنَّكَهُ ‏ ‏بِتَمْرَةٍ ثُمَّ دَعَا لَهُ وَبَرَّكَ عَلَيْهِ وَكَانَ أَوَّلَ مَوْلُودٍ وُلِدَ فِي الْإِسْلَامِ ‏","","",""],[25702,25702,"","বাবা নিচে গিয়ে কথা বলেছি, কিন্তু আল্লাহ্ জানেন তৃতীয়বারের মতো। তিনি আমার মাকে একটা মেয়ে বলেছেন যে আমার মা আমার কাছে এসেছে। আমি এখন যাচ্ছি। ঈশ্বরের কাছে প্রার্থনা করো, আমি তোমার মায়ের প্রার্থনা করছি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَقِيلٍ يَعْنِي عَبْدَ اللَّهِ بْنَ عَقِيلٍ الثَّقَفِيَّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏قَدِمَتْ عَلَيَّ ‏ ‏أُمِّي ‏ ‏فِي مُدَّةِ ‏ ‏قُرَيْشٍ ‏ ‏مُشْرِكَةً وَهِيَ ‏ ‏رَاغِبَةٌ ‏ ‏يَعْنِي مُحْتَاجَةٌ ‏ ‏فَسَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ ‏ ‏أُمِّي ‏ ‏قَدِمَتْ عَلَيَّ وَهِيَ مُشْرِكَةٌ ‏ ‏رَاغِبَةٌ ‏ ‏أَفَأَصِلُهَا ‏ ‏قَالَ ‏ ‏صِلِي ‏ ‏أُمَّكِ ‏","","",""],[25703,25703,"","আমরা বাবার সাথে কথা বলেছি আমার বাবাকে অনেক বেশি বলতে হবে, আর হাঙ্গরের গুঁজে একজন অংশীদার, যিনি প্রতিজ্ঞা করেছেন লর্ডের জ্ঞান আর আদ্দিত্বের কথা বলেছেন। আমি যাচ্ছি। ওকে ফোন করে, আমরা তোমার মায়ের সাথে যাবো।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏قَدِمَتْ عَلَيَّ ‏ ‏أُمِّي ‏ ‏وَهِيَ مُشْرِكَةٌ فِي عَهْدِ ‏ ‏قُرَيْشٍ ‏ ‏إِذْ عَاهَدُوا فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ ‏ ‏أُمِّي ‏ ‏قَدِمَتْ وَهِيَ ‏ ‏رَاغِبَةٌ ‏ ‏أَفَأَصِلُهَا ‏ ‏قَالَ نَعَمْ ‏ ‏صِلِي ‏ ‏أُمَّكِ ‏","","",""],[25704,25704,"","আমি বলেছিলাম যে, ঈশ্বর তাকে এই ভয়ংকর আংটি দিয়ে ডাকতেন যে কোন ছেলে যে কোন রাতে আমি চাঁদকে বলা হয় তৃতীয় রাত তার বাড়ি বলেছিল যে, আমরা হয়তো তার কাছে শপথ করে বলতে পারি, ছেলে ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ ‏ ‏مَوْلَى ‏ ‏أَسْمَاءَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏أَنَّهَا نَزَلَتْ عِنْدَ دَارِ ‏ ‏الْمُزْدَلِفَةِ ‏ ‏فَقَالَتْ أَيْ بُنَيَّ هَلْ غَابَ الْقَمَرُ لَيْلَةَ ‏ ‏جَمْعٍ ‏ ‏وَهِيَ تُصَلِّي قُلْتُ لَا فَصَلَّتْ سَاعَةً ثُمَّ قَالَتْ أَيْ بُنَيَّ هَلْ غَابَ الْقَمَرُ قَالَ وَقَدْ غَابَ الْقَمَرُ قُلْتُ نَعَمْ قَالَتْ فَارْتَحِلُوا فَارْتَحَلْنَا ثُمَّ مَضَيْنَا بِهَا حَتَّى رَمَيْنَا الْجَمْرَةَ ثُمَّ رَجَعَتْ فَصَلَّتْ الصُّبْحَ فِي مَنْزِلِهَا فَقُلْتُ لَهَا أَيْ ‏ ‏هَنْتَاهُ ‏ ‏لَقَدْ غَلَّسْنَا قَالَتْ كَلَّا يَا بُنَيَّ إِنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَذِنَ ‏ ‏لِلظُّعُنِ ‏","","",""],[25705,25705,"","আমরা তোমার বয়ফ্রেন্ডের সাথে কথা বলেছি যে আমরা ঈশ্বরের নাম নিয়ে কথা বলেছি। লংস্টারের আশীর্বাদ একটি পেইনকে একটি দেওয়াল এবং একটি চেহারাহীন আত্মা হিসেবে তৈরি করেছে। ঈশ্বর তার জন্য প্রার্থনা করেছেন। আর আত্মসমর্পণ করা হয়েছিলো যখন সে বাস করছিল, আমরা অসুস্থ ছিলাম না।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏مَوْلَى ‏ ‏أَسْمَاءَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَ ‏ ‏أَخْرَجَتْ إِلَيَّ ‏ ‏جُبَّةً ‏ ‏طَيَالِسَةً ‏ ‏عَلَيْهَا ‏ ‏لَبِنَةُ ‏ ‏شَبْرٍ ‏ ‏مِنْ ‏ ‏دِيبَاجٍ ‏ ‏كِسْرَوَانِيٍّ ‏ ‏وَفَرْجَاهَا ‏ ‏مَكْفُوفَانِ ‏ ‏بِهِ قَالَتْ هَذِهِ ‏ ‏جُبَّةُ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَلْبَسُهَا كَانَتْ عِنْدَ ‏ ‏عَائِشَةَ ‏ ‏فَلَمَّا قُبِضَتْ ‏ ‏عَائِشَةُ ‏ ‏قَبَضْتُهَا إِلَيَّ فَنَحْنُ نَغْسِلُهَا لِلْمَرِيضِ مِنَّا ‏ ‏يَسْتَشْفِي بِهَا ‏","","",""],[25706,25706,"","আমার বাবার চেয়ে বরং একজন মা, যিনি আমার বাবার চেয়ে বেশি প্রশংসা করতেন, তিনি একটা ছেলের কথা বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبَانُ يَعْنِي ابْنَ يَزِيدَ الْعَطَّارِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏لَا شَيْءَ أَغْيَرُ مِنْ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[25707,25707,"","আমরা মুরগি সম্পর্কে কথা বলেছি আমার বাবার সাথে পাশ দিয়ে যাওয়াটা সম্পর্কে... ...যে আমাকে \"ঈশ্বর\" বলে ডাকতে, এই ক্ষেত্রে, সে ঈশ্বরের কাছে প্রার্থনা করবে ( প্রকা.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏أَبِي عُمَرَ ‏ ‏مَوْلَى ‏ ‏أَسْمَاءَ ‏ ‏قَالَ ‏ ‏أَخْرَجَتْ إِلَيْنَا ‏ ‏أَسْمَاءُ ‏ ‏جُبَّةً ‏ ‏مَزْرُورَةً ‏ ‏بِالدِّيبَاجِ ‏ ‏فَقَالَتْ فِي هَذِهِ كَانَ يَلْقَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَدُوَّ ‏","","",""],[25708,25708,"","আমরা রাজার কথা বলেছি, আমার বাবার বিষ প্রয়োগের জন্য আপনাকে উপহার দিতে... ...তিনি তার জন্য প্রার্থনা করেছিলেন এবং একটি ছোট চঞ্চল থেকে একটি রং দিয়েছেন পেইন্টার।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏مَوْلًى لِأَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏كَانَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جُبَّةٌ مِنْ ‏ ‏طَيَالِسَةٍ ‏ ‏لَبِنَتُهَا ‏ ‏دِيبَاجٌ ‏ ‏كِسْرَوَانِيٌّ ‏","","",""],[25709,25709,"","আমরা জিনিয়াস টিচারের কথা বলেছিলাম যে আমি ভাবছি এটা কিভাবে ব্যবহার করা যায়. তারা চলে গিয়েছিল এবং তাকে যেতে বলেছিল ।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ الْقُرِّيِّ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مُتْعَةِ ‏ ‏الْحَجِّ فَرَخَّصَ فِيهَا وَكَانَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏يَنْهَى عَنْهَا فَقَالَ هَذِهِ ‏ ‏أُمُّ ابْنِ الزُّبَيْرِ ‏ ‏تُحَدِّثُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَخَّصَ فِيهَا فَادْخُلُوا عَلَيْهَا فَاسْأَلُوهَا قَالَ فَدَخَلْنَا عَلَيْهَا فَإِذَا امْرَأَةٌ ضَخْمَةٌ عَمْيَاءُ فَقَالَتْ ‏ ‏قَدْ رَخَّصَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهَا ‏","","",""],[25710,25710,"","আমরা ফুলের সবচেয়ে সেরা দুনিয়া সম্পর্কে কথা বলেছি, আমার বাবার দাঁত ছাড়া তুমি কে? আর একজন তার মাথাও দেখতে পাবে এই গুজবের মাধ্যমে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ مُسْلِمٍ ‏ ‏أَخُو ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مَوْلَى لِأَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ كَانَ مِنْكُنَّ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا تَرْفَعْ رَأْسَهَا حَتَّى نَرْفَعَ رُءُوسَنَا كَرَاهَةَ أَنْ يَرَيْنَ عَوْرَاتِ الرِّجَالِ لِصِغَرِ ‏ ‏أُزُرِهِمْ ‏ ‏وَكَانُوا إِذْ ذَاكَ ‏ ‏يَأْتَزِرُونَ ‏ ‏بِهَذِهِ النَّمِرَةِ ‏","","",""],[25711,25711,"","আমি বলছি যে এটা স্বপ্নের কথা। আমরা ঈশ্বরের কাছে প্রার্থনা করব, তাঁর বিশ্বাস করা উচিত এবং তিনি কার সে কে ছিল তা বিশ্বাস করুন, তুমি তার মাথা উপরে তুলে আনতে চাও এমনকি সে মানুষের অনুভূতি দেখতে চাও, ঈশ্বরের একজন দেবতা ভাই আছে, আমার বাবার জন্য গর্ব করে ঈশ্বর তাকে আদেশ দিয়েছেন আর তাকে আত্মসমর্পণ করতে হবে, যে ঈশ্বর ও অন্য কারো কাছে নিশ্চিত ছিল।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏بَعْضِهِمْ ‏ ‏عَنْ ‏ ‏مَوْلَى لِأَسْمَاءَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ الْمُسْلِمُونَ ‏ ‏ذَوِي ‏ ‏حَاجَةٍ ‏ ‏يَأْتَزِرُونَ ‏ ‏بِهَذِهِ ‏ ‏النَّمِرَةِ ‏ ‏فَكَانَتْ إِنَّمَا تَبْلُغُ أَنْصَافَ سُوقِهِمْ ‏ ‏أَوْ نَحْوَ ذَلِكَ ‏ ‏فَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ‏ ‏يَعْنِي النِّسَاءَ ‏ ‏فَلَا تَرْفَعْ رَأْسَهَا حَتَّى نَرْفَعَ رُءُوسَنَا كَرَاهِيَةَ أَنْ تَنْظُرَ إِلَى عَوْرَاتِ الرِّجَالِ مِنْ صِغَرِ ‏ ‏أُزُرِهِمْ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُسْلِمِ بْنِ شِهَابٍ ‏ ‏أَخِي ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مَوْلًى لِأَسْمَاءَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَنْ كَانَ مِنْكُنَّ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[25712,25712,"","আমাদের আলোচনা সম্পর্কে আমরা কথা বলেছি এবং তিনি আমার ভাই-বোন সম্পর্কে কথা বলতে বলেছেন। আমার বাবা আমাকে বলছেন, \"ঈশ্বরের প্রভু তার সাথে এটা ঘটেছে।\" আর একজন আরেকজন। মানুষ না পড়া পর্যন্ত তার নাম ওঠা উচিত তারা খুঁজে বের করবে","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏النُّعْمَانُ بْنُ رَاشِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَخِي الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مَوْلًى لِأَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا مَعْشَرَ النِّسَاءِ ‏ ‏مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا تَرْفَعْ رَأْسَهَا حَتَّى يَرْفَعَ الرِّجَالُ رُءُوسَهُمْ قَالَتْ وَذَلِكَ أَنَّ ‏ ‏أُزُرَهُمْ ‏ ‏كَانَتْ قَصِيرَةً مَخَافَةَ أَنْ تَنْكَشِفَ عَوْرَاتُهُمْ إِذَا سَجَدُوا ‏","","",""],[25713,25713,"","আমরা বিছানায় শুয়েছিলাম এই বলে যে আমরা একদিন বেঁচে থাকার হাত থেকে বেঁচে আছি। সে বলল, আল্লাহ তার জন্য প্রার্থনা করেছে এবং তার দশ ভাগের দশ ভাগ দেওয়া হবে। যে সমস্ত নারীরা তার উপর বিশ্বাস করত এবং যারা বিশ্বের সেরা হবে, এমনকি সে পুরুষ থেকে সবচেয়ে কম বয়স্কদের মুখস্ত করত।","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا مَعْشَرَ النِّسَاءِ ‏ ‏مَنْ كَانَ مِنْكُنَّ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا تَرْفَعْ رَأْسَهَا حَتَّى يَرْفَعَ الْإِمَامُ رَأْسَهُ مِنْ ضِيقِ ثِيَابِ الرِّجَالِ ‏","","",""],[25714,25714,"","আমরা একজন শিকারীর জন্য একটা দাসের কথা বলেছি যার জন্য আমার বাবার মেয়ে খুব ভাল, ঈশ্বর তাকে আমাদের সব উপায় দিতে বলেছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ بْنُ حُمَيْدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏حَجَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَنَا فَجَعَلْنَاهَا عُمْرَةً فَأَحْلَلْنَا كُلَّ الْإِحْلَالِ حَتَّى سَطَعَتْ ‏ ‏الْمَجَامِرُ ‏ ‏بَيْنَ النِّسَاءِ وَالرِّجَالِ ‏","","",""],[25715,25715,"","আমরা আমার বাবার কথা বলেছিলাম, আর আমরা তার সুন্দর চেহারার কথা বলেছিলাম, আমি আমার বাবাকে বড় মনে করে ডাকি, না হলে আমি খুশি হব যে, ঈশ্বরের মাথায় এটা আছে কিনা। ছাত্র অবশ্যই বলবে, কি তোমাকে বিব্রত করা থেকে বিরত রাখবে, কিন্তু ঈশ্বর সবচেয়ে ভালো মহিলা হবেন, আমি আমার দায়িত্ব অস্বীকার করছি আপনার প্রিয় মেয়ে খুঁজে বের করা।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَدَّتِهِ فَمَا أَدْرِي ‏ ‏أَسْمَاءَ بِنْتَ أَبِي بَكْرٍ ‏ ‏أَوْ ‏ ‏سُعْدَى بِنْتَ عَوْفٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَى ‏ ‏ضُبَاعَةَ بِنْتِ الزُّبَيْرِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏فَقَالَ ‏ ‏مَا يَمْنَعُكَ مِنْ الْحَجِّ يَا عَمَّةُ ‏ ‏قَالَتْ يَا رَسُولَ اللَّهِ ‏ ‏إِنِّي امْرَأَةٌ ‏ ‏سَقِيمَةٌ ‏ ‏وَإِنِّي أَخَافُ ‏ ‏الْحَبْسَ ‏ ‏قَالَ فَأَحْرِمِي وَاشْتَرِطِي أَنَّ مَحِلَّكِ حَيْثُ ‏ ‏حُبِسْتِ ‏","","",""],[25716,25716,"","আমি যখন তাকে জিজ্ঞেস করি যে, আমি কী করতে পারি, তখন তিনি আমাকে সাহায্য করেছিলেন । আমি বলেছি, আমি আপনার সুরক্ষার জন্য ধৈর্য ধরতে চাই এবং বলুন যে একজন অপরাধীর ছেলে এমন একজন যার কাছে আছে, যিনি অধিকার আছে যে অধিকার আছে তাকেই দেওয়া হবে অধিকার দান করার জন ্ য তোমার অধিকার আছে, তুমি আমার বাবার মেয়েকেও ডাকা শুরু করবে... ...যেমন ভাববাদীর কাছে আছে আর তাকে যেতে বলা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ ‏ ‏حُدِّثْتُ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏فَزِعَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ كَسَفَتْ الشَّمْسُ ‏ ‏فَأَخَذَ ‏ ‏دِرْعًا ‏ ‏حَتَّى ‏ ‏أَدْرَكَ ‏ ‏بِرِدَائِهِ فَقَامَ بِالنَّاسِ ‏ ‏قِيَامًا ‏ ‏طَوِيلًا يَقُومُ ثُمَّ يَرْكَعُ قَالَتْ فَجَعَلْتُ أَنْظُرُ إِلَى الْمَرْأَةِ الَّتِي هِيَ أَكْبَرُ مِنِّي قَائِمَةً وَإِلَى الْمَرْأَةِ الَّتِي هِيَ ‏ ‏أَسْقَمُ ‏ ‏مِنِّي قَائِمَةً فَقُلْتُ إِنِّي أَحَقُّ أَنْ أَصْبِرَ عَلَى طُولِ الْقِيَامِ مِنْكِ ‏ ‏و قَالَ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏مَنْصُورُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏صَفِيَّةَ بِنْتِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَزِعَ ‏","","",""],[25717,25717,"","আমি শুনেছি কিভাবে বলতে হবে, ঈশ্বরের কাছে প্রার্থনা করলাম, সে পৌঁছে গেছে, আর সে পড়তে পারে, আর আমরা প্রার্থনা করব তার ভালোর আগে। আর প্রকাশকরা এটা করতে পারে। আর প্রকাশকরা, আর প্রকাশকরা কি ভাবে বলতে পারে? ঈশ্বরের দোহাই লাগে যে ঈশ্বরের কথা মানায়।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يَقْرَأُ وَهُوَ ‏ ‏يُصَلِّي نَحْوَ الرُّكْنِ قَبْلَ أَنْ ‏ ‏يَصْدَعَ ‏ ‏بِمَا يُؤْمَرُ وَالْمُشْرِكُونَ يَسْتَمِعُونَ ‏ { ‏فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ ‏}","","",""],[25718,25718,"","আমার সময় নিয়ে কথা বলতে গিয়ে বাবা বাবার সাথে কথা বলেছি। আমার বাবা আমার বাবার মেয়েকে ফোন করে এতো কথা বলেছেন কেন তিনি ঈশ্বরের কাছে তার শান্তি ও শান্তির জন্য প্রার্থনা করা বন্ধ করেছেন। একজন যাজকের একটা ছেলে আছে যার ইচ্ছা ছিল আমার বাবাকে তার ভাগ্যের ক্ষতি করতে। বলা হয় যে এই কৌশল একজন মানুষ। আর তারপর তিনি বলেন, \"অট্ট কৌশলের উদ্দেশ্যতেই,\" তিনি ভাইকে আদেশ করেন আর পরবর্তী ভাইকে হত্যা করা হবে।\" তিনি বলেন, \"সে একজন মানুষ।\" আমার ভাইয়ের সাথে আমার ভাইকে বিরক্ত করার কল্পনায় সে আমার কল্পনায় পড়ে গেছে। প্রতিবেশীটি তাকে আগুনের মধ্যে দিয়ে উড়ে যাচ্ছে। বাবা তাকে দেখে একটা খারাপ ছেলে, যে তার বাবার সাথে দেখা করেছে। সে তাকে কয়েক বছর আগে ছেড়ে দিয়েছে, সে ঈশ্বরকে বলে দিয়েছে, সে তাকে তার দুনিয়া সম্পর্কে শিক্ষা দিয়েছে এবং সে তা করেছে, আমি গর্বিত। তার ভাইয়ের হাত নিয়ে তাকে মেরে আমার ভাইকে কসম খাওয়ার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى بْنُ عَبَّادِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدَّتِهِ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏لَمَّا وَقَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِذِي طُوًى ‏ ‏قَالَ ‏ ‏أَبُو قُحَافَةَ ‏ ‏لِابْنَةٍ لَهُ مِنْ أَصْغَرِ وَلَدِهِ أَيْ بُنَيَّةُ اظْهَرِي بِي عَلَى ‏ ‏أَبِي قَبِيسٍ ‏ ‏قَالَتْ وَقَدْ كُفَّ بَصَرُهُ قَالَتْ ‏ ‏فَأَشْرَفْتُ ‏ ‏بِهِ عَلَيْهِ فَقَالَ يَا بُنَيَّةُ مَاذَا تَرَيْنَ قَالَتْ أَرَى سَوَادًا مُجْتَمِعًا قَالَ تِلْكَ الْخَيْلُ قَالَتْ وَأَرَى رَجُلًا ‏ ‏يَسْعَى ‏ ‏بَيْنَ ذَلِكَ ‏ ‏السَّوَادِ ‏ ‏مُقْبِلًا ‏ ‏وَمُدْبِرًا ‏ ‏قَالَ يَا بُنَيَّةُ ذَلِكَ الْوَازِعُ ‏ ‏يَعْنِي الَّذِي يَأْمُرُ الْخَيْلَ وَيَتَقَدَّمُ إِلَيْهَا ‏ ‏ثُمَّ قَالَتْ قَدْ وَاللَّهِ انْتَشَرَ ‏ ‏السَّوَادُ ‏ ‏فَقَالَ قَدْ وَاللَّهِ إِذَا دَفَعَتْ الْخَيْلُ فَأَسْرِعِي بِي إِلَى بَيْتِي ‏ ‏فَانْحَطَّتْ ‏ ‏بِهِ وَتَلَقَّاهُ الْخَيْلُ قَبْلَ أَنْ يَصِلَ إِلَى بَيْتِهِ وَفِي عُنُقِ ‏ ‏الْجَارِيَةِ ‏ ‏طَوْقٌ لَهَا مِنْ وَرِقٍ فَتَلَقَّاهُ الرَّجُلُ فَاقْتَلَعَهُ مِنْ عُنُقِهَا قَالَتْ فَلَمَّا دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَكَّةَ ‏ ‏وَدَخَلَ الْمَسْجِدَ أَتَاهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏بِأَبِيهِ يَعُودُهُ فَلَمَّا رَآهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ هَلَّا تَرَكْتَ الشَّيْخَ فِي بَيْتِهِ حَتَّى أَكُونَ أَنَا آتِيهِ فِيهِ قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَا رَسُولَ اللَّهِ هُوَ أَحَقُّ أَنْ يَمْشِيَ إِلَيْكَ مِنْ أَنْ تَمْشِيَ أَنْتَ إِلَيْهِ قَالَ فَأَجْلَسَهُ بَيْنَ يَدَيْهِ ثُمَّ مَسَحَ صَدْرَهُ ثُمَّ قَالَ لَهُ ‏ ‏أَسْلِمْ فَأَسْلَمَ وَدَخَلَ بِهِ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَأْسُهُ كَأَنَّهُ ‏ ‏ثَغَامَةٌ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَيِّرُوا هَذَا مِنْ شَعْرِهِ ثُمَّ قَامَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَأَخَذَ بِيَدِ أُخْتِهِ فَقَالَ أَنْشُدُ ‏ ‏بِاللَّهِ وَبِالْإِسْلَامِ طَوْقَ أُخْتِي فَلَمْ يُجِبْهُ أَحَدٌ فَقَالَ يَا ‏ ‏أُخَيَّةُ احْتَسِبِي طَوْقَكِ ‏","","",""],[25719,25719,"","আমরা আমার বাবার সাথে কথা বলেছিলাম, সে আমার সাথে এমন ভাবে কথা বলতে চেয়েছিল যেন সে মাখন পরতে চেয়েছিল। সে তার দাদীকে আমার বাবার মেয়েকে ফোন করে বলে। বাবা কখনো ঈশ্বরের কাছে প্রার্থনা করেনি, বাবা আশা করেছিল সে তার নিজের রক্ত স্পর্শ করতে পারবে না অথবা ছয় হাজার ডলার বলেছে সে ভুল। আমার দাদা একজন প্রভিবাসী যে তাকে হত্যা করতে গিয়েছে। আর দেখ, সে আমার প্রাণ দ্বারা তাঁহাকে সমর্পণ করিল; সে আমাদের অনেক উত্তম কিছু করিতে দিল; সে বলে যেন আমরা পিতার পরাক্রমে কিছু পাথর লইয়া যাই । তার হাত আর হাত, বাবা, তুমি হয়তো এটা করেছ, আমি এর চেয়ে ভালো হতে পারি, কিন্তু আমার হয়তো কিছু বাকি আছে।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏جَدَّتِهِ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏لَمَّا ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَخَرَجَ مَعَهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏احْتَمَلَ ‏ ‏أَبُو بَكْرٍ ‏ ‏مَالَهُ كُلَّهُ مَعَهُ خَمْسَةَ آلَافِ دِرْهَمٍ ‏ ‏أَوْ سِتَّةَ آلَافِ دِرْهَمٍ ‏ ‏قَالَتْ وَانْطَلَقَ بِهَا مَعَهُ قَالَتْ فَدَخَلَ عَلَيْنَا جَدِّي ‏ ‏أَبُو قُحَافَةَ ‏ ‏وَقَدْ ذَهَبَ بَصَرُهُ فَقَالَ وَاللَّهِ إِنِّي لَأَرَاهُ قَدْ ‏ ‏فَجَعَكُمْ ‏ ‏بِمَالِهِ مَعَ نَفْسِهِ قَالَتْ قُلْتُ كَلَّا يَا ‏ ‏أَبَتِ إِنَّهُ قَدْ تَرَكَ لَنَا خَيْرًا كَثِيرًا قَالَتْ فَأَخَذْتُ أَحْجَارًا فَتَرَكْتُهَا فَوَضَعْتُهَا فِي ‏ ‏كُوَّةِ ‏ ‏الْبَيْتِ كَانَ أَبِي يَضَعُ فِيهَا مَالَهُ ثُمَّ وَضَعْتُ عَلَيْهَا ثَوْبًا ثُمَّ أَخَذْتُ بِيَدِهِ فَقُلْتُ يَا ‏ ‏أَبَتِ ضَعْ يَدَكَ عَلَى هَذَا الْمَالِ قَالَتْ فَوَضَعَ يَدَهُ عَلَيْهِ فَقَالَ لَا بَأْسَ إِنْ كَانَ قَدْ تَرَكَ لَكُمْ هَذَا فَقَدْ أَحْسَنَ وَفِي هَذَا لَكُمْ ‏ ‏بَلَاغٌ ‏ ‏قَالَتْ لَا وَاللَّهِ مَا تَرَكَ لَنَا شَيْئًا وَلَكِنِّي قَدْ ‏ ‏أَرَدْتُ ‏ ‏أَنْ أُسْكِنَ الشَّيْخَ بِذَلِكَ ‏","","",""],[25720,25720,"","আমরা কথা বলেছিলাম, একটি ছেলে কথা বলেছিলাম, যে তোমাকে ফোন করার চেষ্টা করেছিল। আমি সেটা ফেলে দিচ্ছি আর আমি সেটা শুনেছি, দুঃখিত, আমি চেষ্টা করেছি। ভুল করে বল, ঈশ্বর বলে যে আমরা একটা ছেলে যে আমার সাথে এমন একটা ছেলে আছে যে ছেলে ছেলে হয়ে আছে, যে ছেলে হয়েছে। একটি ছেলে ছেলে ছেলে ছেলে হয়েছে যে সন ্ তান গ ্ রহণ করেছে , তিনি খুবই ঠাণ্ডা ছিলেন আর তার মতো কথা বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُقَيْلُ بْنُ خَالِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّهَا كَانَتْ ‏ ‏إِذَا ‏ ‏ثَرَدَتْ ‏ ‏غَطَّتْهُ شَيْئًا حَتَّى يَذْهَبَ فَوْرُهُ ثُمَّ تَقُولُ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّهُ أَعْظَمُ لِلْبَرَكَةِ ‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عُقَيْلٍ ‏ ‏و حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلُ بْنُ خَالِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّهَا كَانَتْ إِذَا ثَرَدَتْ غَطَّتْهُ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[25721,25721,"","আমরা ফাঁদে আটকা পড়া থেকে বেশি মজা করার কথা বলেছিলাম। আমি একজন নবী যে তার কাছে প্রার্থনা করেছিল এবং বলতে চাই যে আমি আমার মেয়েকে বিয়ে করেছি এবং আমি অনেক ক্লান্ত ছিলাম। তার রাষ্ট্রপতিকে প্রার্থনা করতে হত্যা করা হয়, কারণ তার সাথে সংযোগ ছিল।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِمْرَانُ بْنُ يَزِيدَ الْقَطَّانُ بَصْرِيٌّ ‏ ‏عَنْ ‏ ‏مَنْصُورِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏أَنَّ امْرَأَةً جَاءَتْ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ ‏ ‏إِنِّي زَوَّجْتُ ابْنَتِي فَمَرِضَتْ ‏ ‏فَتَمَرَّطَ ‏ ‏رَأْسُهَا وَإِنَّ زَوْجَهَا قَدْ اخْتَلَفَ إِلَيَّ ‏ ‏أَفَأَصِلُ ‏ ‏رَأْسَهَا قَالَتْ فَسَبَّ ‏ ‏الْوَاصِلَةَ ‏ ‏وَالْمُسْتَوْصِلَةَ ‏","","",""],[25722,25722,"","আমরা তার মায়ের সঙ্গে দূরে যাওয়ার বিষয়ে কথা বলেছিলাম । সমাধান করার জন্য একটি উপহার","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِمْرَانُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنِ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُهِلِّينَ ‏ ‏بِالْحَجِّ فَقَالَتْ فَقَالَ لَنَا ‏ ‏مَنْ كَانَ مَعَهُ ‏ ‏هَدْيٌ ‏ ‏فَلْيَقُمْ عَلَى إِحْرَامِهِ وَمَنْ لَمْ يَكُنْ مَعَهُ ‏ ‏هَدْيٌ ‏ ‏فَلْيَحْلِلْ ‏","","",""],[25723,25723,"","আমরা এই শব্দগুলো ব্যবহার করেছি আমাদের বলতে যে আমার বাবা তার বাবার কথা শুনতে হবে, গেমের ছেলে পাইলটদের বলছে যেন না আপনার মায়ের কাছে অনুরোধ না করে। তার মায়ের সাথে কথা বলেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং যদি আমরা আমাদের থেকে মরে যেতে চাই, তাহলে আমি কে হতে চাই। আমি কি শপথী নেতা হতে চাই?","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَسْوَدِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُبَادَةَ بْنَ الْمُهَاجِرِ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ الْعَبَّاسِ ‏ ‏يَقُولُ ‏ ‏لِابْنِ الزُّبَيْرِ ‏ ‏أَلَا تَسْأَلُ أُمَّكَ قَالَ فَدَخَلْنَا عَلَى أُمِّهِ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏فَقَالَتْ خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى إِذَا كُنَّا ‏ ‏بِذِي الْحُلَيْفَةِ ‏ ‏قَالَ ‏ ‏مَنْ أَرَادَ مِنْكُمْ أَنْ ‏ ‏يُهِلَّ ‏ ‏بِالْحَجِّ ‏ ‏فَلْيُهِلَّ ‏ ‏وَمَنْ أَرَادَ مِنْكُمْ أَنْ ‏ ‏يُهِلَّ ‏ ‏بِعُمْرَةٍ ‏ ‏فَلْيُهِلَّ ‏ ‏قَالَتْ ‏ ‏أَسْمَاءُ ‏ ‏وَكُنْتُ أَنَا ‏ ‏وَعَائِشَةُ ‏ ‏وَالْمِقْدَادُ ‏ ‏وَالزُّبَيْرُ ‏ ‏مِمَّنْ أَهَلَّ بِعُمْرَةٍ ‏","","",""],[25724,25724,"","আমরা আমার বাবার মেয়ের কথা বলেছিলাম আমার ছেলে হওয়ার কথা। ঈশ্বর প্রার্থনা করেছেন এটা করেছেন আর তার পরে শপথটি করেছেন আর প্রভুকে হত্যা করেছেন। তিনি ফিরে গিয়ে উঠে গিয়ে পড়ে পরে আবার ফিরে যান । এরপর ফিরে গিয়ে ফিরে গিয়ে তিনি ফিরে যান এবং ফিরে যান এবং ফিরে যান এবং ফিরে যান এবং ফিরে যান এবং ফিরে যান এবং ফিরে যান এবং তিনি ফিরে যান এবং বলেন যে তিনি তাকে হত্যা করবেন । আমার ঋণের কারণে, যারা তোমাকে ছোট ছোট একটা বর্বরের সাথে নিতে বাধ্য হতো, আগুন না আসা পর্যন্ত আমি বললাম, \"আমি যদি এটা মিস করি, তাহলে আমরা তাদের সাথে থাকব,\" তিনি আমাকে ছেড়ে দেবেন। তার মৃত্যুর আগ পর্যন্ত সে বেঁচে ছিল আর সে কখনোই তাকে ছেড়ে যায়নি।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏نَافِعٌ يَعْنِي ابْنَ عُمَرَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْكُسُوفِ قَالَتْ فَأَطَالَ الْقِيَامَ ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ ثُمَّ قَامَ فَأَطَالَ الْقِيَامَ ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ ثُمَّ رَفَعَ فَأَطَالَ الْقِيَامَ ثُمَّ سَجَدَ ‏ ‏فَأَطَالَ السُّجُودَ ثُمَّ رَفَعَ ثُمَّ سَجَدَ فَأَطَالَ السُّجُودَ ثُمَّ قَامَ فَأَطَالَ الْقِيَامَ ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ ثُمَّ رَفَعَ فَأَطَالَ الْقَيَّامَ ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ ثُمَّ رَفَعَ ثُمَّ سَجَدَ فَأَطَالَ السُّجُودَ ثُمَّ رَفَعَ ثُمَّ سَجَدَ فَأَطَالَ السُّجُودَ ثُمَّ انْصَرَفَ فَقَالَ ‏ ‏دَنَتْ ‏ ‏مِنِّي الْجَنَّةُ حَتَّى لَوْ ‏ ‏اجْتَرَأْتُ ‏ ‏لَجِئْتُكُمْ ‏ ‏بِقِطَافٍ ‏ ‏مِنْ قِطَافِهَا ‏ ‏وَدَنَتْ ‏ ‏مِنِّي النَّارُ حَتَّى قُلْتُ يَا رَبُّ وَأَنَا مَعَهُمْ وَإِذَا امْرَأَةٌ ‏ ‏قَالَ ‏ ‏نَافِعٌ ‏ ‏حَسِبْتُ أَنَّهُ قَالَ تَخْدِشُهَا هِرَّةٌ ‏ ‏قُلْتُ مَا شَأْنُ هَذِهِ قِيلَ لِي حَبَسَتْهَا حَتَّى مَاتَتْ لَا هِيَ أَطْعَمَتْهَا وَلَا هِيَ أَرْسَلَتْهَا تَأْكُلُ مِنْ ‏ ‏خِشَاشِ ‏ ‏الْأَرْضِ ‏","","",""],[25725,25725,"","আমি আমার বাবার জন্য কথা বলেছি, যাকে আমি তোমার কাছে ক্ষমা প্রার্থনা করেছি, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং আত্মসমর্পণ করেছেন, তিনি চলে যাওয়ার পর সে নিজে নিজে থেকে করতে ব্যর্থ হয়েছেন। তারপর তিনি উঠে দাঁড়ান। সে দুটো লাশ পেয়েছে আর তোমার মত দ্বিতীয়টা কাজ করেছে, আমাকে বলা হয়েছে তাকে অপহরণ করা থেকে বিরত রাখতে। সে একজন পরাজিত। চড়া, আর সে তাকে যেতে দিবে না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ عُمَرَ الْجُمَحِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏انْكَسَفَتْ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ فَصَلَّى فَأَطَالَ الْقِيَامَ ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ ثُمَّ رَفَعَ فَأَطَالَ الْقِيَامَ ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ ثُمَّ رَفَعَ فَأَطَالَ الْقِيَامَ ثُمَّ سَجَدَ سَجْدَتَيْنِ ثُمَّ فَعَلَ فِي الثَّانِيَةِ مِثْلَ ذَلِكَ ثُمَّ قَالَ لَقَدْ ‏ ‏أُدْنِيَتْ ‏ ‏مِنِّي الْجَنَّةُ حَتَّى لَوْ ‏ ‏اجْتَرَأْتُ ‏ ‏عَلَيْهَا لَأَتَيْتُكُمْ ‏ ‏بِقِطْفٍ ‏ ‏مِنْ ‏ ‏أَقْطَافِهَا ‏ ‏وَلَقَدْ ‏ ‏أُدْنِيَتْ ‏ ‏مِنِّي النَّارُ حَتَّى قُلْتُ يَا رَبُّ وَأَنَا مَعَهُمْ فَرَأَيْتُ فِيهَا هِرَّةً ‏ ‏قَالَ حَسِبْتُ أَنَّهَا تَخْدِشُ امْرَأَةً ‏ ‏حَبَسَتْهَا فَلَمْ تُطْعِمْهَا وَلَمْ تَدَعْهَا تَأْكُلُ مِنْ ‏ ‏خِشَاشِ ‏ ‏الْأَرْضِ حَتَّى مَاتَتْ ‏","","",""],[25726,25726,"","আমরা আমাদের মহানাত্বের দ্বারা বাপ্তাইজিত হয়েছি এই কথা বলার জন্য যে আমরা একটা পিপপি তৈরি করেছি এবং একটি ছেলেকে বলেছিলাম আমরা কথা বলেছি। আমার গ্রীষ্মের সবচেয়ে ভাল যে কোন কিছু আমার মা আমার ফোন করতে যাচ্ছে। বাবা তার বাবার সাথে আছেন, তাকে হুমকি দেয়া হয়েছে যে তিনি তার জীবন রক্ষা করতে পারবেন না। পাইলট বলেছিল যে, আমি তোমাকে প্রমাণ করতে ভয় পাচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَرَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَنْصُورُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ شَيْبَةَ ‏ ‏وَهِيَ أُمُّهُ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏خَرَجْنَا مُحْرِمِينَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَ مَعَهُ ‏ ‏هَدْيٌ ‏ ‏فَلْيُتِمَّ ‏ ‏وَقَالَ ‏ ‏رَوْحٌ ‏ ‏فَلْيَقُمْ ‏ ‏عَلَى إِحْرَامِهِ وَمَنْ لَمْ يَكُنْ مَعَهُ ‏ ‏هَدْيٌ ‏ ‏فَلْيَحْلِلْ ‏ ‏قَالَتْ ‏ ‏فَلَمْ يَكُنْ مَعِي ‏ ‏هَدْيٌ ‏ ‏فَحَلَلْتُ وَكَانَ مَعَ ‏ ‏الزُّبَيْرِ ‏ ‏زَوْجِهَا ‏ ‏هَدْيٌ ‏ ‏فَلَمْ ‏ ‏يَحِلَّ ‏ ‏قَالَتْ فَلَبِسْتُ ثِيَابِي وَحَلَلْتُ فَجِئْتُ إِلَى ‏ ‏الزُّبَيْرِ ‏ ‏فَقَالَ قُومِي عَنِّي قَالَتْ فَقُلْتُ ‏ ‏أَتَخْشَى أَنْ ‏ ‏أَثِبَ ‏ ‏عَلَيْكَ ‏","","",""],[25727,25727,"","আমরা এত গর্বিত যে আমরা একটা বাচ্চাকে বলেছিলাম আমার বাবার সাথে কুমারী বলে আমি আমার বাবাকে ডাকি। আমার ছেলে বলেছিল, আমরা একটা অদ্ভুত ঘটনা করেছি। আমি বললাম, সে বসে ছিল এবং সে যা বলেছে, তা আমাকে বলে, \"হে ঈশ্বর, ঈশ্বর, ঈশ্বর, সে বলল, এটাই ছিল উজ্জ্বল।\"","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَرَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ مَوْلَى أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏أَيْ بُنَيَّ هَلْ غَابَ الْقَمَرُ لَيْلَةَ ‏ ‏جَمْعٍ ‏ ‏قُلْتُ لَا ثُمَّ قَالَتْ أَيْ بُنَيَّ هَلْ غَابَ الْقَمَرُ قُلْتُ نَعَمْ قَالَتْ فَارْتَحِلُوا فَارْتَحَلْنَا ثُمَّ مَضَيْنَا حَتَّى رَمَتْ الْجَمْرَةَ ثُمَّ رَجَعَتْ فَصَلَّتْ الصُّبْحَ فِي مَنْزِلِهَا فَقُلْتُ لَهَا لَقَدْ غَلَّسْنَا ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏أَيْ ‏ ‏هَنْتَاهُ ‏ ‏قَالَتْ كَلَّا يَا بُنَيَّ ‏ ‏إِنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَذِنَ ‏ ‏لِلظُّعُنِ ‏","","",""],[25728,25728,"","আমার বাবার বেঁচে থাকা নিয়ে কথা বললাম, তার ছেলের মৃত্যুর পর আমার বাবা বড় হয়েছেন। ঈশ্বর তাকে আদেশ দিয়েছেন আর তাদের মধ্যে থেকে তিনি শেষ দু - তৃতীয়াংশের মধ্যে থেকে আসবেন, নেকড়েদের ব্যাজ ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ النَّاجِيِّ ‏ ‏أَنَّ ‏ ‏الْحَجَّاجَ بْنَ يُوسُفَ ‏ ‏دَخَلَ عَلَى ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏بَعْدَمَا قُتِلَ ابْنُهَا ‏ ‏عَبْدُ اللَّهِ بْنُ الزُّبَيْرِ ‏ ‏فَقَالَ إِنَّ ابْنَكِ ‏ ‏أَلْحَدَ ‏ ‏فِي هَذَا الْبَيْتِ وَإِنَّ اللَّهَ عَزَّ وَجَلَّ أَذَاقَهُ مِنْ عَذَابٍ أَلِيمٍ وَفَعَلَ بِهِ مَا فَعَلَ فَقَالَتْ كَذَبْتَ كَانَ بَرًّا بِالْوَالِدَيْنِ ‏ ‏صَوَّامًا ‏ ‏قَوَّامًا ‏ ‏وَاللَّهِ لَقَدْ أَخْبَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏سَيَخْرُجُ مِنْ ‏ ‏ثَقِيفٍ ‏ ‏كَذَّابَانِ الْآخِرُ مِنْهُمَا شَرٌّ مِنْ الْأَوَّلِ وَهُوَ ‏ ‏مُبِيرٌ ‏","","",""],[25729,25729,"","আমি আমার বাবাকে একটা বিরাট কান্নার আওয়াজ বলি, ঈশ্বরের নামে শপথ করে বলছি, তিনি অনেক দিন ধরে লোকেদের বলেছিলেন । আগে সে স্বর্গে হাঁটু গেড়ে বসত, আমি সেই মহিলা হতে যাচ্ছি, আমি আমার কাছ থেকে আসছি, আর আমি এর গুনতে পারবো।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏صَفِيَّةَ بِنْتِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏فَزِعَ ‏ ‏يَوْمَ كَسَفَتْ الشَّمْسُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخَذَ ‏ ‏دِرْعًا ‏ ‏حَتَّى أَدْرَكَ بِرِدَائِهِ فَقَامَ بِالنَّاسِ قِيَامًا طَوِيلًا يَقُومُ ثُمَّ يَرْكَعُ فَلَوْ جَاءَ إِنْسَانٌ بَعْدَمَا رَكَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَعْلَمْ أَنَّهُ رَكَعَ مَا حَدَّثَ نَفْسَهُ أَنَّهُ رَكَعَ مِنْ طُولِ الْقِيَامِ قَالَتْ فَجَعَلْتُ أَنْظُرُ إِلَى الْمَرْأَةِ الَّتِي هِيَ أَكْبَرُ مِنِّي وَإِلَى الْمَرْأَةِ الَّتِي هِيَ ‏ ‏أَسْقَمُ ‏ ‏مِنِّي قَائِمَةً وَأَنَا أَحَقُّ أَنْ أَصْبِرَ عَلَى طُولِ الْقِيَامِ مِنْهَا ‏","","",""],[25730,25730,"","আমার বাবা বলেছিলেন যে আমার বাবা একটা ছেলের সাথে লড়াই করতে চেষ্টা করেছেন। হালকা ভাবে বলছে যে সে ঈশ্বরের কাছ থেকে আমি কিছু পরিবর্তন করতে পারি না, আমি পরিবর্তন করেছি এবং বাতিল করেছি।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ أَبُو دَاوُدَ الطَّيَالِسِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَرْبُ بْنُ شَدَّادٍ ‏ ‏وَأَبَانُ بْنُ يَزِيدَ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَنَّ ‏ ‏عُرْوَةَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَسْمَاءَ ‏ ‏أَخْبَرَتْهُ أَنَّهَا ‏ ‏سَمِعَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ يَقُولُ إِنَّهُ ‏ ‏لَيْسَ شَيْءٌ أَغْيَرَ مِنْ اللَّهِ عَزَّ وَجَلَّ ‏ ‏وَقَالَ ‏ ‏يُونُسُ ‏ ‏فِي حَدِيثِهِ ‏ ‏عَنْ ‏ ‏أَبَانَ ‏ ‏لَا شَيْءَ أَغْيَرَ مِنْ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[25731,25731,"","বাবা আমাকে বলেছেন, আমরা তোমাকে খুন করবো। সে যখন আমার সাথে কথা বলেছিল, তখন সে তোমাকে খুন করে। আর পরের বার যখন বললো, আমার বাবা আমাকে বলেছে যে, ঈশ্বর তাকে সাহায্য করতে হবে। ঈশ্বর তাকে কিছু দিতে বলেছেন, যখন আমি অন্য কিছু পাব, ঈশ্বর বলে দিয়েছেন, ঈশ্বর তাঁর অনুগ্রহ থেকে আমাকে রক্ষা করেছেন। এটা.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ الْحَنَفِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ عُثْمَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏وَهْبُ بْنُ كَيْسَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَسْمَاءَ بِنْتَ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏مَرَّ بِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا أُحْصِي شَيْئًا وَأَكِيلُهُ قَالَ يَا ‏ ‏أَسْمَاءُ ‏ ‏لَا ‏ ‏تُحْصِي ‏ ‏فَيُحْصِيَ ‏ ‏اللَّهُ عَلَيْكِ قَالَتْ فَمَا ‏ ‏أَحْصَيْتُ ‏ ‏شَيْئًا بَعْدَ قَوْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ مِنْ عِنْدِي وَلَا دَخَلَ عَلَيَّ وَمَا نَفِدَ عِنْدِي مِنْ رِزْقِ اللَّهِ إِلَّا أَخْلَفَهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[25732,25732,"","আমার বাবা আমার ছেলের সম্বন্ধে কী বলেছিলেন, সেই বিষয়ে আমরা কথা বলেছিলাম । ঈশ্বরের প্রতি ঈর্ষা এক বিলাসী বিষয় ।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي مُعَاوِيَةُ يَعْنِي شَيْبَانَ ‏ ‏عَنْ ‏ ‏يَحْيَى يَعْنِي ابْنَ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّهَا ‏ ‏سَمِعَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ وَهُوَ عَلَى الْمِنْبَرِ ‏ ‏مَا مِنْ شَيْءٍ أَغْيَرُ مِنْ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[25733,25733,"","কাঠবিড়ালী আমার জন্য একটা আশীর্বাদ ছিল আর কিছুই করার ছিল না। আমাকে বলতেই হবে যে সে আমার দাস হয়ে গেছে, প্রফেসরের নীতি আমাকে থামিয়ে দিয়েছে","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏أَنَّ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَخْدُمُ ‏ ‏الزُّبَيْرَ ‏ ‏زَوْجَهَا وَكَانَ لَهُ فَرَسٌ كُنْتُ ‏ ‏أَسُوسُهُ ‏ ‏وَلَمْ يَكُنْ شَيْءٌ مِنْ الْخِدْمَةِ أَشَدَّ عَلَيَّ مِنْ ‏ ‏سِيَاسَةِ ‏ ‏الْفَرَسِ فَكُنْتُ ‏ ‏أَحْتَشُّ ‏ ‏لَهُ وَأَقُومُ عَلَيْهِ ‏ ‏وَأَسُوسُهُ ‏ ‏وَأَرْضَخُ ‏ ‏لَهُ ‏ ‏النَّوَى ‏ ‏قَالَ ثُمَّ ‏ ‏إِنَّهَا أَصَابَتْ خَادِمًا أَعْطَاهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ فَكَفَتْنِي ‏ ‏سِيَاسَةَ ‏ ‏الْفَرَسِ فَأَلْقَتْ عَنِّي ‏ ‏مَئُونَتَهُ ‏","","",""],[25734,25734,"","বাবা আমার বাবার সাথে কথা বলেছি, আমি আমার বাবাকে নগ্ন হওয়ার চেষ্টা করতে বলছি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ وَهُوَ عَلَى الْمِنْبَرِ ‏ ‏لَا شَيْءَ أَغْيَرُ مِنْ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[25735,25735,"","আমরা আমার বাবাকে লেখার সময় ঈশ্বর বলেছিলেন, আমরা মাখনের বাচ্চাটিকে নিয়ে কথা বলেছি। ঈশ্বরের অনুগ্রহ থেকে তার কাছ থেকে শুনে ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং বলেন, তিনি চলে গেছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي هَذَا الْحَدِيثَ بِخَطِّ يَدِهِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ سُلَيْمَانَ سَعْدَوَيْهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبَّادٌ يَعْنِي ابْنَ الْعَوَّامِ ‏ ‏عَنْ ‏ ‏هَارُونَ بْنِ عَنْتَرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏لَمَّا قَتَلَ ‏ ‏الْحَجَّاجُ بْنَ الزُّبَيْرِ ‏ ‏وَصَلَبَهُ مَنْكُوسًا فَبَيْنَا هُوَ عَلَى الْمِنْبَرِ إِذْ جَاءَتْ ‏ ‏أَسْمَاءُ ‏ ‏وَمَعَهَا أَمَةٌ تَقُودُهَا وَقَدْ ذَهَبَ بَصَرُهَا فَقَالَتْ أَيْنَ أَمِيرُكُمْ فَذَكَرَ قِصَّةً فَقَالَتْ كَذَبْتَ وَلَكِنِّي أُحَدِّثُكَ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَخْرُجُ مِنْ ‏ ‏ثَقِيفٍ ‏ ‏كَذَّابَانِ الْآخِرُ مِنْهُمَا أَشَرُّ مِنْ الْأَوَّلِ وَهُوَ ‏ ‏مُبِيرٌ ‏","","",""],[25736,25736,"","আমরা একটা ছেলে কে জিতলে তার নাম আমার বাবার বলা কথা শুনেছি... ...সে আমাকে ঋণ নিতে বলেছে, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আমি তাদের কি দিতে পারি তা দিয়ে দেব। - না.","‏ ‏حَدَّثَنَا ‏ ‏يَعْمَرُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ مُبَارَكٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنِ ‏ ‏ابْنِ يَزِيدَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ ‏ ‏مَوْلَى ‏ ‏أَسْمَاءَ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏أَسْمَاءَ بِنْتَ أَبِي بَكْرٍ ‏ ‏تَقُولُ ‏ ‏عِنْدِي ‏ ‏لِلزُّبَيْرِ ‏ ‏سَاعِدَانِ ‏ ‏مِنْ ‏ ‏دِيبَاجٍ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْطَاهُمَا إِيَّاهُ يُقَاتِلُ فِيهِمَا ‏","","",""],[25737,25737,"","আমরা দুটো প্রশংসার জন্য চেষ্টা করেছি, সে বলেছে আমরা শেষকৃত্য অনুষ্ঠানের আগে কথা বলেছি, আমার বাবার ছেলে কি সে এটা জানার চেষ্টা করছে। সে বলল যে, সে তার মাথায় ছিল। সে প্রার্থনা করেছিল আর বলেছে শিকারীকে খুঁজে বের করতে। সে বলেছে, তুমি কি বলবে, ঈশ্বর তাকে বলতে চাচ্ছে। আমি বলতে চাই, ঈশ্বর তার জন্য প্রার্থনা করুক এবং তিনি বললেন। সে বলল, \"আমি জানি না। তুমি এটা করতে পারবে। তুমি বলেছিলে, এটা সফল হবে।\" সে বলল, \"আমি জানি না।\" সে বলল, \"আমি জানি না।\" সে বলেছে, \"সে তার কল্পনার অনুসন্ধানের মাধ্যমে আপনার রাজা তার জীবন করেছেন। আলো তাকে এমন কিছু করেছে যা সে শুনতে পায় না, তার নীরবতার কথা শোনে না।\"","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنُ بْنُ الْمُثَنَّى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ أَبِي سَلَمَةَ الْمَاجِشُونَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ يَعْنِي ابْنَ الْمُنْكَدِرِ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏أَسْمَاءُ ‏ ‏تُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ قَالَ ‏ ‏إِذَا دَخَلَ الْإِنْسَانُ قَبْرَهُ فَإِنْ كَانَ مُؤْمِنًا ‏ ‏أَحَفَّ ‏ ‏بِهِ عَمَلُهُ الصَّلَاةُ وَالصِّيَامُ قَالَ فَيَأْتِيهِ الْمَلَكُ مِنْ نَحْوِ الصَّلَاةِ فَتَرُدُّهُ وَمِنْ نَحْوِ الصِّيَامِ فَيَرُدُّهُ قَالَ ‏ ‏فَيُنَادِيهِ اجْلِسْ قَالَ فَيَجْلِسُ فَيَقُولُ لَهُ مَاذَا تَقُولُ فِي هَذَا الرَّجُلِ ‏ ‏يَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَنْ قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏قَالَ أَنَا أَشْهَدُ أَنَّهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَقُولُ وَمَا يُدْرِيكَ أَدْرَكْتَهُ أَشْهَدُ أَنَّهُ رَسُولُ اللَّهِ قَالَ يَقُولُ عَلَى ذَلِكَ عِشْتَ وَعَلَيْهِ مِتَّ وَعَلَيْهِ تُبْعَثُ قَالَ وَإِنْ كَانَ فَاجِرًا أَوْ كَافِرًا قَالَ جَاءَ الْمَلَكُ وَلَيْسَ بَيْنَهُ وَبَيْنَهُ شَيْءٌ يَرُدُّهُ قَالَ فَأَجْلَسَهُ قَالَ يَقُولُ اجْلِسْ مَاذَا تَقُولُ فِي هَذَا الرَّجُلِ قَالَ أَيُّ رَجُلٍ قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏قَالَ يَقُولُ وَاللَّهِ مَا أَدْرِي سَمِعْتُ النَّاسَ يَقُولُونَ شَيْئًا فَقُلْتُهُ قَالَ فَيَقُولُ لَهُ الْمَلَكُ عَلَى ذَلِكَ عِشْتَ وَعَلَيْهِ مِتَّ وَعَلَيْهِ تُبْعَثُ قَالَ وَتُسَلَّطُ عَلَيْهِ دَابَّةٌ فِي قَبْرِهِ مَعَهَا سَوْطٌ تَمْرَتُهُ جَمْرَةٌ مِثْلُ ‏ ‏غَرْبِ ‏ ‏الْبَعِيرِ تَضْرِبُهُ مَا شَاءَ اللَّهُ ‏ ‏صَمَّاءُ ‏ ‏لَا تَسْمَعُ صَوْتَهُ فَتَرْحَمَهُ ‏","","",""],[25738,25738,"","আমরা একজন মহিলাকে ফোন করেছি যে বলেছে সে কখনো করেনি। আমার বিয়ের জন্য আমার প্রভুর মঙ্গলের জন্য, লর্ডের আদেশ অনুযায়ী। তাকে সব কাপড় আর ফুল দিয়ে দাও।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏فَاطِمَةُ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏أَنَّ امْرَأَةً قَالَتْ يَا رَسُولَ اللَّهِ إِنَّ لِي ‏ ‏ضَرَّةً ‏ ‏فَهَلْ عَلَيَّ ‏ ‏جُنَاحٌ ‏ ‏إِنْ تَشَبَّعْتُ مِنْ زَوْجِي بِغَيْرِ الَّذِي يُعْطِينِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُتَشَبِّعُ بِمَا لَمْ يُعْطَهُ كَلَابِسِ ثَوْبَيْ ‏ ‏زُورٍ ‏","","",""],[25739,25739,"","আমি শপথ করের শপথ করছি , যে শপথ করে ( সেগুলো) নির্ধারণ করুন ( ১ রাজা.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏فَاطِمَةُ بِنْتُ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏أَكَلْنَا فَرَسًا لَنَا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[25740,25740,"","আমরা কথা বলেছিলাম তোমাকে ফোন করা হয়েছে, আমি একটা জগাখিচুড়ি যে তার জন্য দোয়া করেছে... ...আর আমি যদি ওর কাছে কিছু একটা জিনিস পৌঁছে দেই তাহলে সে আমার কাছে পৌঁছে দেবে... তার মাথা থেকে বের করে বলতে হয়, ঈশ্বর তাকে প্রার্থনা করতে বলেছেন।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏فَاطِمَةُ بِنْتُ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّ امْرَأَةً مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَتْ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِي بُنَيَّةً عَرِيسًا وَإِنَّهُ ‏ ‏تَمَرَّقَ ‏ ‏شَعَرُهَا فَهَلْ عَلَيَّ مِنْ ‏ ‏جُنَاحٍ ‏ ‏إِنْ ‏ ‏وَصَلْتُ ‏ ‏رَأْسَهَا ‏ ‏وَقَالَ ‏ ‏وَكِيعٌ ‏ ‏تَمَرَّطَ ‏ ‏شَعْرُهَا ‏ ‏قَالَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْوَاصِلَةَ ‏ ‏وَالْمُسْتَوْصِلَةَ ‏","","",""],[25741,25741,"","আমার বাবার ছেলের একটা কুকুর ছেলে, যার কোন নাম নেই, আমার কাছে পাইলট আছে তার সাথে আমাকে কামড় দিতে আর আমার চোখের ব্যাপারে সচেতন না হতে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏يَا رَسُولَ اللَّهِ لَيْسَ لِي إِلَّا مَا أَدْخَلَ عَلَيَّ ‏ ‏الزُّبَيْرُ ‏ ‏أَفَأَرْضَخُ ‏ ‏مِنْهُ قَالَ ‏ ‏ارْضَخِي ‏ ‏وَلَا ‏ ‏تُوعِي ‏ ‏فَيُوعِيَ ‏ ‏اللَّهُ عَلَيْكِ ‏","","",""],[25742,25742,"","এক বছর আগে আমি আমাকে সাহায্য করার কথা বলেছিলাম। আমি বলছি, যে এক মহিলা তার কাছে প্রার্থনা করবে, সে আমাদের একজনকে দিয়ে দেবে বধির, তাহলে তুমি এটাকে ফোন করবে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏فَاطِمَةُ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏أَنَّ امْرَأَةً أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ إِحْدَانَا يُصِيبُ ثَوْبُهَا مِنْ دَمِ الْحَيْضَةِ قَالَ ‏ ‏تَحُتُّهُ ‏ ‏ثُمَّ ‏ ‏لِتَقْرِضْهُ ‏ ‏بِالْمَاءِ ثُمَّ ‏ ‏تَنْضَحْهُ ‏ ‏ثُمَّ تُصَلِّي فِيهِ ‏","","",""],[25743,25743,"","বাবার বয়স অনুযায়ী আমরা ভিন্নভাবে কথা বলেছি, আমাকে \"আমি ক্ষুধার্ত\" বলে। ঈশ্বরের অনুগ্রহ মুক্তি পেয়েছে এবং শেষ পর্যন্ত তিনি হল থেকে বেরিয়ে এসেছেন।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مُغِيرَةُ بْنُ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي عُمَرَ ‏ ‏مَوْلَى ‏ ‏أَسْمَاءَ ‏ ‏قَالَ ‏ ‏قَالَتْ ‏ ‏أَسْمَاءُ ‏ ‏يَا جَارِيَةُ ‏ ‏نَاوِلِينِي ‏ ‏جُبَّةَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَأَخْرَجَتْ ‏ ‏جُبَّةً ‏ ‏مِنْ ‏ ‏طَيَالِسَةٍ ‏","","",""],[25744,25744,"","আমরা চুপ থাকার ভয়ে কথা বলেছি, যখন আমার বাবা কথা বলেছিলেন, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তাকে রক্ষা করতে হবে অথবা তার রক্ষা করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏نَحَرْنَا ‏ ‏فَرَسًا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَكَلْنَا لَحْمَهُ ‏ ‏أَوْ مِنْ لَحْمِهِ ‏","","",""],[25745,25745,"","আমরা কিছু জিনিস নিয়ে কথা বলেছি যেগুলো আমি ঈশ্বরের উপাসনা করতে পারবো না, আমার রাজা আমার বাবাকে তার ইচ্ছার জন্য প্রার্থনা করতে বলেছে। ঈশ্বর আপনার কাছে এসেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سُلَيْمَانَ ‏ ‏وَعَبْدُ الْجَبَّارِ بْنُ وَرْدٍ ‏ ‏رَجُلَانِ مِنْ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏سَمِعَاهُ مِنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّهَا سَأَلَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ ‏ ‏الزُّبَيْرِ ‏ ‏رَجُلٌ شَدِيدٌ ‏ ‏وَيَأْتِينِي الْمِسْكِينُ فَأَتَصَدَّقُ عَلَيْهِ مِنْ بَيْتِهِ بِغَيْرِ إِذْنِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ارْضَخِي ‏ ‏وَلَا ‏ ‏تُوعِي ‏ ‏فَيُوعِيَ ‏ ‏اللَّهُ عَلَيْكِ ‏","","",""],[25746,25746,"","আমরা একে অপরের নাম বলেছি তিনি আমার ভালবাসার অনুপ্রেরণার একজন ভালো প্রভু। ঈশ্বর তাকে শিখিয়েছেন এবং আপনি আমার মাঝে সচেতন হবেন না ঈশ্বর তোমাকে শিখিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تُوعِي ‏ ‏فَيُوعِيَ ‏ ‏اللَّهُ عَلَيْكِ ‏","","",""],[25747,25747,"","বাবার সবচেয়ে ভালো নাম নিয়ে আমরা কথা বলেছি, আমি লর্ডের কাছে প্রার্থনা করেছি তার জন্য এবং আমি তার অভিজাত দিনের খাবার খেয়েছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏أَبِي عُمَرَ ‏ ‏مَوْلَى ‏ ‏أَسْمَاءَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَتْ لَهُ ‏ ‏جُبَّةٌ ‏ ‏مِنْ ‏ ‏طَيَالِسَةٍ ‏ ‏مَكْفُوفَةٍ ‏ ‏بِالدِّيبَاجِ ‏ ‏يَلْقَى فِيهَا الْعَدُوَّ ‏","","",""],[25748,25748,"","আমি আমার বাবার সাথে কথা বলেছি যে আমি তোমার বাবাকে ভালোবাসি, ঈশ্বর আমার প্রতি যেন আমার সাথে কিছু না করেন। তার ভাই সম্পর্কে কথা বলতে, বাবার মেয়েকে আমরা অনেক কিছু বলি।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏أَسْمَاءُ بِنْتُ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ مَا لِي شَيْءٌ إِلَّا مَا أَدْخَلَ ‏ ‏الزُّبَيْرُ ‏ ‏عَلَى بَيْتِي ‏ ‏فَأُعْطِي مِنْهُ قَالَ ‏ ‏أَعْطِي وَلَا ‏ ‏تُوكِي ‏ ‏فَيُوكِيَ ‏ ‏اللَّهُ عَلَيْكِ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ أَبِي مُلَيْكَةَ ‏ ‏أَنَّ ‏ ‏عَبَّادَ بْنَ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏نَحْوَهُ ‏","","",""],[25749,25749,"","আমরা তোমাকে বলেছিলাম বাবার মত বড় হতে। ঈশ্বর তার জন্য প্রার্থনা করেন এবং তার মেয়ের জন্য ছয় বছরের খাবার প্রদান করেন।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏مَوْلَى أَسْمَاءَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏كَانَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جُبَّةٌ ‏ ‏مِنْ ‏ ‏طَيَالِسَةٍ ‏ ‏لَبِنَتُهَا ‏ ‏دِيبَاجٌ ‏ ‏كِسْرَوَانِيٌّ ‏","","",""],[25750,25750,"","আমরা তোমার সাথে শপথ করে বলেছিলাম কি হয়েছে, সে বলেছিল সে সময় কাটায় বা জেগে উঠবে আর তোমার যত্ন নিবে না।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا ‏ ‏أَنْفِقِي ‏ ‏أَوْ ‏ ‏انْضَحِي ‏ ‏وَلَا ‏ ‏تُحْصِي ‏ ‏فَيُحْصِيَ ‏ ‏اللَّهُ عَلَيْكِ ‏ ‏أَوْ لَا ‏ ‏تُوعِي ‏ ‏فَيُوعِيَ ‏ ‏اللَّهُ عَلَيْكِ ‏","","",""],[25751,25751,"","আমরা একটি মহান খারাপ সঙ্গে কথা করেছি আমরা যে একটি চোরের নাম দ্বারা আপ যে একটি পুত্র প্রেম যে ঈশ্বরকে তার জন্য ক্ষমা এবং আমাকে করতে বলুন. এটা, অথবা এখানে গিয়ে নিজের চোখকে মনে করো না, ঈশ্বর তোমার সাথে আছে, আর তুমি আটকেও যাওনি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏وَكَانَتْ ‏ ‏مُحْصِيَةً ‏ ‏وَعَنِ ‏ ‏عَبَّادِ بْنِ حَمْزَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا ‏ ‏أَنْفِقِي أَوْ ‏ ‏انْضَخِي ‏ ‏أَوْ ‏ ‏انْفَحِي ‏ ‏هَكَذَا وَهَكَذَا وَلَا ‏ ‏تُوعِي ‏ ‏فَيُوعِيَ ‏ ‏اللَّهُ عَلَيْكِ وَلَا ‏ ‏تُحْصِي ‏ ‏فَيُحْصِي ‏ ‏اللَّهُ عَلَيْكِ ‏","","",""],[25752,25752,"","আমরা নিশ্চিত হয়েছি যে, আমরা আগের চেয়ে ভাল কাজ করেছি। ছোট, ছোট, ক্ষুদ্র, ক্ষুদ্র, এমনকী মারাত্মক, অসুখী, অসুখী, অসুখী, অসুখী, অসুখী, অসুখী, অসুখী, অসুখী, অসুখী, অসুখী, অসুখী, অসুখী, অসুখী, অসুখী, অসুখী, অসুখী, অসুখী, অসুখী, অসুখী, অসুখী, অসুখী, অসুখী, মনূষ্য, মন, মন, মন খারাপ । আমি আমার পরিবারের সঙ্গে বাইবেল অধ্যয়ন করতে শুরু করি । সে ঈশ্বরকে তার শান্তির জন্য প্রার্থনা করেছে। সে পানি প্রার্থনা করে এবং তারপর সে অনেক দূরে চলে গেছে। দীর্ঘ সময় তিনি চলে গেছেন। তার আত্মাই প্রথম আংটি, তারপর, সে খুঁজে পেয়েছে, তারপর, তারপর, তারপর, সে আত্মসমর্পণ করেছে, সূর্য হলো মৃত্যুর দুই মাস... ...যার মানে হলো, মৃত্যু আর না থাকলে তার জীবনের একটা অংশ। আমাকে বলতে চাইলে বলতে হবে, যখন তুমি কি বলতে চাও, আমি জানি না। আমি তোমাকে আগুনের থেকে গণনা করতে হবে এবং এটা বলতে হবে না। হয়তো জেল থেকে বেরিয়ে যেতে হবে, চাঁদের মত চাঁদ আমাকে খুন করতে হবে। যাও।","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبَّادِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏خَسَفَتْ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَمِعْتُ رَجَّةَ النَّاسِ وَهُمْ يَقُولُونَ آيَةٌ وَنَحْنُ يَوْمَئِذٍ فِي فَازِعٍ فَخَرَجْتُ ‏ ‏مُتَلَفِّعَةً ‏ ‏بِقَطِيفَةٍ ‏ ‏لِلزُّبَيْرِ ‏ ‏حَتَّى دَخَلْتُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَائِمٌ ‏ ‏يُصَلِّي لِلنَّاسِ فَقُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏مَا لِلنَّاسِ فَأَشَارَتْ بِيَدِهَا إِلَى السَّمَاءِ قَالَتْ فَصَلَّيْتُ مَعَهُمْ وَقَدْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَغَ مِنْ سَجْدَتِهِ الْأُولَى قَالَتْ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قِيَامًا طَوِيلًا حَتَّى رَأَيْتُ بَعْضَ مَنْ ‏ ‏يُصَلِّي ‏ ‏يَنْتَضِحُ ‏ ‏بِالْمَاءِ ثُمَّ رَكَعَ فَرَكَعَ رُكُوعًا طَوِيلًا ثُمَّ قَامَ وَلَمْ يَسْجُدْ قِيَاما طَوِيلًا وَهُوَ دُونَ الْقِيَامِ الْأَوَّلِ ثُمَّ رَكَعَ رُكُوعًا طَوِيلًا وَهُوَ دُونَ رُكُوعِهِ الْأَوَّلِ ثُمَّ سَجَدَ ثُمَّ سَلَّمَ وَقَدْ ‏ ‏تَجَلَّتْ ‏ ‏الشَّمْسُ ثُمَّ ‏ ‏رَقِيَ ‏ ‏الْمِنْبَرَ ثُمَّ قَالَ أَيُّهَا النَّاسُ ‏ ‏إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ ‏ ‏آيَاتِ ‏ ‏اللَّهِ لَا يَخْسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ فَإِذَا رَأَيْتُمْ ذَلِكَ ‏ ‏فَافْزَعُوا ‏ ‏إِلَى الصَّلَاةِ وَإِلَى ‏ ‏الصَّدَقَةِ ‏ ‏وَإِلَى ذِكْرِ اللَّهِ أَيُّهَا النَّاسُ إِنَّهُ لَمْ يَبْقَ شَيْءٌ لَمْ أَكُنْ رَأَيْتُهُ إِلَّا وَقَدْ رَأَيْتُهُ فِي مَقَامِي هَذَا وَقَدْ أُرِيتُكُمْ ‏ ‏تُفْتَنُونَ ‏ ‏فِي قُبُورِكُمْ يُسْأَلُ أَحَدُكُمْ مَا كُنْتَ تَقُولُ وَمَا كُنْتَ تَعْبُدُ فَإِنْ قَالَ لَا أَدْرِي رَأَيْتُ النَّاسَ يَقُولُونَ شَيْئًا فَقُلْتُهُ وَيَصْنَعُونَ شَيْئًا فَصَنَعْتُهُ قِيلَ لَهُ أَجَلْ عَلَى الشَّكِّ عِشْتَ وَعَلَيْهِ مِتَّ هَذَا ‏ ‏مَقْعَدُكَ مِنْ النَّارِ وَإِنْ قَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ قِيلَ عَلَى ‏ ‏الْيَقِينِ ‏ ‏عِشْتَ قَالَ مِتَّ هَذَا مَقْعَدُكَ مِنْ الْجَنَّةِ وَقَدْ رَأَيْتُ خَمْسِينَ ‏ ‏أَوْ سَبْعِينَ ‏ ‏أَلْفًا يَدْخُلُونَ الْجَنَّةَ فِي مِثْلِ صُورَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ فَقَامَ إِلَيْهِ رَجُلٌ فَقَالَ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ قَالَ اللَّهُمَّ اجْعَلْهُ مِنْهُمْ أَيُّهَا النَّاسُ إِنَّكُمْ لَنْ تَسْأَلُونِي عَنْ شَيْءٍ حَتَّى أَنْزِلَ إِلَّا أَخْبَرْتُكُمْ بِهِ فَقَامَ رَجُلٌ فَقَالَ مَنْ أَبِي قَالَ أَبُوكَ فُلَانٌ الَّذِي كَانَ يُنْسَبُ إِلَيْهِ ‏","","",""],[25753,25753,"","আমরা আমার বাবার সঙ্গে ঝগড়ার বিষয়ে কথা বলেছিলাম, যিনি আমাদের আরেকটা মুকুট দিয়েছিলেন । আত্মসমর্পণ করো যদি আগুনকে বাঁচাতে হয়.","‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ بَابٍ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏أَبِي عُمَرَ ‏ ‏خَتَنٌ ‏ ‏كَانَ ‏ ‏لِعَطَاءٍ ‏ ‏أَخْرَجَتْ لَنَا ‏ ‏أَسْمَاءُ ‏ ‏جُبَّةً ‏ ‏مَزْرُورَةً ‏ ‏بِدِيبَاجٍ ‏ ‏قَالَتْ قَدْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا لَقِيَ الْحَرْبَ لَبِسَ هَذِهِ ‏","","",""],[25754,25754,"","আমরা একটা ছেলেকে হত্যা করার কথা বলেছিলাম যে একবার তার বাবাকে নিয়ে আমাদের কথা বলেছে। পর্দার পর্দার উপর দিয়ে চলে যাও, আল্লাহ আছে আর আমি বলবো, আমার মা আমার দক্ষতা বাড়িয়ে দিয়েছে, আমার মনে হয় সে তার মতো দেখতে শুরু করেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏قَدِمَتْ عَلَيَّ ‏ ‏أُمِّي ‏ ‏وَهِيَ رَاغِبَةٌ وَهِيَ مُشْرِكَةٌ فِي عَهْدِ ‏ ‏قُرَيْشٍ ‏ ‏وَمُدَّتِهِمْ الَّتِي كَانَتْ بَيْنَهُمْ وَبَيْنَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ ‏ ‏أُمِّي ‏ ‏قَدِمَتْ عَلَيَّ وَهِيَ رَاغِبَةٌ وَهِيَ مُشْرِكَةٌ ‏ ‏أَفَأَصِلُهَا ‏ ‏قَالَ ‏ ‏صِلِيهَا ‏ ‏قَالَ وَأَظُنُّهَا ‏ ‏ظِئْرَهَا ‏","","",""],[25755,25755,"","আমরা চেষ্টা করেছি. ঐ আচে যে ওকে মেরে ফেলেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ نَوْفَلٍ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏كُنَّا ‏ ‏نُؤَدِّي زَكَاةَ الْفِطْرِ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُدَّيْنِ ‏ ‏مِنْ قَمْحٍ ‏ ‏بِالْمُدِّ ‏ ‏الَّذِي تَقْتَاتُونَ بِهِ ‏","","",""],[25756,25756,"","আমরা দুই বছর ধরে একজন যাজকের কাছ থেকে পালিয়েছি, ঈশ্বর তাকে শিখিয়েছেন আর একটা ছেলেকে আমার কাছে দিয়ে দিয়েছে যে তাকে বিছানা বলে ডাকতে পারে নি।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أُمِّ قَيْسٍ بِنْتِ مِحْصَنٍ ‏ ‏قَالَتْ ‏ ‏دَخَلْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِابْنٍ لِي لَمْ يَطْعَمْ ‏ ‏فَبَالَ عَلَيْهِ فَدَعَا بِمَاءٍ فَرَشَّهُ عَلَيْهِ ‏","","",""],[25757,25757,"","আমরা প্রভুর মায়ের মরুভূমি সম্পর্কে কথা বলেছি, যে একজন যাজককে বেছে নিয়েছেন, যে একজন যাজকের দ্বারা নির্বাচিত হয়েছে, যে একজন যাজকের দ্বারা যিনি একজন মৃত যাজকের হাতে খুন হওয়া একজন চোরকে, আমি ঈশ্বরের কাছে প্রার্থনা করতে হবে, আর সে তার রক্ত না খেয়ে এটা উদ্ধার করবে। পরমাণুর সাহায্যে বলা যায় তুমি কি করবে... ...নাকি করবে, নাকি তুমি এটা করবে, একবার হলেও, ভারত পাপ করতে ফিরে আসবে।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أُمِّ قَيْسٍ بِنْتِ مِحْصَنٍ ‏ ‏أُخْتِ ‏ ‏عُكَّاشَةَ بْنِ مِحْصَنٍ ‏ ‏قَالَتْ ‏ ‏دَخَلْتُ بِابْنٍ لِي عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَأْكُلْ الطَّعَامَ فَبَالَ فَدَعَا بِمَاءٍ فَرَشَّهُ وَدَخَلْتُ بِابْنٍ لِي قَدْ أَعْلَقْتُ عَنْهُ ‏ ‏وَقَالَ ‏ ‏مَرَّةً عَلَيْهِ ‏ ‏مِنْ ‏ ‏الْعُذْرَةِ ‏ ‏فَقَالَ ‏ ‏عَلَامَ ‏ ‏تَدْغَرْنَ ‏ ‏أَوْلَادَكُنَّ بِهَذَا ‏ ‏الْعِلَاقِ ‏ ‏عَلَيْكُمْ بِهَذَا الْقُسْطِ ‏ ‏وَقَالَ ‏ ‏مَرَّةً ‏ ‏سُفْيَانُ ‏ ‏الْعُودِ الْهِنْدِيِّ ‏ ‏فَإِنَّ بِهِ سَبْعَةَ أَشْفِيَةٍ مِنْهَا ذَاتُ الْجَنْبِ ‏ ‏يُسْعَطُ ‏ ‏مِنْ ‏ ‏الْعُذْرَةِ ‏ ‏وَيُلَدُّ مِنْ ذَاتِ الْجَنْبِ ‏","","",""],[25758,25758,"","একজন যাজক যিনি ঈশ্বরের কাছে তার সর্বোত্তমটা চাইতে চাইবেন, তিনি সেই ব্যক্তির কাছে নিজেকে উৎসর্গ করবেন বলে আমরা খুশি হব । আর পানি আর দাগ আর গরম দিয়ে পরিষ্কার করো।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ثَابِتٌ أَبُو الْمِقْدَامِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَدِيُّ بْنُ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أُمَّ قَيْسٍ بِنْتَ مِحْصَنٍ ‏ ‏قَالَتْ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الثَّوْبِ يُصِيبُهُ دَمُ الْحَيْضِ قَالَ حُكِّيهِ ‏ ‏بِضِلَعٍ ‏ ‏وَاغْسِلِيهِ بِالْمَاءِ ‏ ‏وَالنَّدِّ ‏ ‏وَسِدْرٍ ‏","","",""],[25759,25759,"","আমরা কথা বলেছি, আর আমরা কথা বলেছি, কিন্তু আমার বাবা আমাকে আমার বাবার চেয়ে ভালো ভালোবাসে। আমার মা বলেন, তিনি আমার ছেলের ক্ষমা করবেন। যদি তার কাছে ঘোড়া থাকে যে কিনা তার নিজের আদেশ আছে আর তাকে ভয় পেতে বলেছে, সে পাশ করেছে, আমি জানি না যে কোন মহিলা মারা গেছে।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وهَاشِمٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْحَسَنِ ‏ ‏مَوْلَى ‏ ‏أُمِّ قَيْسٍ بِنْتِ مِحْصَنٍ ‏ ‏عَنْ ‏ ‏أُمِّ قَيْسٍ ‏ ‏أَنَّها قَالَتْ ‏ ‏تُوُفِّيَ ابْنِي ‏ ‏فَجَزِعْتُ ‏ ‏عَلَيْهِ فَقُلْتُ لِلَّذِي يَغْسِلُهُ ‏ ‏لَا تَغْسِلْ ابْنِي بِالْمَاءِ الْبَارِدِ فَتَقْتُلَهُ فَانْطَلَقَ ‏ ‏عُكَّاشَةُ بْنُ مِحْصَنٍ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ بِقَوْلِهَا فَتَبَسَّمَ ثُمَّ قَالَ مَا قَالَتْ طَالَ عُمْرُهَا ‏ ‏قَالَ ‏ ‏فَلَا أَعْلَمُ امْرَأَةً عُمِّرَتْ مَا عُمِّرَتْ ‏","","",""],[25760,25760,"","আমরা ঈশ্বরের সবচেয়ে ভালোটা সম্বন্ধে কথা বলেছিলাম কিন্তু এরপর আমরা বিয়ের ব্যাপারে কথা বলেছিলাম । তার পাপের হার রয়েছে আর এরপর তিনি ভবিষ্যদ্বাণীটা গ্রহণ করেন এবং তার কাছে রয়েছে । আমরা ঈশ্বরের সেরা জল ব্যবহার করেছি। আমরা তাকে বলেছিলাম, সে যে খাবার বানিয়েছে তা খেতে নয়। এবং প্রতিবেশীরা বলে যে, এই ফুলটি নিতে পারবে না। কুমারী আর সেই কাপুরুষের জন্য জন্ম নিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏أُمِّْ قَيْسٍ بِنْتِ مِحْصَنٍ الْأَسَدِيَّةِ ‏ ‏أُخْتِ ‏ ‏عُكَّاشَةَ ‏ ‏قَالَتْ ‏ ‏جِئْتُ بِابْنٍ لِي قَدْ أَعْلَقْتُ عَنْهُ أَخَافُ أَنْ يَكُونَ بِهِ ‏ ‏الْعُذْرَةُ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَامَ ‏ ‏تَدْغَرْنَ ‏ ‏أَوْلَادَكُنَّ بِهَذِهِ ‏ ‏الْعَلَائِقِ ‏ ‏عَلَيْكُنَّ بِهَذَا الْعُودِ الْهِنْدِيِّ قَالَ ‏ ‏يَعْنِي ‏ ‏الْكُسْتَ ‏ ‏فَإِنَّ فِيهِ سَبْعَةَ أَشْفِيَةٍ مِنْهَا ‏ ‏ذَاتُ الْجَنْبِ ‏ ‏ثُمَّ أَخَذَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَبِيَّهَا فَوَضَعَهُ فِي حِجْرِهِ فَبَالَ عَلَيْهِ فَدَعَا بِمَاءٍ فَنَضَحَهُ وَلَمْ يَكُنْ الصَّبِيُّ بَلَغَ أَنْ يَأْكُلَ الطَّعَامَ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏فَمَضَتْ السُّنَّةُ بِأَنْ يُرَشَّ بَوْلُ الصَّبِيِّ وَيُغْسَلَ بَوْلُ ‏ ‏الْجَارِيَةِ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏فَيُسْتَسْعَطُ ‏ ‏لِلْعُذْرَةِ ‏ ‏وَيُلَدُّ ‏ ‏لِذَاتِ الْجَنْبِ ‏","","",""],[25761,25761,"","আমরা বাবার নিয়মিত বাবার কাছে প্রার্থনা করেছি, যে তার মায়ের কাছে ঋণী। আমি ঈশ্বরের কাছে প্রার্থনা করব তার কাছে প্রার্থনা করব এবং তাকে আত্মসমর্পণ করব। প্রেম তাঁর প্রজ্ঞা ও কিছু অর্থ দিয়ে পশমের মতো কাজ করে ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ أَبِي الْمِقْدَامِ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏أُمِّ قَيْسٍ بِنْتِ مِحْصَنٍ ‏ ‏قَالَتْ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ دَمِ الْحَيْضِ يُصِيبُ الثَّوْبَ فَقَالَ حُكِّيهِ وَلَوْ ‏ ‏بِضِلَعٍ ‏","","",""],[25762,25762,"","আমরা আমার উপহারপ্রাপ্ত ছেলের ব্যাপারে কথা বলেছি যে বলেছিল যে আমরা একটা কাজ করেছি... ...যে আমাকে খুজে বের করে। একজন সাহায্যকারীকে পাঠানো হবে, সে ঈশ্বরের রক্তে তার সবচেয়ে ভালো আগ্রহ। তার কিছু জিনিস ছিল।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ دِينَارٍ ‏ ‏مَوْلَى ‏ ‏أُمِّ قَيْسٍ ‏ ‏عَنْ ‏ ‏أُمِّ قَيْسٍ بِنْتِ مِحْصَنٍ ‏ ‏قَالَتْ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ دَمِ الْحَيْضِ يُصِيبُ الثَّوْبَ فَقَالَ اغْسِلِيهِ بِمَاءٍ ‏ ‏وَسِدْرٍ ‏ ‏وَحُكِّيهِ ‏ ‏بِضِلَعٍ ‏","","",""],[25763,25763,"","আমরা বিয়ের ব্যাপারে কথা বলেছিলাম, যখন তিনি আমাদের বিয়ের বিষয়ে আমাদের বলেছিলেন । সে বলল যে সে এমন একজন যে কিনা যুদ্ধ করার ক্ষমতা রাখে। সে বলল যে সে ঈশ্বরের কাছে যাবে, সে এমন একটা ছেলের জন্য চলে যাবে, যার নেই। বিজ্ঞান বন্যাগ্রস্ত ছিল বা বলতে পারত আমরা রেড এর সাথে কথা বলেছি। ইশ্বরের জন্য প্রার্থনা করুন এবং তিনি এমন একটি পতাকা দেবেন যা ঈর্ষার আগুন হতে পারে অথবা হতে পারে। তোমার সাথে বছর।","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏أَنَّ ‏ ‏أُمَّ قَيْسٍ بِنْتَ مِحْصَنٍ ‏ ‏إِحْدَى ‏ ‏بَنِي أَسَدِ بْنِ خُزَيْمَةَ ‏ ‏وَكَانَتْ مِنْ ‏ ‏الْمُهَاجِرَاتِ ‏ ‏الْأُوَلِ اللَّائِي بَايَعْنَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَأَخْبَرَتْنِي ‏ ‏أَنَّهَا أَتَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِابْنٍ لَهَا لَمْ يَبْلُغْ أَنْ يَأْكُلَ الطَّعَامَ فَذَكَرَ الْحَدِيثَ وَقَالَ عَلَامَ ‏ ‏تَدْغَرْنَ ‏ ‏أَوْلَادَكُنَّ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَقَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏عَنْ ‏ ‏أُمِّْ قَيْسٍ بِنْتِ مِحْصَنٍ ‏ ‏أَنَّهَا جَاءَتْ بِابْنٍ لَهَا وَقَدْ أَعْلَقَتْ عَلَيْهِ مِنْ ‏ ‏الْعُذْرَةِ ‏ ‏فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَامَ ‏ ‏تَدْغَرْنَ ‏ ‏أَوْلَادَكُنَّ بِهَذِهِ ‏ ‏الْعُلُقِ ‏ ‏عَلَيْكُنَّ بِهَذَا الْعُودِ الْهِنْدِيِّ فَإِنَّ فِيهِ سَبْعَةَ أَشْفِيَةٍ مِنْهَا ‏ ‏ذَاتُ الْجَنْبِ ‏ ‏ثُمَّ أَخَذَ الصَّبِيَّ فَبَالَ عَلَيْهِ فَدَعَا بِمَاءٍ ‏ ‏فَنَضَحَهُ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏مَضَتْ السُّنَّةُ بِذَلِكَ ‏","","",""],[25764,25764,"","আমি ভয় পাচ্ছি যে আমার বাবা তাকে হত্যা করতে রাজি হবেন।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏سَهْلَةَ ‏ ‏امْرَأَةِ ‏ ‏أَبِي حُذَيْفَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏سَالِمًا ‏ ‏مَوْلَى ‏ ‏أَبِي حُذَيْفَةَ ‏ ‏يَدْخُلُ عَلَيَّ وَهُوَ ذُو لِحْيَةٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْضِعِيهِ فَقَالَتْ كَيْفَ أُرْضِعُهُ وَهُوَ ذُو لِحْيَةٍ فَأَرْضَعَتْهُ فَكَانَ يَدْخُلُ عَلَيْهَا ‏","","",""],[25765,25765,"","আমরা দুই বছর ধরে একটা মেয়ের উপাধি দিয়ে কাজ করেছি যে কিনা নিজের প্রভুর ছেলেকে শুনতে পাবে। আমি ভগবানকে খুন করতে এবং আমাদের ক্ষমা চাইতে বলবো। সে বলল আমি মেয়েদের সাথে থাকতে দেব না। আমাকে একশ জন মহিলার কাছে বল।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏قَالَ سَمِعَ ‏ ‏ابْنُ الْمُنْكَدِرِ ‏ ‏أُمَيْمَةَ بِنْتَ رُقَيْقَةَ ‏ ‏تَقُولُ ‏ ‏بَايَعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي نِسْوَةٍ فَلَقَّنَنَا فِيمَا اسْتَطَعْتُنَّ ‏ ‏وَأَطَقْتُنَّ ‏ ‏قُلْتُ اللَّهُ وَرَسُولُهُ أَرْحَمُ مِنَّا مِنْ أَنْفُسِنَا قُلْتُ يَا رَسُولَ اللَّهِ بَايِعْنَا قَالَ ‏ ‏إِنِّي لَا أُصَافِحُ النِّسَاءَ إِنَّمَا قَوْلِي لِامْرَأَةٍ قَوْلِي لِمِائَةِ امْرَأَةٍ ‏","","",""],[25766,25766,"","আমরা ব্রেন্ডামকে মারতে চেষ্টা করেছি, আমার বাবার ছেলেকে নিয়ে কথা বলতে বলেছিলাম, কিন্তু সে আমাকে খুন করার চেষ্টা করেছে। তুমি হচ্ছে সেই উত্তরাধিকারী যাকে আমি আদেশ করছি, ঈশ্বর আত্মসমর্পণ করেছে ঈশ্বর ও তাঁর বার্তাবাহককে আমরা বলেছিলাম যে, ঈশ্বর আপনার কাছে এসেছেন । আমাদের বিশ্বাস হারিয়ে যাওয়ার চেয়ে আমাদের প্রতি করুণা আর কিছুই নেই । যেতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏أُمَيْمَةَ بِنْتِ رُقَيْقَةَ التَّيْمِيَّةِ ‏ ‏قَالَتْ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي نِسْوَةٍ مِنْ الْمُسْلِمِينَ لِنُبَايِعَهُ فَقُلْنَا يَا رَسُولَ اللَّهِ جِئْنَا لِنُبَايِعَكَ عَلَى أَنْ لَا نُشْرِكَ بِاللَّهِ شَيْئًا وَلَا نَسْرِقَ وَلَا نَزْنِيَ وَلَا نَقْتُلَ أَوْلَادَنَا وَلَا نَأْتِيَ ‏ ‏بِبُهْتَانٍ ‏ ‏نَفْتَرِيهِ ‏ ‏بَيْنَ أَيْدِينَا وَأَرْجُلِنَا وَلَا نَعْصِيَكَ فِي مَعْرُوفٍ قَالَتْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا اسْتَطَعْتُنَّ وَأَطَعْتُنَّ قَالَتْ قُلْنَا اللَّهُ وَرَسُولُهُ أَرْحَمُ بِنَا مِنْ أَنْفُسِنَا ‏ ‏بَايِعْنَا ‏ ‏يَا رَسُولَ اللَّهِ قَالَ ‏ ‏اذْهَبْنَ فَقَدْ ‏ ‏بَايَعْتُكُنَّ ‏ ‏إِنَّمَا قَوْلِي لِمِائَةِ امْرَأَةٍ كَقَوْلِي لِامْرَأَةٍ وَاحِدَةٍ قَالَتْ وَلَمْ يُصَافِحْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنَّا امْرَأَةً ‏","","",""],[25767,25767,"","ঈশ্বর যদি তার জন্য প্রার্থনা করতেন এবং আমাদের প্রভু প্রভু, আমরা কিছু একটা বলি, তা হলে আমরা তাকে বাঁচাতে চেয়েছিলাম । চুরি না করা, আমরা দুটো ঘোড়া নিয়ে যাব না, তুমি নিশ্চিত করতে পারবে যে আমরা ঈশ্বরকে বলে দেব আর আমাদের কাছ থেকে তাকে আবার বিজয়ী হতে পাঠিয়ে দিবো। ঈশ্বর তাকে জিজ্ঞেস করেছেন, আর তিনি তার কাছে আত্মসমর্পণ করবেন যাতে আমি নারীদের ক্ষমা না করি। যখন আমি একজন নারীকে বলি যে, যে কিনা শক্তিশালী, সে একজন মহিলার সাথে থাকতে সক্ষম হতে সক্ষম হতে সক্ষম হতে সক্ষম হতে সক্ষম হতে সক্ষম হয়।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏أُمَيْمَةَ بِنْتِ رُقَيْقَةَ ‏ ‏أَنَّها قَالَتْ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي نِسْوَةٍ ‏ ‏نُبَايِعُهُ ‏ ‏فَقُلْنَا يَا رَسُولَ اللَّهِ ‏ ‏نُبَايِعُكَ ‏ ‏عَلَى أَنْ لَا نُشْرِكَ بِاللَّهِ شَيْئًا وَلَا نَسْرِقَ وَلَا نَزْنِيَ وَلَا نَأْتِيَ ‏ ‏بِبُهْتَانٍ ‏ ‏نَفْتَرِيهِ ‏ ‏بَيْنَ أَيْدِينَا وَأَرْجُلِنَا وَلَا نَعْصِيَكَ فِي مَعْرُوفٍ قَالَ قَالَ فِيمَا اسْتَطَعْتُنَّ وَأَطَعْتُنَّ قَالَتْ فَقُلْنَا اللَّهُ وَرَسُولُهُ أَرْحَمُ بِنَا مِنَّا بِأَنْفُسِنَا ‏ ‏هَلُمَّ ‏ ‏نُبَايِعُكَ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَا أُصَافِحُ النِّسَاءَ إِنَّمَا قَوْلِي لِمِائَةِ امْرَأَةٍ كَقَوْلِي لِامْرَأَةٍ وَاحِدَةٍ ‏","","",""],[25768,25768,"","আমি বলেছি, নবী তার জন্য প্রার্থনা করেছেন এবং তার বাবার নামে উদ্ধার করা হবে। আমি বলেছি, আমি নিশ্চিত হতে পারব যে আমরা ঈশ্বরকে বলে দেব এবং আমাদের নিজেদের ক্ষতি থেকে আমাদের স্বস্তি চাইতে চাই। আমি নারীদের জন্য দুঃখিত, আমি একজন নারীর মত শক্তিশালী বলে বলছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ يَعْنِي ابْنَ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏أُمَيْمَةَ بِنْتِ رُقَيْقَةَ ‏ ‏قَالَتْ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي نِسَاءٍ ‏ ‏نُبَايِعُهُ ‏ ‏فَأَخَذَ عَلَيْنَا مَا فِي الْقُرْآنِ أَنْ لَا نُشْرِكَ بِاللَّهِ شَيْئًا الْآيَةَ قَالَ فِيمَا اسْتَطَعْتُنَّ وَأَطَعْتُنَّ قُلْنَا اللَّهُ وَرَسُولُهُ أَرْحَمُ بِنَا مِنْ أَنْفُسِنَا قُلْنَا يَا رَسُولَ اللَّهِ أَلَا تُصَافِحُنَا قَالَ ‏ ‏إِنِّي لَا أُصَافِحُ النِّسَاءَ إِنَّمَا قَوْلِي لِامْرَأَةٍ وَاحِدَةٍ كَقَوْلِي لِمِائَةِ امْرَأَةٍ ‏","","",""],[25769,25769,"","আমরা একে অপরের সর্বোচ্চ চেষ্টা করেছি বিশ্বের সেরা সেরাদের জন্য। ঈশ্বর তাকে জিজ্ঞেস করেছেন এবং আমি বলব আমি সেরা ব্যক্তি নই যে, আমি এই কথা বলার জন্য সে সবচেয়ে ভালো মানুষ। আমি কি তাকে বলতে পারি? মহিলা মহিলা একজন মহিলা।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أُمَيْمَةَ بِنْتَ رُقَيْقَةَ ‏ ‏تُحَدِّثُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَسْتُ أُصَافِحُ النِّسَاءَ إِنَّمَا قَوْلِي لِامْرَأَةٍ وَاحِدَةٍ كَقَوْلِي لِمِائَةِ امْرَأَةٍ ‏","","",""],[25770,25770,"","তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন যেন তিনি নারীদের হত্যা করেন বা তাদের সঙ্গে শুতেন কিন্তু তিনি যে জ্যোতিতে আছেন, সেই আলোকেই তিনি আমার মেধার সবচেয়ে ভালটা জানেন । এমন একজন মহিলা, যে তাকে দেখাতে চায় যে সে আমাদের উপর অত্যাচার করে যদি আমাদের সাথে কোন শক্তির কথা বলে, তাহলে তার এই সিদ্ধান্তের কিছু ধাপ নিয়ে আমি তাকে কিছু ধাপ নিয়ে যাই। ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏رِبْعِيٍّ ‏ ‏عَنِ ‏ ‏امْرَأَتِهِ ‏ ‏عَنْ ‏ ‏أُخْتِ حُذَيْفَةَ ‏ ‏قَالَتْ ‏ ‏خَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا مَعْشَرَ النِّسَاءِ ‏ ‏أَمَا لَكُنَّ فِي الْفِضَّةِ مَا تَحَلَّيْنَ أَمَا إِنَّهُ لَيْسَ مِنْكُنَّ امْرَأَةٌ تَحَلَّى ذَهَبًا تُظْهِرُهُ إِلَّا عُذِّبَتْ بِهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏رِبْعِيِّ بْنِ حِرَاشٍ ‏ ‏عَنْ ‏ ‏امْرَأَتِهِ ‏ ‏عَنِ ‏ ‏أُخْتِ خُذَيْفَةَ ‏ ‏قَالَتْ ‏ ‏خَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[25771,25771,"","আমি এই সময়ের মধ্যে সব থেকে ভালো দুজন ছেলেকে বলেছিলাম আমার কার নিয়ে যেতে হবে। আমি হয়তো নবীকে ঈশ্বরের ইচ্ছার দিকে টেনে নিয়ে যেতে পারি এবং এটিকে টেনে আনতে পারি। আমি এই ক্ষেত্রে নেই। তুমি হয়তো মনে করো এটা নারী হতে যাচ্ছে না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏رِبْعِيٍّ ‏ ‏عَنْ ‏ ‏امْرَأَتِهِ ‏ ‏عَنْ ‏ ‏أُخْتِ حُذَيْفَةَ ‏ ‏وَكُنَّ لَهُ أَخَوَاتٌ قَدْ أَدْرَكْنَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏خَطَبَنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا مَعْشَرَ النِّسَاءِ ‏ ‏أَلَيْسَ لَكُنَّ فِي الْفِضَّةِ مَا تَحَلَّيْنَ أَمَا إِنَّهُ لَيْسَتْ مِنْكُنَّ امْرَأَةٌ ‏ ‏تَتَحَلَّى ذَهَبًا تُظْهِرُهُ إِلَّا عُذِّبَتْ بِهِ ‏","","",""],[25772,25772,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমাদের জন্য একটা সমস্যা তৈরি করেছে, সে আমাকে একটা বাজে কাপড়ের জন্য দোষারোপ করতে পেরে খুবই ক্লান্ত। ঈশ্বর যেন আমার আত্মার নির্দেশনা দেন... ...যে লর্ডের অনুগ্রহে...","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ النُّعْمَانِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏طَلْحَةَ الْأَيَامِيَّ ‏ ‏يُحَدِّثُ ‏ ‏وَيَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ النُّعْمَانِ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ مُصَرِّفٍ ‏ ‏عَنِ ‏ ‏امْرَأَةٍ ‏ ‏مِنْ ‏ ‏بَنِي عَبْدِ الْقَيْسِ ‏ ‏عَنْ ‏ ‏أُخْتِ عَبْدِ اللَّهِ بْنِ رَوَاحَةَ الْأَنْصَارِيِّ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏وَجَبَ الْخُرُوجُ عَلَى كُلِّ ذَاتِ نِطَاقٍ ‏","","",""],[25773,25773,"","আমরা দুই বছর আমার বাবাকে হত্যা করেছি, কিন্তু ঈশ্বর একটা কুত্তার ছেলে। ঈশ্বরের শান্তি যেন শীঘ্রই আসে। সে আমার পিছনে যাবে, আর তার কাছে তৃতীয় আর সে যখন বলেছে সে তাদের ভিতরে ঢোকার আগে সে তার হাত তুলে নিয়েছে, তিন বছর ধরে তার আসল আর তিন বছর আর তার রাজত্বের অনুগ্রহ আছে, আমি জিজ্ঞাসা করবো, আর সে একজন জিনিয়াসের ছেলে...","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَقِيلِ بْنِ أَبِي طَالِبٍ ‏ ‏قَالَ ‏ ‏أَرْسَلَنِي ‏ ‏عَلِيُّ بْنُ حُسَيْنٍ ‏ ‏إِلَى ‏ ‏الرُّبَيِّعِ بِنْتِ مُعَوِّذِ ابْنِ عَفْرَاءَ ‏ ‏فَسَأَلْتُهَا عَنْ وُضُوءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْرَجَتْ لَهُ ‏ ‏يَعْنِي إِنَاءً يَكُونُ ‏ ‏مُدًّا ‏ ‏أَوْ نَحْوَ مُدٍّ وَرُبُعٍ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏كَأَنَّهُ يَذْهَبُ إِلَى ‏ ‏الْهَاشِمِيِّ ‏ ‏قَالَتْ كُنْتُ ‏ ‏أُخْرِجُ لَهُ الْمَاءَ فِي هَذَا فَيَصُبُّ عَلَى يَدَيْهِ ثَلَاثًا ‏ ‏وَقَالَ ‏ ‏مَرَّةً يَغْسِلُ يَدَيْهِ قَبْلَ أَنْ يُدْخِلَهُمَا ‏ ‏وَيَغْسِلُ وَجْهَهُ ثَلَاثًا وَيُمَضْمِضُ ثَلَاثًا وَيَسْتَنْشِقُ ثَلَاثًا وَيَغْسِلُ يَدَهُ الْيُمْنَى ثَلَاثًا وَالْيُسْرَى ثَلَاثًا وَيَمْسَحُ بِرَأْسِهِ وَقَالَ مَرَّةً ‏ ‏أَوْ مَرَّتَيْنِ ‏ ‏مُقْبِلًا وَمُدْبِرًا ثُمَّ يَغْسِلُ رِجْلَيْهِ ثَلَاثًا قَدْ جَاءَنِي ابْنُ عَمٍّ لَكَ فَسَأَلَنِي وَهُوَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَأَخْبَرْتُهُ ‏ ‏فَقَالَ ‏ ‏مَا أَجِدُ فِي كِتَابِ اللَّهِ إِلَّا مَسْحَتَيْنِ وَغَسْلَتَيْنِ ‏","","",""],[25774,25774,"","আমরা দুই মাস ধরে ঈশ্বরের ছেলের কথা বলেছি। সে বলেছিল, তার জন্য প্রার্থনা করা উচিত। সে অনেক গান গেয়েছিল, সে অনেক কিছু গেয়েছিল। এরপর তিনি তার অহংকারের প্রতি তার হাত ধুইয়ে দিয়েছিলেন এবং কিছুক্ষণের জন্য তার পা ধুইয়ে দিয়েছিলেন এবং তাকে ক্ষতি করার অনুমতি দিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏الرُّبَيِّعُ بِنْتُ مُعَوِّذِ ابْنِ عَفْرَاءَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْتِينَا فَيُكْثِرُ فَأَتَانَا فَوَضَعْنَا لَهُ ‏ ‏الْمِيضَأَةَ ‏ ‏فَتَوَضَّأَ فَغَسَلَ كَفَّيْهِ ثَلَاثًا وَمَضْمَضَ وَاسْتَنْشَقَ مَرَّةً مَرَّةً وَغَسَلَ وَجْهَهُ ثَلَاثًا وَذِرَاعَيْهِ ثَلَاثًا وَمَسَحَ رَأْسَهُ بِمَا بَقِيَ مِنْ وَضُوئِهِ فِي يَدَيْهِ مَرَّتَيْنِ بَدَأَ بِمُؤَخَّرِهِ ثُمَّ رَدَّ يَدَهُ إِلَى نَاصِيَتِهِ وَغَسَلَ رِجْلَيْهِ ثَلَاثًا وَمَسَحَ أُذُنَيْهِ مُقَدَّمَهُمَا وَمُؤَخَّرَهُمَا ‏","","",""],[25775,25775,"","ঈশ্বর তাকে প্রার্থনা করেছিলেন এবং তিনি প্রভুর কাছে প্রার্থনা করেছিলেন এবং তাদেরকে সেবা করার এবং মৃত্যুবরণ করার জন্য তাঁকে সেবা করার জন্য ।","‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ الْمُفَضَّلِ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ ذَكْوَانَ ‏ ‏عَنِ ‏ ‏الرُّبَيِّعِ بِنْتِ مُعَوِّذِ ابْنِ عَفْرَاءَ ‏ ‏قَالَتْ ‏ ‏كُنَّا نَغْزُو مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَسْقِي الْقَوْمَ وَنَخْدُمُهُمْ وَنَرُدُّ الْجَرْحَى وَالْقَتْلَى إِلَى ‏ ‏الْمَدِينَةِ ‏","","",""],[25776,25776,"","ঈশ্বরের পুত্রের মৃত্যুর জন্য আমরা একে অপরের সাথে কথা বলেছি, আমি ঈশ্বরের কাছে প্রার্থনা করছি তার জন্য প্রার্থনা করছি এবং তিনি আমাদেরকে তিন বার সূর্য থেকে একটি কথা বলার জন্য আত্মসমর্পণ করবেন। শেষ অনুপ্রবেশকারী, আমি তার কানে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنِ ‏ ‏الرُّبَيِّعِ بِنْتِ مُعَوِّذِ ابْنِ عَفْرَاءَ ‏ ‏قَالَتْ ‏ ‏أَتَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَضَعْنَا لَهُ ‏ ‏الْمِيضَأَةَ ‏ ‏فَتَوَضَّأَ ثَلَاثًا ثَلَاثًا وَمَسَحَ بِرَأْسِهِ مَرَّتَيْنِ بَدَأَ بِمُؤَخَّرِهِ وَأَدْخَلَ أُصْبُعَيْهِ فِي أُذُنَيْهِ ‏","","",""],[25777,25777,"","আমরা একটা ছেলের জন্য কথা বলেছি যে তোমার সাথে ব্যস্ত... ...যে ঈশ্বরের জন্য প্রার্থনা করে আর স্বপ্নের শিকার হয়, আমি তাকে আমার গলায় গুলি করতে যাচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏حَسَنٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَقِيلٍ ‏ ‏عَنِ ‏ ‏الرُّبَيِّعِ بِنْتِ مُعَوِّذٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فَأَدْخَلَ أُصْبُعَيْهِ فِي ‏ ‏حُجْرَيْ أُذُنَيْهِ ‏","","",""],[25778,25778,"","আমরা আপনার সন্তানের জন্য আপনার পার্টনারের কথা বলেছি যে আপনার সাথে গর্ভবতী... ...যে বলছে লর্ড এসেছে... ...আর এক পয়সা তেল আর দাঙ্গার মাধ্যমে, আমি আমার হাতে কিছু বলতে চাই তুমি এটা করছ আর তুমি ভুলে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏الرُّبَيِّعِ بِنْتِ مُعَوِّذٍ ‏ ‏قَالَتْ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقِنَاعٍ ‏ ‏فِيهِ رُطَبٌ ‏ ‏وَأَجْرُ ‏ ‏زُغْبٍ ‏ ‏فَوَضَعَ فِي يَدِي شَيْئًا فَقَالَ ‏ ‏تَحَلَّيْ بِهَذَا وَاكْتَسِي بِهَذَا ‏","","",""],[25779,25779,"","আমরা বধিরদের কথা বলেছি এবং আমাদের বাবার মাংস বা তরুণদের প্রতি অভিযোগ নিয়ে আমরা কথা বলেছি। ঈশ্বর, যদি সে আমার মাথায় থাকে, ঈশ্বর তার আর আমার কনেকে আত্মসমর্পণ করতে প্রার্থনা করেছেন। তুমি আমার বাবা-মাকে মেরেছো আর তুমি আমার মাকে মেরেছো যখন তুমি বলেছিলে যে সে বলেছে যে সে বলেছে মারা গেছে এবং মারা গেছে। ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَمُهَنَّأُ بْنُ عَبْدِ الْحَمِيدِ أَبُو شِبْلٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ ذَكْوَانَ ‏ ‏قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏فِي حَدِيثِهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْحُسَيْنِ ‏ ‏عَنِ ‏ ‏الرُّبَيِّعِ ‏ ‏وَقَالَ ‏ ‏خَالِدٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏الرُّبَيِّعُ بِنْتُ مُعَوِّذِ ابْنِ عَفْرَاءَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ عُرْسِي فَقَعَدَ فِي مَوْضِعِ فِرَاشِي هَذَا وَعِنْدِي ‏ ‏جَارِيَتَانِ ‏ ‏تَضْرِبَانِ بِالدُّفِّ ‏ ‏وَتَنْدُبَانِ ‏ ‏آبَائِي الَّذِينَ قُتِلُوا يَوْمَ ‏ ‏بَدْرٍ ‏ ‏فَقَالَتَا فِيمَا تَقُولَانِ وَفِينَا نَبِيٌّ يَعْلَمُ مَا يَكُونُ فِي الْيَوْمِ وَفِي غَدٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّا هَذَا فَلَا تَقُولَاهُ ‏","","",""],[25780,25780,"","আমরা সবাই বলেছি, আমরা মারা যাওয়ার পর আমার কিছু করার কথা বলেছি। ঈশ্বরের আশীর্বাদ কামনা করেছিলাম। আমি তাকে কিস করেছি আমার কবিতার খেলা দেখে আমি খুবই অভিভূত হয়ে গিয়েছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَجْلَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلِ بْنِ أَبِي طَالِبٍ ‏ ‏عَنِ ‏ ‏رُبَيِّعَ بِنْتِ مُعَوِّذِ ابْنِ عَفْرَاءَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ عِنْدَهَا فَرَأَيْتُهُ مَسَحَ عَلَى رَأْسِهِ مَجَارِيَ الشَّعْرِ مَا أَقْبَلَ مِنْهُ وَمَا أَدْبَرَ وَمَسَحَ ‏ ‏صُدْغَيْهِ ‏ ‏وَأُذُنَيْهِ ظَاهِرَهُمَا وَبَاطِنَهُمَا ‏","","",""],[25781,25781,"","তিনি যদি আমাকে ঈশ্বরের কাছে জিজ্ঞেস করতেন, তাহলে তিনি এত মিষ্টি হতেন যে, তাকে একটা নির্দিষ্ট স্বপ্ন দেওয়া হতো । অথবা সে যেতে বলে এবং বলে আপনি এই কাজ করছেন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنِ ‏ ‏الرُّبَيِّعِ بِنْتِ مُعَوِّذِ ابْنِ عَفْرَاءَ ‏ ‏قَالَتْ ‏ ‏أَهْدَيْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قِنَاعًا ‏ ‏مِنْ رُطَبٍ ‏ ‏وَأَجْرٍ ‏ ‏زُغْبٍ ‏ ‏قَالَتْ ‏ ‏فَأَعْطَانِي مِلْءَ كَفَّيْهِ حُلِيًّا ‏ ‏أَوْ قَالَ ذَهَبًا ‏ ‏فَقَالَ تَحَلَّيْ بِهَذَا ‏","","",""],[25782,25782,"","আমরা একটা কুত্তির ছেলে আছে, যে আমাকে হত্যা করেছে, ঈশ্বর তোমার আছে, যে ঈশ্বরকে উদ্ধার করতে সক্ষম হয়েছে, সে প্রতিবারই কবিকে নিয়ে যাচ্ছে না। তার নিজের সম্পর্কে.","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلِ بْنِ أَبِي طَالِبٍ ‏ ‏عَنِ ‏ ‏الرُّبَيِّعِ بِنْتِ مُعَوِّذِ ابْنِ عَفْرَاءَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ عِنْدَهَا فَمَسَحَ الرَّأْسَ كُلَّهُ مِنْ فَوْقِ الشَّعْرِ كُلِّ نَاحِيَةٍ لِمُنْصَبِّ الشَّعْرِ لَا يُحَرِّكُ الشَّعْرَ عَنْ هَيْئَتِهِ ‏","","",""],[25783,25783,"","আমি যখন কথা বললাম, তখন আমরা একটা বিষয় নিয়ে কথা বলেছিলাম। সে ঈশ্বরের কাজ করতো, সে বিজয়ের গ্রামে পৌঁছে দিত, যে কিনা তোমার শিকারী ছিল, আমি সেটা খেয়েছিলাম। তার যমজ","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدُ بْنُ ذَكْوَانَ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏رُبَيِّعُ بِنْتُ مُعَوِّذٍ ‏ ‏قَالَتْ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قُرَى ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ ‏ ‏مَنْ كَانَ مِنْكُمْ صَائِمًا فَلْيُتِمَّ صَوْمَهُ وَمَنْ كَانَ أَكَلَ فَلْيَصُمْ بَقِيَّةَ ‏ ‏يَوْمِهِ ‏","","",""],[25784,25784,"","আমরা ঈশ্বরের কাছে যা বলেছিলাম, সেই বিষয়ে তিনি আমাদের বলেছিলেন যে, তিনি ঈশ্বরের কাছে প্রার্থনা করবেন যেন তিনি একজন পুত্র হন । আমরা যারা বড় হতে সক্ষম তাদের মধ্যে থেকে চলে এসেছি।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ ذَكْوَانَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏الرُّبَيِّعَ بِنْتَ مُعَوِّذِ ابْنِ عَفْرَاءَ ‏ ‏عَنْ صَوْمِ ‏ ‏عَاشُورَاءَ ‏ ‏فَقَالَتْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏عَاشُورَاءَ ‏ ‏مَنْ أَصْبَحَ مِنْكُمْ صَائِمًا قَالَ قَالُوا مِنَّا الصَّائِمُ وَمِنَّا الْمُفْطِرُ قَالَ فَأَتِمُّوا بَقِيَّةَ يَوْمِكُمْ وَأَرْسِلُوا إِلَى مَنْ ‏ ‏حَوْلَ ‏ ‏الْمَدِينَةِ ‏ ‏فَلْيُتِمُّوا بَقِيَّةَ يَوْمِهِمْ ‏","","",""],[25785,25785,"","হামাদ বেনের সালাদের সাথে কি হয়েছে আমরা বাবা সম্পর্কে কথা বলেছি আমি লর্ডের সাথে একটা ছেলের সাথে কাজ করেছি যে আমার প্রভুর বার্তাবাহকে ইতিমধ্যে এসেছি। এখানে আমার দুই প্রতিবেশী আছে যারা আমার বাবা-মা'কে মৃত বলে ডাকছে, যারা মারা যাচ্ছে। আপনি বলেছিলেন, যখন আপনি আমাদের বাবা জানেন যে অন্ধকার মেঘে কি হবে অথবা তুমি এটাই বলছ.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو حُسَيْنٍ ‏ ‏قَالَ ‏ ‏كَانَ يَوْمٌ لِأَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏يَلْعَبُونَ فَدَخَلْتُ عَلَى ‏ ‏الرُّبَيِّعِ بِنْتِ مُعَوِّذِ ابْنِ عَفْرَاءَ ‏ ‏فَقَالَتْ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَعَدَ عَلَى مَوْضِعَ فِرَاشِي هَذَا وَعِنْدِي ‏ ‏جَارِيَتَانِ ‏ ‏تَنْدُبَانِ ‏ ‏آبَائِي الَّذِينَ قُتِلُوا يَوْمَ ‏ ‏بَدْرٍ ‏ ‏تَضْرِبَانِ بِالدُّفُوفِ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً بِالدُّفِّ ‏ ‏فَقَالَتَا فِيمَا تَقُولَانِ وَفِينَا نَبِيٌّ يَعْلَمُ مَا يَكُونُ فِي غَدٍ فَقَالَ أَمَّا هَذَا فَلَا تَقُولَاهُ ‏","","",""],[25786,25786,"","আমরা একটি সুখী কথা লিখতে চেষ্টা করেছি আমরা একটি সময়ের প্রভুর পুত্র সম্পর্কে কথা বলেছি। আপনি প্রতিজ্ঞা করেছেন, এটা এমন নয় যে কবি তার অনুভূতি প্রকাশ করতে পারবে না। চুপ।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنِ ‏ ‏الرُّبَيِّعِ بِنْتِ مُعَوِّذٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ عِنْدَهَا فَمَسَحَ بِرَأْسِهِ الرَّأْسِ كُلِّهِ مِنْ وَرَاءِ الشَّعْرِ كُلَّ نَاحِيَةٍ لِمُنْصَبِّ الشَّعْرِ لَا يُحَرِّكُ الشَّعْرَ عَنْ هَيْئَتِهِ ‏","","",""],[25787,25787,"","আমরা রাজ্জার গুরুকে হত্যা করার চেষ্টা করেছি, তার মা আমাকে বলেছে সে আমাকে তার সাথে যুদ্ধ করতে বলেছে, আমি তার প্রভুর ক্ষমতা নিয়ে কথা বলেছি, সে আল্লাহ্‌র কাছে দিয়েছে। আর তাকে বাঁচিয়েছে, সে সকালে তার ভাইয়ের প্রাণ হারাবে, না তার বাবা, তুমি তাকে বিক্রি করবে না বলে দেবে, আর যদি সে শুনে থাকে তাহলে আমি তাকে মেরে ফেলব। ঈশ্বরের দয়ায় করা হয়েছে, ঈশ্বর সেটা করতে পারতেন, আর তিনি তার মাকে মেরে ফেলতেন। ঈশ্বর তার কাছ থেকে আত্মসমর্পণ করেছেন এবং বলেন, তাদের মধ্যে কেউ কেউ কেউ স্বাধীন। আমি আশা করি, ঈশ্বর যেন তার কাছে প্রার্থনা করেন। প্রার্থনা করো।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ إِبْرَاهِيمَ الرَّازِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلَمَةُ بْنُ الْفَضْلِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْخَطَّابِ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏قَالَتْ حَدَّثَتْنِي ‏ ‏سَلَامَةُ بِنْتُ مَعْقِلٍ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏لِلْحُبَابِ بْنِ عَمْرٍو ‏ ‏وَلِي مِنْهُ غُلَامٌ فَقَالَتْ ‏ ‏لِيَ امْرَأَتُهُ الْآنَ تُبَاعِينَ فِي دَيْنِهِ فَأَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَاحِبُ تَرِكَةِ ‏ ‏الْحُبَابِ بْنِ عَمْرٍو ‏ ‏فَقَالُوا أَخُوهُ ‏ ‏أَبُو الْيُسْرِ كَعْبُ بْنُ عَمْرٍو ‏ ‏فَدَعَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَا تَبِيعُوهَا وَأَعْتِقُوهَا فَإِذَا سَمِعْتُمْ بِرَقِيقٍ قَدْ حَسَبَنِي فَأْتُونِي أُعَوِّضُكُمْ فَفَعَلُوا فَاخْتَلَفُوا فِيمَا بَيْنَهُمْ بَعْدَ وَفَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ قَوْمٌ أُمُّ الْوَلَدِ مَمْلُوكَةٌ لَوْلَا ذَلِكَ لَمْ يُعَوِّضْهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْهَا وَقَالَ بَعْضُهُمْ هِيَ حُرَّةٌ قَدْ أَعْتَقَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَفِيَّ كَانَ ‏ ‏الِاخْتِلَافُ ‏","","",""],[25788,25788,"","আমরা একজন ডাক্তার হওয়ার অভিজ্ঞতার জীবন নিয়ে কথা বলেছি, বর্ণমালা তার কাছে প্রার্থনা করেছে আর ঈশ্বরের কাছে আমাকে সমর্পণ করেছে, আমি বিস্মিত হতে চাই, আমি কিভাবে বলতে পারি তুমি আমাকে ভালোবাসো?","‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ الْعَوَّامِ ‏ ‏عَنْ ‏ ‏هِلَالٍ يَعْنِي ابْنَ خَبَّابٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏ضُبَاعَةَ بِنْتَ الزُّبَيْرِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنِّي أُرِيدُ أَنْ أَحُجَّ فَأَشْتَرِطُ قَالَ نَعَمْ قَالَتْ فَكَيْفَ أَقُولُ قَالَ قُولِي ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ مَحِلِّي مِنْ الْأَرْضِ حَيْثُ تَحْبِسُنِي ‏","","",""],[25789,25789,"","অনেক দিন ধরে আমরা হাত মিলিয়ে কাজ করেছি, ঈশ্বর আমাদের বলেছেন, আমরা ভাল হতে পারব না। আমি তাকে বলতে চাই, এটা করা উচিত। ঈশ্বরের ইচ্ছা ছিল, আমরা একে অপরকে বলতে চাই। আমরা একে অপরের সাথে ভাল ব্যবহার করি। আমরা যদি আমাদের সম্পর্ক করি, তাহলে আমরা একে অপরের কাছে এটা করতে পারি। আমরা যদি আমাদের কাছে এটা করি, আমরা যা চাই, তা হবে, তাহলে আমরা এটা করতে চাই। আমরা কি করি? ঈশ্বর তাকে হত্যা করার আদেশ দিয়েছেন বলে তিনি তাকে হত্যা করার আদেশ দিয়েছেন ।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏وَعَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ الْفَضْلِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏ضُبَاعَةَ بِنْتِ الزُّبَيْرِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏أَنَّهَا ذَبَحَتْ فِي بَيْتِهَا شَاةً فَأَرْسَلَ إِلَيْهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أَطْعِمِينَا مِنْ شَاتِكُمْ فَقَالَتْ لِلرَّسُولِ وَاللَّهِ مَا بَقِيَ عِنْدَنَا إِلَّا الرَّقَبَةُ وَإِنِّي ‏ ‏أَسْتَحِي أَنْ أُرْسِلَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالرَّقَبَةِ فَرَجَعَ ‏ ‏الرَّسُولُ فَأَخْبَرَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ارْجِعْ إِلَيْهَا فَقُلْ لَهَا ‏ ‏أَرْسِلِي بِهَا فَإِنَّهَا هَادِيَةٌ وَأَقْرَبُ الشَّاةِ إِلَى الْخَيْرِ وَأَبْعَدُهَا مِنْ الْأَذَى ‏","","",""],[25790,25790,"","আমরা একটা বাপ্তিস্ম নেওয়ার বিষয়ে কথা বলেছিলাম কিন্তু একটা ছেলে ছিল । আমার মায়ের কাছে হাসির পাত্রী করে যে তোমাকে পরাজিত করবে... ...কারণ তুমি সেই মানুষ না যে মানুষ যে মানুষ ছিল সে একজন মানুষ যে লোক পুরুষ ও নারী মানুষকেই কামনা করে , তার জন ্ য সে একজন নির ্ ধারণ করে । যে পুরুষ পুরুষ মানুষ আছে সে একজন মানুষ যে মানুষ যে একজন মানুষ আছে তার কাছে একজন মানুষ আছে যিনি একজন মানুষ আছেন তার ছেলে আছে আমার মা আছে, যারা তোমাকে বন্দি অবস্থায় ছেড়ে যাবে। বিয়ে করে, একটা কোলে হারিয়ে সে মারা গেলে সে চলে যেত। আমার খবর হলো যে, আমি এমন একটা ছেলের সাথে বাস করি যে ভালোবাসায় বাস করে। আমি তাকে বলেছিলাম যে, তিনি তার জন্য প্রার্থনা করেন এবং তাকে আমার বাড়িতে পাঠিয়ে দেন এবং তার সঙ্গে কথা বলেন ।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أُمِّ حَرَامٍ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏بَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَائِلًا فِي بَيْتِي إِذْ اسْتَيْقَظَ وَهُوَ يَضْحَكُ فَقُلْتُ بِأَبِي وَأُمِّي أَنْتَ مَا يُضْحِكُكَ فَقَالَ ‏ ‏عُرِضَ عَلَيَّ نَاسٌ مِنْ أُمَّتِي يَرْكَبُونَ ظَهْرَ هَذَا الْبَحْرِ كَالْمُلُوكِ عَلَى الْأَسِرَّةِ فَقُلْتُ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ قَالَ اللَّهُمَّ اجْعَلْهَا مِنْهُمْ ثُمَّ نَامَ أَيْضًا فَاسْتَيْقَظَ وَهُوَ يَضْحَكُ فَقُلْتُ بِأَبِي وَأُمِّي مَا يُضْحِكُكَ قَالَ عُرِضَ عَلَيَّ نَاسٌ مِنْ أُمَّتِي يَرْكَبُونَ هَذَا الْبَحْرَ كَالْمُلُوكِ عَلَى الْأَسِرَّةِ فَقُلْتُ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ قَالَ أَنْتِ مِنْ الْأَوَّلِينَ ‏ ‏فَغَزَتْ مَعَ ‏ ‏عُبَادَةَ بْنِ الصَّامِتِ ‏ ‏وَكَانَ زَوْجَهَا ‏ ‏فَوَقَصَتْهَا ‏ ‏بَغْلَةٌ لَهَا ‏ ‏شَهْبَاءُ ‏ ‏فَوَقَعَتْ فَمَاتَتْ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أُمِّ حَرَامٍ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِي ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[25791,25791,"","তিনি তার সঙ্গে ঈশ্বরকে পাঠাতে বলেছিলেন এবং বলেছিলেন যে তিনি হয়তো তা করেছিলেন । আমার কোন ব্যাথা নেই বা তাদেরও নেই।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏جُدَامَةَ بِنْتَ وَهْبٍ ‏ ‏حَدَّثَتْهَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَقَدْ هَمَمْتُ أَنْ ‏ ‏أَنْهَى عَنْ ‏ ‏الْغِيلَةِ ‏ ‏حَتَّى ذَكَرْتُ أَنَّ ‏ ‏فَارِسَ ‏ ‏وَالرُّومَ ‏ ‏يَصْنَعُونَهُ فَلَا يَضُرُّ أَوْلَادَهُمْ ‏","","",""],[25792,25792,"","আমরা আমাদের আত্মার প্রতি দয়া দেখিয়ে কথা বলেছি, আল্লাহ বলে যে এটা হবে। এমনকি মেঘও উল্লেখ করেছে যে, এতে কোন সমস্যা হবে। তাদের সন্তানদের আঘাত করো না.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ نَوْفَلٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ ‏ ‏جُدَامَةَ بِنْتِ وَهْبٍ الْأَسَدِيَّةِ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَقَدْ هَمَمْتُ أَنْ ‏ ‏أَنْهَى عَنْ ‏ ‏الْغِيلَةِ ‏ ‏حَتَّى ذَكَرْتُ أَنَّ ‏ ‏فَارِسَ ‏ ‏وَالرُّومَ ‏ ‏يَفْعَلُونَ ذَلِكَ فَلَا يَضُرُّ أَوْلَادَهُمْ ‏","","",""],[25793,25793,"","আমরা একটি জীবন্ত ছেলের খবর চুরি করার চেষ্টা করেছি। আমরা খুশি হব যে আমার বাবা আরো একবার কথা বলবে, সে এটা বলেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ ‏ ‏جُدَامَةَ بِنْتِ وَهْبٍ الْأَسَدِيَّةِ ‏ ‏وَكَانَتْ مِنْ ‏ ‏الْمُهَاجِرَاتِ ‏ ‏الْأُوَلِ قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ ‏ ‏عَنْ ‏ ‏الْعَزْلِ ‏ ‏فَقَالَ هُوَ ‏ ‏الْوَأْدُ ‏ ‏الْخَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أبُو عَبدِ الْرَحَمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي أَيُّوبَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏فَذَكَرَهُ ‏","","",""],[25794,25794,"","আমরা একটা ছেলের সঙ্গে কথা বলেছি, যিনি তার বাবা-মা-মা'র কথা বলেছিলেন অথবা সে কিভাবে ডাক্তার হবে, আপনি বলেছেন, ঈশ্বর তার জন্য বলেছেন যে ঈশ্বর তাকে তৈরি করেছেন হে আল ্ লাহ ! বিশ ্ বজগতের পালনকর ্ তা ! বিশ ্ বজগতের পালনকর ্ তা , আল ্ লাহ ও তাঁর ফিরিশ ্ ‌ তাগণ আল ্ লাহ ্ ‌ র কাছে পরিত ্ রাণ খোঁজো , আর আল ্ লাহ ্ ‌ র নামে তোমাদের প ্ রভু ! আর আল ্ লাহ ্ ‌ র কাছে যা রয়েছে তা পুণ ্ যর ্ শন ও জ ্ ঞানময় , হে জ ্ ঞানময় আল ্ লাহ ্ ‌ র প্রভু ! হে ঈশ্বর , যিনি দেবতা , তিনি আল ্ লাহ । তিনি ব ্ যতীত কোন উপাস ্ য নেই । অতএব , তোমরা কোথায় ফিরে যাও ? প্রভু প্রভু, প্রভু প্রভু, প্রভু প্রভু, প্রভু প্রভু, প্রভু প্রভু, প্রভু প্রভু, প্রভু প্রভু, প্রভু প্রভু, প্রভু প্রভু, প্রভু প্রভু প্রভু, প্রভু প্রভু প্রভু, প্রভু প্রভু, প্রভু প্রভু, প্রভু প্রভু, প্রভু প্রভু, প্রভু প্রভু, প্রভু প্রভু, প্রভু প্রভু, প্রভু প্রভু, প্রভু প্রভু, প্রভু প্রভু, প্রভু প্রভু প্রভু, প্রভু প্রভু প্রভু, প্রভু প্রভু, প্রভু, প্রভু, প্রভু, প্রভু, প্রভু, প্রভু, প্রভু, তিনি বললেন যে, তিনি তার হাতকে শ্বাস নিন, যে মহিলা তাকে এর পাশে রাখতে পারবে। তার নিজের একটা এলাকা, আমরা যা করেছি তার থেকে সবচেয়ে ভালো বলতে হবে যে আমরা একটা ছেলের সাথে কথা বলেছি যে ওয়ার্ডেনের মা, তুমি বলবে গোসলের সময় গোসলের কথা আল্লাহ এটা রক্ষা করেছেন এবং এটা করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَبَّانُ ‏ ‏عَنْ ‏ ‏سَهْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أُمَّ الدَّرْدَاءِ ‏ ‏تَقُولُ ‏ ‏خَرَجْتُ مِنْ الْحَمَّامِ فَلَقِيَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مِنْ أَيْنَ يَا ‏ ‏أُمَّ الدَّرْدَاءِ ‏ ‏قَالَتْ مِنْ الْحَمَّامِ فَقَالَ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏مَا مِنْ امْرَأَةٍ تَضَعُ ثِيَابَهَا فِي غَيْرِ بَيْتِ أَحَدٍ مِنْ ‏ ‏أُمَّهَاتِهَا إِلَّا وَهِيَ هَاتِكَةٌ كُلَّ سِتْرٍ بَيْنَهَا وَبَيْنَ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رِشْدِينُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏زَبَّانُ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ مُعَاذٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أُمَّ الدَّرْدَاءِ ‏ ‏تَقُولُ ‏ ‏خَرَجْتُ مِنْ الْحَمَّامِ فَلَقِيَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَهُ ‏","","",""],[25795,25795,"","আমরা একটা দাড়ি সম্বন্ধে বলেছিলাম, যে কিনা সেই কাজ করার চেষ্টা করেছিল । বছর, বছরের পর বছর।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ حَلْحَلَةَ الدُّؤَلِيِّ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أُمِّ الدَّرْدَاءِ ‏ ‏تَرْفَعُ الْحَدِيثَ قَالَتْ ‏ ‏مَنْ ‏ ‏رَابَطَ ‏ ‏فِي شَيْءٍ مِنْ سَوَاحِلِ الْمُسْلِمِينَ ثَلَاثَةَ أَيَّامٍ أَجْزَأَتْ عَنْهُ ‏ ‏رِبَاطَ ‏ ‏سَنَةٍ ‏","","",""],[25796,25796,"","আমরা ঈশ্বরের ছেলের কথা বলেছিলাম আর তিনি আমাকে বলেছেন যে সে একটা খারাপ ছেলে। সে রেড শার্টের মা তার মায়ের সাথে কথা বলেছে। অনুষ্ঠান থেকে শ্রদ্ধার কথা হলো, আল্লাহকে জিজ্ঞাসা করা হয়েছে যে তিনি কি কি কি, তা জানতে হবে। কিন্তু তিনি ঈশ্বরের দোহাই এবং ছয় তারা।","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏قَالَ وَقَالَ ‏ ‏حَيْوَةُ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو صَخْرٍ ‏ ‏أَنَّ ‏ ‏يُحَنَّسَ أَبَا مُوسَى ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أُمَّ الدَّرْدَاءِ ‏ ‏حَدَّثَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقِيَهَا يَوْمًا فَقَالَ مِنْ أَيْنَ جِئْتِ يَا ‏ ‏أُمَّ الدَّرْدَاءِ ‏ ‏فَقَالَتْ مِنْ الْحَمَّامِ فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ امْرَأَةٍ تَنْزِعُ ثِيَابَهَا إِلَّا ‏ ‏هَتَكَتْ ‏ ‏مَا بَيْنَهَا وَبَيْنَ اللَّهِ عَزَّ وَجَلَّ مِنْ سِتْرٍ ‏","","",""],[25797,25797,"","আমরা বাবার ছেলে আমার মায়ের ব্যাপারে কথা বলেছি। সে বলল, ঈশ্বর তার জন্য প্রার্থনা করেন এবং তাকে মৃত্যুর অন্ধকারে উদ্ধার করেন। যদি তুমি তাকে কখনো না বলতে,\" সে ঈশ্বরকে বলে, তাহলে আমরা সেই ব্যক্তিদের থেকে রক্ষা পাব যারা এখানে এসেছে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أُمِّ مُبَشِّرٍ ‏ ‏امْرَأَةِ ‏ ‏زَيْدِ بْنِ حَارِثَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِ ‏ ‏حَفْصَةَ ‏ ‏فَقَالَ ‏ ‏لَا يَدْخُلُ النَّارَ أَحَدٌ شَهِدَ ‏ ‏بَدْرًا ‏ ‏وَالْحُدَيْبِيَةَ ‏ ‏قَالَتْ ‏ ‏حَفْصَةُ ‏ ‏أَلَيْسَ اللَّهُ عَزَّ وَجَلَّ يَقُولُ ‏ { ‏وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا ‏} ‏قَالَتْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَهْ ‏ { ‏ثُمَّ ‏ ‏نُنَجِّي الَّذِينَ اتَّقَوْا ‏}","","",""],[25798,25798,"","আমরা আমার বাবার সঙ্গে ভেড়ার সঙ্গে ঘুমের জন্য ব্যবহার করা সম্বন্ধে কথা বলেছিলাম । বন্ধু।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أُمِّ مُبَشِّرٍ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ غَرَسَ غَرْسًا أَوْ زَرَعَ زَرْعًا فَأَكَلَ مِنْهُ إِنْسَانٌ أَوْ سَبُعٌ أَوْ دَابَّةٌ أَوْ طَيْرٌ فَهُوَ لَهُ ‏ ‏صَدَقَةٌ ‏","","",""],[25799,25799,"","আমরা বাবার মায়ের সাথে প্রতারণা করা নিয়ে যুদ্ধ সম্পর্কে কথা বলেছিলাম। ঈশ্বর তাঁর কাছে প্রার্থনা করেন এবং আত্মসমর্পণ করেন এবং আমরা গ্রামের একটি দেয়ালে আছি। আমি তাদের উপর অত্যাচার করব, চলে যাবে আর সে বলবে যে তারা ঈশ্বরের কাছে দাঁড়িয়ে আছে, তাদের কবর বলছে আমরা প্রভুর নামে যেতে শিখতে পারব।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أُمِّ مُبَشِّرٍ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا فِي ‏ ‏حَائِطٍ ‏ ‏مِنْ ‏ ‏حَوَائِطِ ‏ ‏بَنِي النَّجَّارِ ‏ ‏فِيهِ قُبُورٌ مِنْهُمْ قَدْ مَاتُوا فِي الْجَاهِلِيَّةِ فَسَمِعَهُمْ وَهُمْ يُعَذَّبُونَ فَخَرَجَ وَهُوَ يَقُولُ ‏ ‏اسْتَعِيذُوا بِاللَّهِ مِنْ عَذَابِ الْقَبْرِ قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ وَإِنَّهُمْ لَيُعَذَّبُونَ فِي قُبُورِهِمْ قَالَ نَعَمْ عَذَابًا تَسْمَعُهُ الْبَهَائِمُ ‏","","",""],[25800,25800,"","আমরা তাকে বলেছিলাম যে কীভাবে আমরা আমার বাবার বিষয়ে দুটো উপায় জয় করতে পারি ।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أُمِّ مُبَشِّرٍ ‏ ‏قَالَتْ ‏ ‏جَاءَ غُلَامُ ‏ ‏حَاطِبٍ ‏ ‏فَقَالَ وَاللَّهِ لَا يَدْخُلُ ‏ ‏حَاطِبٌ ‏ ‏الْجَنَّةَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَذَبْتَ قَدْ شَهِدَ ‏ ‏بَدْرًا ‏ ‏وَالْحُدَيْبِيَةَ ‏","","",""]];
